  FT["PH-H1136"] = {"id":"PH-H1136","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1302_1955.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将本格特副省芒卡延市镇、高山省改为市的法案","en":"An Act to Convert the Municipal District of Mankayan, Sub-Province of Benguet, Mountain Province, into a Municipality","orig":"An Act to Convert the Municipal District of Mankayan, Sub-Province of Benguet, Mountain Province, into a Municipality","vi":"Đạo luật chuyển Đơn vị Hành chính Cấp Quận Mankayan, Tỉnh Phụ Benguet, Tỉnh Mountain thành Đô thị","th":"พระราชบัญญัติเปลี่ยนเขตการปกครองระดับอำเภอหมานกายันจังหวัดเบงเกตจังหวัดภูเขาเป็นเทศบาล","id":"Undang-Undang Mengubah Distrik Kota Mankayan, Subprovinsi Benguet, Provinsi Mountain, menjadi Kota","ms":"Akta Menukar Daerah Bandaran Mankayan, Subwilayah Benguet, Wilayah Mountain, kepada sebuah Bandar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1302","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-16","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1302_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1136-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Municipal District of Mankayan, Sub-province of Benguet, Mountain Province, is converted into a municipality."}},{"id":"PH-H1136-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The present mayor, vice-mayor and councilors, of the Municipal District of Mankayan shall be the mayor, vice-mayor and councilors, respectively, of the new municipality until their successors shall have been elected in the next regular election for provincial and municipal officials and shall have qualified."}},{"id":"PH-H1136-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1955."}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Convert the Municipal District of Mankayan, Sub-Province of Benguet, Mountain Province, into a Municipality","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1137"] = {"id":"PH-H1137","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1303_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Bayawan市","en":"An Act Creating the Barrios of Kalumboyan and Villareal in the Municipality of Bayawan, Province of Oriental Negros","orig":"An Act Creating the Barrios of Kalumboyan and Villareal in the Municipality of Bayawan, Province of Oriental Negros","vi":"Đạo luật thành lập Barrio Kalumboyan và Villareal tại Thị trấn Bayawan, Tỉnh Oriental Negros","th":"พระราชบัญญัติจัดตั้งบาริโอ Kalumboyan และ Villareal ในเทศบาล Bayawan จังหวัด Oriental Negros","id":"Undang-Undang membentuk Barrio Kalumboyan dan Villareal di Kotamadya Bayawan, Provinsi Oriental Negros","ms":"Akta menubuhkan Barrio Kalumboyan dan Villareal di Perbandaran Bayawan, Wilayah Oriental Negros"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1303","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1303_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1137-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Kalumboyan in the barrio of Nangka, and the sitio of Balabag in the barrio of Manihihon, Municipality of Bayawan, Province of Oriental Negros are hereby constituted into separate and independent barrios to be known as the barrios of Kalumboyan and Villareal, respectively."}},{"id":"PH-H1137-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1955."}}],"pack":"ph-p16"};
  FT["PH-H1138"] = {"id":"PH-H1138","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1304_1955.html","fetchedAt":"2026-10-06","articleCount":9,"structureMode":"ARTICLE","title":{"zh":"授予 Manila Electric 公司在菲律宾建设、维护和运营私人固定点对点及陆基无线电台与陆地移动业务以收发无线电通信的特许权法案","en":"An Act Granting the Manila Electric Company a Franchise to Construct, Maintain and Operate Private Fixed Point-to-Point and Land Based Radio Stations and Land Mobile Service for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting the Manila Electric Company a Franchise to Construct, Maintain and Operate Private Fixed Point-to-Point and Land Based Radio Stations and Land Mobile Service for the Reception and Transmission of Radio Communications Within the Philippines","vi":"Đạo luật cấp quyền khai thác cho Manila Electric Company để xây dựng, lắp đặt, vận hành và duy trì hệ thống phát thanh tại Philippines","th":"พระราชบัญญัติให้สัมปทานแก่ Manila Electric Company เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบวิทยุกระจายเสียงในฟิลิปปินส์","id":"Undang-Undang memberikan waralaba kepada Manila Electric Company untuk membangun, memasang, mengoperasikan, dan memelihara sistem penyiaran radio di Filipina","ms":"Akta memberikan francais kepada Manila Electric Company untuk membina, memasang, mengendalikan dan menyelenggara sistem penyiaran radio di Filipina"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1304","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-16","completenessNote":"全文，共 9 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1304_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1138-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to the Manila Electric Company, its successors or assigns, a franchise to construct, maintain and operate in the Philippines, at such places as the Company may select subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point and land based radio stations and land mobile service for the reception and transmission of wireless messages on radiotelegraphy or radio telephony."}},{"id":"PH-H1138-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the location of said private fixed point-to-point and land based radio stations and land mobile service on lands of the public domain upon such terms as he may prescribe."}},{"id":"PH-H1138-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee shall not engage in domestic business of telecommunications in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this franchise is to secure to the grantee the right to construct, install, maintain and operate radio stations within the Philippines as the interest of the Company and of its business may justify."}},{"id":"PH-H1138-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This franchise shall be for a period of twenty-five years from the date of its approval: Provided, That the holder of the franchise herein granted shall start the operation of said stations within one year from the approval of this Act."}},{"id":"PH-H1138-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee shall so construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H1138-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee is authorized to operate its private radio stations on the frequency and/or frequencies assigned to it by the Secretary of Public Works and Communications."}},{"id":"PH-H1138-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public, peril, calamity, or disaster to cause the closing of the grantee’s radio stations or to authorize the temporary use or possession thereof by any department of the government, upon just compensation."}},{"id":"PH-H1138-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privilege herein provided for."}},{"id":"PH-H1138-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1955."}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Manila Electric Company a Franchise to Construct, Maintain and Operate Private Fixed Point-to-Point and Land Based Radio Stations and Land Mobile Service for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1139"] = {"id":"PH-H1139","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1305_1955.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"为补充经第310号共和国法重新设立的“公地勘测与细分基金”追加拨款的法案，并旨在加快根据第630号联邦法进行的公有农业用地细分工作，以及用于其他目的","en":"An Act to Provide Additional Appropriation to Replenish the “Public Land Survey and Subdivision Fund,” as Recreated by Republic Act Numbered Three Hundred Ten, and Intended to Hasten the Subdivision of Public Agricultural Lands Under Commonwealth Act Numbered Six Hundred Thirty, and for Other Purposes","orig":"An Act to Provide Additional Appropriation to Replenish the “Public Land Survey and Subdivision Fund,” as Recreated by Republic Act Numbered Three Hundred Ten, and Intended to Hasten the Subdivision of Public Agricultural Lands Under Commonwealth Act Numbered Six Hundred Thirty, and for Other Purposes","vi":"Đạo luật cấp thêm khoản ngân sách để bổ sung Quỹ Khảo sát và Phân chia Đất công, được thành lập lại theo Đạo luật Cộng hòa số 310, nhằm đẩy nhanh việc phân chia đất nông nghiệp công cộng theo Đạo luật Liên bang số 630","th":"พระราชบัญญัติจัดสรรงบประมาณเพิ่มเติมเพื่อเติมเต็มกองทุนสำรวจและแบ่งแยกที่ดินสาธารณะซึ่งจัดตั้งขึ้นใหม่ตามพระราชบัญญัติสาธารณรัฐฉบับที่310และมีวัตถุประสงค์เพื่อเร่งการแบ่งแยกที่ดินเกษตรกรรมสาธารณะภายใต้พระราชบัญญัติเครือจักรภพฉบับที่630","id":"Undang-Undang menyediakan alokasi tambahan untuk mengisi kembali Dana Survei dan Subdivisi Tanah Publik, sebagaimana didirikan kembali menurut Undang-Undang Republik Nomor 310, dan dimaksudkan untuk mempercepat subdivisi tanah pertanian publik berdasarkan Undang-Undang Persemakmuran Nomor 630","ms":"Akta menyediakan peruntukan tambahan untuk mengisi semula Dana Ukur dan Bahagian Tanah Awam yang ditubuhkan semula mengikut Akta Republik Nombor 310 dan bertujuan mempercepat bahagian tanah pertanian awam di bawah Akta Komanwel Nombor 630"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 1305","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-16","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1305_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1139-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of twenty million pesos is hereby appropriated, out of any funds raised by the sales of bonds under Republic Act Numbered One thousand, to replenish the \"Public Land Survey and Subdivision Fund,\" as recreated by Republic Act Numbered Three hundred ten, which shall be expended by the Director of Lands with the approval of the Secretary of Agriculture and Natural Resources in carrying out the purposes of Commonwealth Act Numbered Six hundred thirty.\nThe sum of four million pesos shall be released and/or expended annually from the said fund during the period of five years for the purpose herein stated, and the balance at the end of any fiscal year shall continue to form part of the said fund and shall be available for expenditure in the next following fiscal year and other subsequent years."}},{"id":"PH-H1139-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Upon the recommendation of the Secretary of Agriculture and Natural Resources, the President shall make any amount or portion of this sum available to the Bureau of Forestry to undertake the classification and delimitation of forest lands of the public domain."}},{"id":"PH-H1139-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect as of July 1, 1954.\nApproved: June 16, 1955."}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Provide Additional Appropriation to Replenish the “Public Land Survey and Subdivision Fund,” as Recreated by Republic Act Numbered Three Hundred Ten, and Intended to Hasten the Subdivision of Public Agricultural Lands Under Commonwealth Act Numbered Six Hundred Thirty, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
