  FT["PH-H1149"] = {"id":"PH-H1149","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1315_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将北甘马磷省巴苏德市镇帕塔格小村改设为圣伊西德罗描笼涯的法案","en":"An Act Converting the Sitio of Patag to Barrio of San Isidro in the Municipality of Basud, Province of Camarines Norte","orig":"An Act Converting the Sitio of Patag to Barrio of San Isidro in the Municipality of Basud, Province of Camarines Norte","vi":"Đạo luật chuyển Sitio Patag thành Barrio San Isidro tại Thành phố trực thuộc tỉnh Basud, Tỉnh Camarines Norte","th":"พระราชบัญญัติเปลี่ยนซีเทียวปาตาคเป็นบารังไกย์ซานอิซิดโรในเทศบาลบาซุดจังหวัดกาเมรินส์นอร์เต","id":"Undang-Undang Mengubah Sitio Patag menjadi Barrio San Isidro di Kotamadya Basud, Provinsi Camarines Norte","ms":"Akta Menukar Sitio Patag kepada Barrio San Isidro di Perbandaran Basud, Wilayah Camarines Norte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1315","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1315_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1149-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Patag in the Municipality of Basud, Province of Camarines Norte, is converted into a barrio to be called San Isidro."}},{"id":"PH-H1149-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1955."}}],"pack":"ph-p16"};
  FT["PH-H1150"] = {"id":"PH-H1150","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1316_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将北甘马磷省 Capalonga 市镇的 Ilayang Basiad 小区改设为该市镇圣佩德罗描笼涯的法案","en":"An Act Converting the Sitio of Ilayang Basiad in the Municipality of Capalonga, Province of Camarines Norte, into Barrio San Pedro of Said Municipality","orig":"An Act Converting the Sitio of Ilayang Basiad in the Municipality of Capalonga, Province of Camarines Norte, into Barrio San Pedro of Said Municipality","vi":"Đạo luật chuyển đổi khu dân cư Ilayang Basiad thuộc thành phố trực thuộc tỉnh Capalonga, tỉnh Camarines Norte thành thôn San Pedro của thành phố trực thuộc tỉnh này","th":"พระราชบัญญัติเปลี่ยนแปลงสถานที่อิลายังบาเซียดในเขตเทศบาลกาปาโลงกาจังหวัดกามารีเนสโนร์เตเป็นบารังไกย์ซานเปโดรของเทศบาลดังกล่าว","id":"Undang-Undang mengubah Sitio Ilayang Basiad di Kotamadya Capalonga, Provinsi Camarines Norte menjadi Barrio San Pedro di Kotamadya tersebut","ms":"Akta menukar Sitio Ilayang Basiad dalam Perbandaran Capalonga, Wilayah Camarines Norte kepada Barrio San Pedro bagi Perbandaran berkenaan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1316","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1316_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1150-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Ilayang Basiad in the Municipality of Capalonga, Province of Camarines Norte, is converted into barrio San Pedro of said municipality."}},{"id":"PH-H1150-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1955."}}],"pack":"ph-p16"};
  FT["PH-H1151"] = {"id":"PH-H1151","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1317_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将北甘马磷省巴苏德市镇的利东、塔巴塔巴、曼蒙托伊、博拉博德、泰桑、希南帕坎、曼利蒙西托、波兰图纳与奥利瓦等聚居点改设为同名描笼涯的法案","en":"An Act Converting the Sitios of Lidong, Taba-Taba, Manmontoy, Borabod, Taisan, Hinampacan, Manlimonsito, Polantuna, and Oliva in the Municipality of Basud, Province of Camarines Norte, into Barrios of Said Municipality with the Same Names","orig":"An Act Converting the Sitios of Lidong, Taba-Taba, Manmontoy, Borabod, Taisan, Hinampacan, Manlimonsito, Polantuna, and Oliva in the Municipality of Basud, Province of Camarines Norte, into Barrios of Said Municipality with the Same Names","vi":"Đạo luật chuyển các sitio Lidong, Taba-Taba, Manmontoy, Borabod, Taisan, Hinampacan, Manlimonsito, Polantuna và Oliva thuộc thành phố trực thuộc tỉnh Basud, tỉnh Camarines Norte, thành các barrio cùng tên","th":"พระราชบัญญัติเปลี่ยนแปลงไซโต้ลีดองตาบาตาบาแมนมอนโทยโบราโบดไทซานฮินัมปาคันแมนลิมอนซิโตโปลันตูนาและโอลิวาในเทศบาลบาซุดจังหวัดกาไมรินส์นอร์เตให้เป็นบารังไกย์ที่มีชื่อเดียวกัน","id":"Undang-Undang mengubah situs Lidong, Taba-Taba, Manmontoy, Borabod, Taisan, Hinampacan, Manlimonsito, Polantuna, dan Oliva di Kotamadya Basud, Provinsi Camarines Norte, menjadi kelurahan dengan nama yang sama","ms":"Akta menukar situ Lidong, Taba-Taba, Manmontoy, Borabod, Taisan, Hinampacan, Manlimonsito, Polantuna dan Oliva di Perbandaran Basud, Wilayah Camarines Norte kepada kampung dengan nama yang sama"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1317","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1317_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1151-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Lidong, Taba-taba, Manmontoy, Borabod, Taisan, Hinampacan, Manlimonsito, Polantuna, and Oliva in the Municipality of Basud, Province of Camarines Norte, are converted into barrios of said municipality with the same names."}},{"id":"PH-H1151-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1955."}}],"pack":"ph-p16"};
