  FT["PH-H1169"] = {"id":"PH-H1169","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1335_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"对《国家国内税收法典》的修改","en":"An Act to Amend Section Seven of Republic Act Numbered Five Hundred and Eighty-Nine, Entitled “An Act to Amend Sections One Hundred and Thirty-Three, One Hundred and Thirty-Four, One Hundred and Thirty-Five, One Hundred and Thirty-Seven, One Hundred and Forty, and One Hundred and Forty-Seven of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code, as Amended”","orig":"An Act to Amend Section Seven of Republic Act Numbered Five Hundred and Eighty-Nine, Entitled “An Act to Amend Sections One Hundred and Thirty-Three, One Hundred and Thirty-Four, One Hundred and Thirty-Five, One Hundred and Thirty-Seven, One Hundred and Forty, and One Hundred and Forty-Seven of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code, as Amended”","vi":"Đạo luật sửa đổi Điều 7 của Đạo luật Cộng hòa số 589 (Bộ luật Thuế nội địa) như đã được sửa đổi","th":"พระราชบัญญัติแก้ไขเพิ่มเติมมาตรา 7 แห่งพระราชบัญญัติแห่งสาธารณรัฐที่ 589 (ประมวลรัษฎากร) ซึ่งแก้ไขเพิ่มเติมแล้ว","id":"Undang-Undang mengubah Pasal 7 Undang-Undang Republik No. 589 (Kitab Undang-Undang Pajak Dalam Negeri) sebagaimana diubah","ms":"Akta meminda Seksyen 7 Akta Republik No. 589 (Kanun Hasil Dalam Negeri) sebagaimana dipinda"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 1335","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1335_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1169-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section Seven of Republic Act Numbered Five hundred and eighty-nine, as amended by Republic Act Numbered Seven hundred and twenty-four, Republic Act Numbered Nine hundred and fifty-five, and Republic Act Numbered One thousand ninety, is further amended to read as follows:\n\"Sec. 7. The provisions of this Act shall take effect upon its approval but, unless otherwise expressly extended by Congress, the increased rates of tax provided for in this Act shall continue in force and effect until December thirty-one, nineteen hundred and fifty-seven.\""}},{"id":"PH-H1169-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1955."}}],"pack":"ph-p16"};
  FT["PH-H1170"] = {"id":"PH-H1170","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1336_1955.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"将南甘马仁省省议会所在地从纳加市迁至同省皮利市镇帕莱斯蒂纳描笼涯的法案","en":"An Act Transferring the Site of the Provincial Capitol of the Province of Camarines Sur from the City of Naga to the Barrio of Palestina, Municipality of Pili in the Same Province","orig":"An Act Transferring the Site of the Provincial Capitol of the Province of Camarines Sur from the City of Naga to the Barrio of Palestina, Municipality of Pili in the Same Province","vi":"Đạo luật chuyển địa điểm trụ sở Tòa nhà Hành chính tỉnh của tỉnh Camarines Sur từ thành phố Naga đến thôn Palestina, huyện Pili trong cùng tỉnh","th":"พระราชบัญญัติโอนสถานที่ตั้งของสำนักงานผู้ว่าราชการจังหวัดจังหวัดกามารีเนสซูร์จากนครนาคาไปยังบารังไกย์ปาเลสตินาอำเภอปีลีในจังหวัดเดียวกัน","id":"Undang-Undang memindahkan lokasi gedung kantor provinsi Provinsi Camarines Sur dari Kota Naga ke Barangay Palestina, Kotamadya Pili di provinsi yang sama","ms":"Akta memindahkan lokasi ibu pejabat kerajaan wilayah Wilayah Camarines Selatan daripada Bandar Naga ke Barangay Palestina, Perbandaran Pili dalam wilayah yang sama"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1336","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-16","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1336_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1170-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The site of the provincial capitol of the Province of Camarines Sur is hereby transferred from the City of Naga to the barrio of Palestina, Municipality of Pili, Province of Camarines Sur."}},{"id":"PH-H1170-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines is hereby authorized to select the new capitol site within the locality mentioned in section one hereof."}},{"id":"PH-H1170-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Upon approval of this Act, the capital of the Province of Camarines Sur shall be the Municipality of Pili."}},{"id":"PH-H1170-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1955."}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Transferring the Site of the Provincial Capitol of the Province of Camarines Sur from the City of Naga to the Barrio of Palestina, Municipality of Pili in the Same Province","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1171"] = {"id":"PH-H1171","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1337_1955.html","fetchedAt":"2026-10-06","articleCount":9,"structureMode":"ARTICLE","title":{"zh":"授予 Evening News 出版公司设立广播与电视无线电台特许权的法案","en":"An Act Granting the Evening News Publishing Co., Inc. a Franchise to Establish Radio Stations for Broadcasting and Television","orig":"An Act Granting the Evening News Publishing Co., Inc. a Franchise to Establish Radio Stations for Broadcasting and Television","vi":"Đạo luật cấp quyền khai thác cho Evening News Publishing Co., Inc. để xây dựng, lắp đặt, vận hành và duy trì hệ thống phát thanh và truyền hình tại Philippines","th":"พระราชบัญญัติให้สัมปทานแก่ Evening News Publishing Co., Inc. เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบวิทยุกระจายเสียงและวิทยุโทรทัศน์ในฟิลิปปินส์","id":"Undang-Undang memberikan waralaba kepada Evening News Publishing Co., Inc. untuk membangun, memasang, mengoperasikan, dan memelihara sistem penyiaran radio dan televisi di Filipina","ms":"Akta memberikan francais kepada Evening News Publishing Co., Inc. untuk membina, memasang, mengendalikan dan menyelenggara sistem penyiaran radio dan televisyen di Filipina"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1337","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-16","completenessNote":"全文，共 9 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1337_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1171-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution, the Evening News Publishing Co., Inc., is hereby granted a franchise which shall continue in force during the time that the Government has not established similar service at the places selected by the grantee, to construct, maintain and operate, for commercial purposes and in the public interest, radio broadcasting stations and stations for television in the Philippines: Provided, That this franchise shall be void unless the construction of at least one radio broadcasting station or one television station be begun within two years from the date of approval of this Act, and be completed within four years from said date: Provided, further, That the grantee shall provide adequate public service time to enable the Government, through the said radio broadcasting stations and stations for television, to reach the population on important public issues; shall assist in the functions of public information and education; shall conform to the ethics of honest enterprise; and shall not use its stations for the broadcasting and/or telecasting of obscene or indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public health, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H1171-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Such provisions of Act Numbered Thirty-eight hundred and forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes\"; Act Numbered Thirty-nine hundred and ninety-seven, known as the Radio Broadcasting Law; Commonwealth Act Numbered One hundred and forty-six, known as the Public Service Act, and their amendments, as are applicable to radio broadcasting stations shall be applied, as far as practicable, to the television stations referred to in section one."}},{"id":"PH-H1171-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee shall file a bond in the amount of fifty thousand pesos to guaranty full compliance and fulfillment of the conditions under which this franchise is granted."}},{"id":"PH-H1171-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"In the event of any completing individual, partnership or corporation receiving from the Congress a similar franchise in which there shall be any term of terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall, ipso facto, become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, partnership or corporation."}},{"id":"PH-H1171-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"(a) The grantee shall be liable to pay the same taxes on its real estate, buildings and personal property, exclusive of the franchise, as other persons or corporations are now or hereafter may be required by law to pay.\n(b) The grantee shall further be liable to pay all other taxes that may be imposed by the National Internal Revenue Code by reason of this franchise."}},{"id":"PH-H1171-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"In the event the Government should desire to maintain and operate for itself any or all of the stations herein authorized, the grantee shall turn over such station or stations to the Government with all the serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H1171-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall not require any previous censorship of any speech, play, act or scene or other matter to be broadcast and/or telecast from its stations; but if any such speech, play, act or scene or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play, act or scene or other matter: Provided, That the grantee, during any broadcast and/or telecast, may cut off from the air the speech, play, act or scene or other matter being broadcast and/or telecast if the tendency thereof is to propose and/or incite treason, rebellion or sedition, or the language used therein or the theme thereof is indecent or immoral."}},{"id":"PH-H1171-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereupon to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other company or corporation organized for the same purpose, without the previous approval of the Congress of the Philippines. Any corporation to which this franchise is sold, transferred or assigned, shall be subject to all the conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as if the franchise has been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H1171-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1955."}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Evening News Publishing Co., Inc. a Franchise to Establish Radio Stations for Broadcasting and Television","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1172"] = {"id":"PH-H1172","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1338_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"为执行第1082号共和国法目的、在1955至1956财政年度追加拨款四十万比索的法案","en":"An Act Appropriating the Sum of Four Hundred Thousand Pesos as Additional Fund to Carry Out the Purposes of Republic Act Numbered Ten Hundred Eighty-Two for the Fiscal Year Nineteen Hundred Fifty-Five to Nineteen Hundred Fifty-Six","orig":"An Act Appropriating the Sum of Four Hundred Thousand Pesos as Additional Fund to Carry Out the Purposes of Republic Act Numbered Ten Hundred Eighty-Two for the Fiscal Year Nineteen Hundred Fifty-Five to Nineteen Hundred Fifty-Six","vi":"Đạo luật cấp thêm ngân sách bốn trăm nghìn peso cho năm tài chính 1955–1956 nhằm thực hiện mục đích của Đạo luật Cộng hòa Số 1082","th":"พระราชบัญญัติจัดสรรงบประมาณเพิ่มเติมสี่แสนเปโซสำหรับปีงบประมาณ พ.ศ. 2498–2499 เพื่อดำเนินการตามวัตถุประสงค์ของพระราชบัญญัติสาธารณรัฐฉบับที่ 1082","id":"Undang-Undang tentang Pengalokasian Tambahan Empat Ratus Ribu Peso untuk Tahun Anggaran 1955–1956 guna Melaksanakan Tujuan Undang-Undang Republik Nomor 1082","ms":"Akta bagi Peruntukan Tambahan Empat Ratus Ribu Peso untuk Tahun Perakaunan 1955–1956 bagi Melaksanakan Tujuan Akta Republik Nombor 1082"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1338","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1338_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1172-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of four hundred thousand pesos is appropriated, out of any funds in the National Treasury not otherwise appropriated, as additional fund to carry out the purposes of Republic Act Numbered Ten hundred eighty-two for the fiscal year nineteen hundred fifty-five to nineteen hundred fifty-six."}},{"id":"PH-H1172-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1955."}}],"pack":"ph-p16"};
  FT["PH-H1173"] = {"id":"PH-H1173","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1339_1955.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"授予 Antonio Heras 在菲律宾境内建设、维护和运营私人固定点对点及陆基、陆上移动无线电台以收发无线电通信的临时许可的法案","en":"An Act Granting Antonio Heras a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land Based and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting Antonio Heras a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land Based and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","vi":"Đạo luật cấp giấy phép tạm thời cho Antonio Heras để xây dựng, duy trì và vận hành trạm vô tuyến cố định điểm-điểm, trên mặt đất và di động mặt đất tư nhân để nhận và truyền thông tin vô tuyến tại Philippines","th":"พระราชบัญญัติให้ใบอนุญาตชั่วคราวแก่ Antonio Heras ในการก่อสร้าง บำรุงรักษา และดำเนินการสถานีวิทยุแบบจุดต่อจุดประจำที่、ภาคพื้นดินและเคลื่อนที่ภาคพื้นดินของเอกชนสำหรับรับและส่งการสื่อสารทางวิทยุในฟิลิปปินส์","id":"Undang-Undang memberikan izin sementara kepada Antonio Heras untuk membangun, memelihara, dan mengoperasikan stasiun radio titik-ke-titik tetap, berbasis darat dan mudah alih darat swasta untuk penerimaan dan pengiriman komunikasi radio di Filipina","ms":"Akta memberikan permit sementara kepada Antonio Heras untuk membina, menyelenggarakan dan mengendalikan stesen radio titik-ke-titik tetap, berasas darat dan mudah alih darat persendirian untuk penerimaan dan penghantaran komunikasi radio di Filipina"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1339","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-16","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1339_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1173-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to Antonio Heras, proprietor of JD Transit and Taxi, his successors or assigns a temporary permit to construct, maintain and operate in the Philippines, at such places as the grantee may select, subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point and land based and land mobile radio stations for the reception and transmission of wireless messages on radiotelegraphy or radiotelephony, each station to be provided with a radio transmitting apparatus and a radio receiving apparatus."}},{"id":"PH-H1173-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established similar service at the places selected by the grantee, and is granted upon the express condition that the same shall be void unless the construction or installation of said stations be begun within one year from the date of the approval of this Act and be completed within two years from said date."}},{"id":"PH-H1173-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee, his successors or assigns, shall not engage in domestic business of telecommunications in the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, install, maintain, and operate private fixed point-to-point and land based and land mobile radio stations in such places within the Philippines as the interests of the grantee may justify."}},{"id":"PH-H1173-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"No fees shall be charged by the grantee as the radio stations that may be established by virtue of this Act shall engage in communications regarding the grantee’s business only."}},{"id":"PH-H1173-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee, his successors or assigns, shall so construct and operate his radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H1173-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, his successors or assigns, shall hold the national, provincial, city and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of his radio stations."}},{"id":"PH-H1173-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, his successors or assigns, is authorized to operate his private fixed point-to-point and land based and land mobile radio stations on the medium frequency, high frequency, and very high frequency, that may be assigned to him by the Secretary of Public Works and Communications."}},{"id":"PH-H1173-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, calamity or disaster to cause the closing of the grantee’s radio stations or to authorize the temporary use, or possession thereof by any department of the Government upon just compensation."}},{"id":"PH-H1173-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"This temporary permit shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when public interest so requires, and shall not be interpreted as an exclusive grant of the privilege herein provided for."}},{"id":"PH-H1173-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1955."}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Antonio Heras a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land Based and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1174"] = {"id":"PH-H1174","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1340_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第731号共和国法第1条、第2条、第3条、第4条与第5条，该法规定设立国家儿童医院并为此拨款的法案","en":"An Act Amending Sections One, Two, Three, Four and Five of Republic Act Numbered Seven Hundred Thirty-One Providing for the Establishment of the National Children’s Hospital and Appropriating Funds for the Purpose","orig":"An Act Amending Sections One, Two, Three, Four and Five of Republic Act Numbered Seven Hundred Thirty-One Providing for the Establishment of the National Children’s Hospital and Appropriating Funds for the Purpose","vi":"Đạo luật sửa đổi các Điều 1, 2, 3, 4 và 5 của Đạo luật Cộng hòa số 731","th":"พระราชบัญญัติแก้ไขเพิ่มเติมมาตรา 1, 2, 3, 4 และ 5 แห่งพระราชบัญญัติแห่งสาธารณรัฐที่ 731","id":"Undang-Undang mengubah Pasal 1, 2, 3, 4, dan 5 Undang-Undang Republik No. 731","ms":"Akta meminda Seksyen 1, 2, 3, 4 dan 5 Akta Republik No. 731"},"level":"law","status":"active","topics":["civil","health"],"docNumber":"Republic Act No. 1340","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1340_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1174-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections one, two, three, four and five of Republic Act Numbered Seven hundred thirty-one are hereby amended to read as follows:\n\"Sec. 1. There is hereby established under the Bureau of Hospitals, the National Children’s Hospital, which shall be under the management and supervision of a chief who must be a physician of good repute, graduate from a medical college of recognized standing and has for five years engaged in the practice of medicine. The chief of said hospital shall be appointed by the Secretary of Health, upon the recommendation of the Director of Hospitals, and shall receive a compensation of not more than six thousand pesos per annum. The chief of the National Children’s Hospital shall have all the powers conferred generally on chiefs of government hospitals.\n\"Sec. 2. It shall be incumbent upon the National Children’s Hospital to render free medical service and give accommodation gratuitously to sick and/or undernourished children, subject to the rules and regulations of the Bureau of Hospitals.\n\"Sec. 3. The chief of the National Children’s Hospital shall have the authority to promulgate, with the approval of the Director of Hospitals, such rules and regulations not inconsistent with law, as may be necessary to secure the efficient administration of the hospital and the proper enforcement of laws relating thereto.\n\"Sec. 4. With the approval of the Director of Hospitals, the chief may allow subsistence, quarters, and laundry service in kind to physicians, nurses or employees serving in the hospital whenever such actions seems advisable for the best interest of the public service.\n\"Sec. 5. Upon the approval of this Act, the existing Indigent Children’s Hospital shall be abolished and the personnel and all the files, records, supplies, equipments, properties and other assets and unexpended balances of the appropriation of said hospital shall be transferred to the National Children’s Hospital established under the provision hereof.\""}},{"id":"PH-H1174-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1955."}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Sections One, Two, Three, Four and Five of Republic Act Numbered Seven Hundred Thirty-One Providing for the Establishment of the National Children’s Hospital and Appropriating Funds for the Purpose","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1175"] = {"id":"PH-H1175","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1341_1955.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"从第1000号共和国法所授权债券发行所得款项中拨款两千万比索，用于宿务波特兰水泥公司追加资本化、煤炭资源勘探与开发及其他用途的法案","en":"An Act Appropriating the Sum of Twenty Million Pesos Out of the Proceeds of the Bond Issue Authorized by Republic Act Numbered One Thousand, for Additional Capitalization of the Cebu Portland Cement Company and the Exploration and Development of the Coal Resources, and for Other Purposes","orig":"An Act Appropriating the Sum of Twenty Million Pesos Out of the Proceeds of the Bond Issue Authorized by Republic Act Numbered One Thousand, for Additional Capitalization of the Cebu Portland Cement Company and the Exploration and Development of the Coal Resources, and for Other Purposes","vi":"Đạo luật cấp ngân sách hai mươi triệu peso từ khoản thu từ việc phát hành trái phiếu theo Đạo luật Cộng hòa số 1000 nhằm bổ sung vốn cho Công ty Xi măng Portland Cebu và thăm dò, khai thác tài nguyên than, cùng các mục đích khác","th":"พระราชบัญญัติจัดสรรเงินจำนวนยี่สิบล้านเปโซจากผลรายได้จากการออกพันธบัตรตามพระราชบัญญัติสาธารณรัฐฉบับที่1000เพื่อเพิ่มทุนให้บริษัทซีเมนต์พอร์ตแลนด์เซบูและสำรวจพัฒนาทรัพยากรถ่านหินและวัตถุประสงค์อื่น","id":"Undang-Undang mengalokasikan jumlah dua puluh juta peso dari hasil penerbitan obligasi yang diotorisasi oleh Undang-Undang Republik Nomor 1000 guna tambahan modalisasi Perusahaan Semen Portland Cebu dan eksplorasi serta pengembangan sumber daya batu bara, serta tujuan lainnya","ms":"Akta memperuntukkan jumlah dua puluh juta peso daripada hasil isu bon yang dibenarkan oleh Akta Republik Nombor 1000 untuk kapitalisasi tambahan Syarikat Simen Portland Cebu dan eksplorasi serta pembangunan sumber tenaga arang batu dan tujuan lain"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1341","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-16","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1341_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1175-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Out of the proceeds of the bond issue authorized by Republic Act Numbered One thousand, there is hereby appropriated the sum of twenty million pesos for the Cebu Portland Cement Company."}},{"id":"PH-H1175-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Of the amount appropriated under section one hereof, fifteen million pesos shall be invested to increase the capital stock of the Cebu Portland Cement Company, and five million pesos shall be utilized for the exploration and development of the country’s coal resources: Provided, However , That no portion of the latter sum shall be utilized to compete with private persons engaged in coal mining or for the exploration and/or development by the Cebu Portland Cement Company on royalty basis of coal resources leased by the Government in favor of private persons."}},{"id":"PH-H1175-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1955."}}],"pack":"ph-p16"};
  FT["PH-H1176"] = {"id":"PH-H1176","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1342_1955.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"为采购与繁育咖啡及可可种子与种苗并在成本价基础上向菲律宾种植者分发，以及为其他目的拨款十八万比索的法案","en":"An Act Providing for the Appropriation of One Hundred Eighty Thousand Pesos for the Procurement and Propagation of Coffee and Cacao Seeds and Seedlings for Distribution at Cost to Planters in the Philippines, and for Other Purposes","orig":"An Act Providing for the Appropriation of One Hundred Eighty Thousand Pesos for the Procurement and Propagation of Coffee and Cacao Seeds and Seedlings for Distribution at Cost to Planters in the Philippines, and for Other Purposes","vi":"Đạo luật cấp ngân sách một trăm tám mươi nghìn peso để mua và nhân giống hạt và cây con cà phê, ca cao nhằm phân phối với giá vốn cho nông dân trồng trọt tại Philippines, và cho các mục đích khác","th":"พระราชบัญญัติจัดสรรงบประมาณจำนวนหนึ่งแสนแปดหมื่นเปโซเพื่อจัดหาและขยายพันธุ์เมล็ดพันธุ์และต้นกล้ากาแฟและโกโก้เพื่อแจกจ่ายให้แก่ผู้ปลูกในฟิลิปปินส์ในราคาทุนและเพื่อวัตถุประสงค์อื่น","id":"Undang-Undang yang mengalokasikan jumlah seratus delapan puluh ribu peso untuk pengadaan dan pembiakan benih serta bibit kopi dan kakao guna didistribusikan dengan harga pokok kepada petani di Filipina, serta untuk maksud lain","ms":"Akta yang mengeluarkan jumlah seratus lapan puluh ribu peso bagi pengadaan dan pembiakan benih dan anak pokok kopi dan coklat untuk diedarkan pada harga kos kepada penanam di Filipina dan bagi tujuan lain"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 1342","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-16","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1342_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1176-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"To enable the Bureau of Plant Industry to advance further the implementation of the coffee and cacao development program of the National Agricultural Council, there is hereby appropriated for the said Bureau from any fund available in the National Treasury of the Philippines not otherwise appropriated, the amount of one hundred eighty thousand pesos to finance the procurement and propagation of coffee and cacao seeds and seedlings for distribution at cost to planters, and for other purposes."}},{"id":"PH-H1176-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The proceeds from the sale of coffee and cacao seeds and seedlings shall accrue to a special fund, to be known as Coffee and Cacao Development Fund, which shall be made available to the Director of Plant Industry to finance the project defined in this Act."}},{"id":"PH-H1176-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1955."}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Appropriation of One Hundred Eighty Thousand Pesos for the Procurement and Propagation of Coffee and Cacao Seeds and Seedlings for Distribution at Cost to Planters in the Philippines, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1177"] = {"id":"PH-H1177","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1343_1955.html","fetchedAt":"2026-10-06","articleCount":9,"structureMode":"ARTICLE","title":{"zh":"授予《马尼拉纪事报》在菲律宾建造、维护和运营广播电台与电视台许可的法案","en":"An Act Granting the Manila CHRonicle a Permit to Construct, Maintain and Operate Radio Broadcasting Stations and Stations for Television in the Philippines","orig":"An Act Granting the Manila CHRonicle a Permit to Construct, Maintain and Operate Radio Broadcasting Stations and Stations for Television in the Philippines","vi":"Đạo luật cấp giấy phép cho Manila Chronicle xây dựng, bảo trì và vận hành các trạm phát thanh và truyền hình tại Philippines","th":"พระราชบัญญัติอนุญาตให้หนังสือพิมพ์มะนิลาโครนิเคิลสร้าง บำรุงรักษา และดำเนินการสถานีกระจายเสียงและสถานีโทรทัศน์ในฟิลิปปินส์","id":"Undang-Undang memberikan izin kepada Manila Chronicle untuk membangun, memelihara, dan mengoperasikan stasiun penyiaran radio dan stasiun televisi di Filipina","ms":"Akta memberikan kebenaran kepada Manila Chronicle untuk membina, menyelenggara dan mengendalikan stesen penyiaran radio dan stesen televisyen di Filipina"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1343","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-16","completenessNote":"全文，共 9 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1343_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1177-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution, the Manila Chronicle is hereby granted a permit, which shall continue in force during the time that the Government has not established similar service at the places selected by the grantee, to construct, maintain and operate, for commercial purposes and in the public interest, radio broadcasting stations and stations for television in the Philippines: Provided, That this permit shall be void unless the construction of at least one radio broadcasting station or one television station be begun within two years from the date of approval of this Act, and be completed within four years from said date: Provided, further, That the grantee shall provide adequate public service time to enable the Government, through the said radio broadcasting stations and stations for television, to reach the population on important public issues; shall assist in the functions of public information and education; shall conform to the ethics of honest enterprise; and shall not use its stations for the broadcasting and/or telecasting of obscene or indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public health, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H1177-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Such provisions of Act Numbered Thirty-eight hundred and forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes\"; Act Numbered Thirty-nine hundred and ninety seven, known as the Radio Broadcasting Law; Commonwealth Act Numbered One hundred and forty-six, known as the Public Service Act, and their amendments, as are applicable to radio broadcasting stations shall be applied, as far as practicable, to the television stations referred to in section one."}},{"id":"PH-H1177-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee shall file a bond in the amount of fifty thousand pesos to guaranty for the full compliance and fulfillment of the conditions under which this permit is granted."}},{"id":"PH-H1177-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"In the event of any competing individual, partnership or corporation receiving from the Congress a similar permit in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall, ipso facto, become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, partnership or corporation."}},{"id":"PH-H1177-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"(a) The grantee shall be liable to pay the same taxes on its real estate, buildings and personal property, exclusive of the permit, as other persons or corporations are now or hereafter may be required by law to pay.\n(b) The grantee shall further be liable to pay all other taxes as provided in the National Internal Revenue Code by reason of this permit."}},{"id":"PH-H1177-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"In the event the Government should desire to maintain and operate for itself any or all of the stations herein authorized, the grantee shall turn over such station or stations to the Government with all the serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H1177-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall not require any previous censorship of any speech, play, act or scene or other matter to be broadcast and/or telecast from its stations; but if any such speech, play, act or scene or other matter should constitute a violation of the law or infringement of private right, the grantee shall be free from any liability, civil or criminal, for such speech, play, or act or scene or other matter: Provided, That the grantee, during any broadcast and/or telecast, may cut off from the air the speech, play, act or scene or other matter being broadcast and/or telecast, if the tendency thereof is to propose and/or incite treason, rebellion or sedition, or the language used therein or the theme thereof is indecent or immoral."}},{"id":"PH-H1177-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this permit nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this permit is sold, transferred or assigned, shall be subject to all the conditions, terms, restrictions and limitations of this permit as fully and completely and to the same extent as if the permit has been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H1177-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1955."}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Manila CHRonicle a Permit to Construct, Maintain and Operate Radio Broadcasting Stations and Stations for Television in the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1178"] = {"id":"PH-H1178","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1344_1955.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在八打雁省设立廷洛伊市镇的法案","en":"An Act to Create the Municipality of Tingloy in the Province of Batangas","orig":"An Act to Create the Municipality of Tingloy in the Province of Batangas","vi":"Đạo luật thành lập Thành phố trực thuộc tỉnh Tingloy thuộc Tỉnh Batangas","th":"พระราชบัญญัติจัดตั้งเทศบาลติงลอยในจังหวัดบะตังกัส","id":"Undang-Undang yang membentuk Kotamadya Tingloy di Provinsi Batangas","ms":"Akta yang menubuhkan Perbandaran Tingloy di Wilayah Batangas"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1344","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-16","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1344_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1178-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrios of Tingloy, Maricaban, Payapa, Pisa, Gamao, and Talahib are hereby separated from the Municipality of Bauan, Province of Batangas, and constituted into a separate and independent municipality to be known as the Municipality of Tingloy in the Province of Batangas. The seat of government of the newly constituted Municipality of Tingloy shall be located in the present site of the barrio of Tingloy."}},{"id":"PH-H1178-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first officials of the newly constituted Municipality of Tingloy shall be appointed by the President of the Philippines, and shall hold office until their successors shall have been elected and have qualified."}},{"id":"PH-H1178-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1955."}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Create the Municipality of Tingloy in the Province of Batangas","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1179"] = {"id":"PH-H1179","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1345_1955.html","fetchedAt":"2026-10-06","articleCount":20,"structureMode":"ARTICLE","title":{"zh":"设立国立营销公司并解散价格稳定公司的法案，为此拨款，并规定其他事项","en":"An Act Creating the National Marketing Corporation and Dissolving the Price Stabilization Corporation, Appropriating Funds Therefor, and for Other Purposes","orig":"An Act Creating the National Marketing Corporation and Dissolving the Price Stabilization Corporation, Appropriating Funds Therefor, and for Other Purposes","vi":"Đạo luật thành lập Công ty Tiếp thị Quốc gia và giải thể Công ty Ổn định Giá, cấp kinh phí cho việc này và các mục đích khác","th":"พระราชบัญญัติจัดตั้งบริษัทการตลาดแห่งชาติและยุบบริษัทการคงราคา พร้อมจัดสรรงบประมาณเพื่อวัตถุประสงค์ดังกล่าวและวัตถุประสงค์อื่น","id":"Undang-Undang mendirikan Perusahaan Pemasaran Nasional dan membubarkan Perusahaan Stabilisasi Harga, mengalokasikan dana untuk itu serta tujuan lainnya","ms":"Akta menubuhkan Syarikat Pemasaran Kebangsaan dan membubarkan Syarikat Penstabilan Harga, mengeluarkan peruntukan kewangan untuk tujuan tersebut dan tujuan lain"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 1345","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-17","completenessNote":"全文，共 20 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1345_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1179-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Declaration of Policy. It is hereby declared to be the policy of Congress to assist Filipino retailers and businessmen by supplying them with merchantable goods at prices that will enable them to compete successfully in the open market so that they may have greater participation in the distribution system of our economy. In order to do this, it is necessary that a government corporation be created for the purpose of engaging in the activities of procurement, buying and distributing merchantable goods to Filipino retailers and businessmen not for the purpose of making profit but to render an essential public service in order to promote the social and economic welfare of the Nation."}},{"id":"PH-H1179-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Name and Duration. There is hereby created a private corporation under the name of the \"National Marketing Corporation\" which, in short, shall be known as the \"NAMARCO.\" The Corporation shall exist for a period of twenty-five years from the effective date of this Act."}},{"id":"PH-H1179-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Principal Office. The Corporation shall have its main office and principal place of business in the City of Manila or Quezon City, but may establish such branches and agencies in other places, within and outside the Philippines, as may be necessary for the proper conduct of its business."}},{"id":"PH-H1179-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"General Powers. The NAMARCO is hereby authorized to exercise the following general powers:\n(a) To adopt, alter and use a corporate seal which shall be judicially noticed;\n(b) To make contracts;\n(c) To purchase, hold, convey, sell, lease, let, mortgage, encumber and otherwise deal with such real and personal property as the purposes for which the Corporation was formed may permit and the transaction of lawful business of the Corporation may reasonably and necessarily require;\n(d) To sue and be sued in any court;\n(e) To do all such other things and to transact all such business directly or indirectly necessary, incidental or conducive to the attainment of the purposes of the Corporation; and\n(f) To exercise generally all the powers of the Corporation under the Corporation Law in so far as they are not inconsistent with the provisions of this Act."}},{"id":"PH-H1179-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Special Powers. The NAMARCO is authorized and directed;\n(a) To procure and buy commodities for distribution at reasonable prices to Filipino retailers and businessmen in order to promote their greater participation in the distribution system of the national economy;\n(b) To stabilize the prices of commodities in short supply by supplying commodities to the general public at fair prices through Filipino businessmen;\n(c) To formulate policies and procedures with respect to the use and acceptance of eligible evidence of indebtedness in the sale of commodities on credit to Filipino retailers and businessmen in accordance with established business practices;\n(d) To establish and operate distribution offices and agencies and/or to enter into contracts with wholesale business throughout the Philippines for the purchase and distribution of such commodities that may be deemed essential for carrying out the purposes of the Corporation authorized in this Act.\n(e) To accept eligible evidence of indebtedness in carrying out its authorized activities and to rediscount said eligible evidence of indebtedness with the Central Bank of the Philippines, Rehabilitation Finance Corporation, Philippine National Bank and/or any other government financial institution; and\n(f) To borrow money from any credit institution for any of the purposes herein provided."}},{"id":"PH-H1179-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Capitalization and Revolving Fund. (a) The NAMARCO shall have an authorized capital of thirty million pesos to be subscribed entirely by the Republic of the Philippines and to be paid out of any general fund in the National Treasury, as follows:\nThe sum of ten million pesos upon approval of this Act; and The sum of ten million pesos for every fiscal year thereafter for a period of two years which shall be automatically appropriated and included in the General Appropriation Acts for such subsequent fiscal years. The authorized capital of thirty million pesos shall constitute as a revolving fund for the purpose of financing its business transactions, except as herein provided for.\n(b) For the operating expenses of the NAMARCO, the Board of Directors may appropriate out of the said authorized capital a sum not exceeding one million pesos during each fiscal year and a standing annual appropriation is hereby made out of any general fund in the National Treasury of such sum as may be necessary to reimburse the NAMARCO of the total amount actually expended out of the said one million pesos for overhead expenses during each fiscal year, which reimbursement shall accrue to the revolving fund. The unexpended balance of the appropriation for overhead expenses at the end of each fiscal year shall automatically revert to the said revolving fund and whatever earnings of the NAMARCO, if any, shall also accrue to the revolving fund."}},{"id":"PH-H1179-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Board of Directors Composition, Appointment and Compensation. The corporate powers of the Corporation shall be vested in and exercised by a Board of Directors of seven members, consisting of the Secretary of Commerce and Industry, as ex officio Chairman, and six members who shall be appointed by the President of the Philippines, with the consent of the Commission on Appointments. The said members shall serve as designated by the President of the Philippines in their appointments for terms of one to three years, respectively, from the date they qualify and assume office; but their successors shall be appointed for terms of three years, except that any person chosen to fill a vacancy shall serve only for the unexpired term of the member he succeeds.\nThe Board shall hold regular weekly meetings and such number of special meetings as may be called by the Chairman or any three members from time to time. For attendance at meetings, each director shall receive a per diem of twenty-five pesos: Provided , That no member of the Board shall receive more than two hundred pesos as per diems a month."}},{"id":"PH-H1179-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Powers and duties of the Board of Directors. The Board of Directors shall have the following powers and duties:\n(a) To prescribe, amend and repeal by-laws, rules and regulations governing the manner in which the general business of the Corporation may be exercised, including provisions for the formation of such committee or committees as the Board of Directors may deem necessary to facilitate its business;\n(b) To appoint and fix the compensation of the General Manager and Assistant General Manager, subject to the approval of the President of the Philippines, and to appoint and fix the compensation of a secretary of the Board and such other corporate officials as may be needed. The Board, by a majority vote of all the members, may, for cause, and with the approval of the President of the Philippines, suspend and/or remove the General Manager and/or the Assistant General Manager; and\n(c) To approve the annual budget and/or such supplementary budgets of the Corporation which may be submitted to it by the General Manager from time to time."}},{"id":"PH-H1179-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Suspension and removal of Directors. Any member of the Board of Directors may be suspended or removed by the President of the Philippines, upon the recommendation of the Chairman of the Board of Directors."}},{"id":"PH-H1179-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Prohibition for Board members. No Chairman or member of the Board of Directors of the Corporation shall at the same time serve in the Corporation in any capacity whatsoever other than Chairman or Member thereof."}},{"id":"PH-H1179-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The General Manager and members of the Board of Directors of the Corporation shall not intervene, directly, or indirectly, in the management or control of any private enterprise which in any way may be affected by the functions of their office; nor shall they, directly or indirectly, be financially interested in any contract with the Corporation or in any business activity that may be benefited by the operations of the Corporation."}},{"id":"PH-H1179-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Managing Head. The management of the Corporation shall be vested in the General Manager."}},{"id":"PH-H1179-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Powers and Duties of the General Manager. The General Manager shall have the following powers and duties:\n(a) To direct and manage the affairs and business of the Corporation, on behalf of the Board of Directors, and subject to its control and supervision;\n(b) To sit in all meetings of the Board of Directors, and participate in its deliberations, but without the right to vote;\n(c) To submit within sixty days at the close of each fiscal year an annual report, through the Board of Directors, to the President of the Philippines;\n(d) To appoint and fix the number and salaries, with the approval of the Board of Directors, of such subordinate personnel as may be necessary for the proper discharge of the duties and functions of the Corporation, and, with the approval of the Board, to remove, suspend, or otherwise discipline for cause, any subordinate employee of the Corporation; and\n(e) To perform such other duties as may be assigned to him by the Board of Directors from time to time."}},{"id":"PH-H1179-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Appointment and Promotion, basis. In the appointment and promotion of officers and employees, merit and efficiency shall serve as bases and no political test or qualification shall be prescribed and considered for such appointments or promotions. Any person appointed by the General Manager in violation of the above provision shall be removed from the service by the Board of Directors."}},{"id":"PH-H1179-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Organizational Operation. The Corporation shall be organized along the following setup:\n(a) Purchasing Department responsible for the procurement, or arranging for the procurement, of required commodities;\n(b) Marketing Department responsible for the sale and distribution of commodities through appropriate outlets;\n(c) Traffic-Storage Department responsible for the transportation, shipping and warehousing of stocks and commodities.\nIn addition, the General Manager shall have the following specified staff offices to assist him in his work:\n(a) Personnel Office provide advice and assistance on personnel management problems, including employment, training, employee relations and salary classification matters;\n(b) Finance Office provide advice and assistance on all budgeting, accounting and financial matters of the NAMARCO;\n(c) Market Analysis Office responsible for market analysis to determine necessary quantities and prices of commodities to be purchased or sold to stabilize or control prices;\n(d) General Service Office provide supply, records and building maintenance services;\n(e) Office of the General Counsel provide advice and assistance on all legal matters of the NAMARCO, including investigations and preparation of contracts. The Secretary of Justice shall be the ex officio legal adviser of the NAMARCO. He shall appoint a representative who shall be the General Counsel thereof. Any assistant legal counsel and other personnel shall be appointed by the General Manager, subject to the approval of the Board of Directors. All salaries and operating expenses of the Office of the General Counsel shall be fixed by the Board of Directors and paid by the NAMARCO.\n(f) Auditing Office responsible for the audit of the financial transactions of the NAMARCO in accordance with law, administrative regulations and the principles and procedures applicable to commercial corporate transactions. The Auditor General shall be the ex officio Auditor in charge of the Auditing Office of the NAMARCO. He shall appoint a representative who shall be the Auditor thereof. The Auditor General shall, upon the recommendation of the Auditor of the NAMARCO, appoint or remove personnel of the Auditing Office. The operating expenses of the Auditing Office and the number and salaries of officers and employees of such office shall be fixed by the Board of Directors and paid by the NAMARCO. The representative of the Auditor General shall render an annual report within sixty days after each fiscal year on the financial condition of the NAMARCO to the President of the Philippines, the Secretary of Finance, the Auditor General, and the Board of Directors. The report shall contain a statement of the resources and liabilities including earnings and expenses, the amount of paid-up capital stock, surplus, reserves, as well as losses, bad debts and such other facts which the Auditor considers necessary to accurately describe the financial condition of the NAMARCO."}},{"id":"PH-H1179-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"General Provisions. (a) Obligations issued by the NAMARCO in accordance with the authority of paragraphs (c) and (e) of section five of this Act shall be secured by the assets of the NAMARCO, including all securities held by it under the provisions of this Act. These obligations shall be redeemable at the option of the NAMARCO at or before maturity and in such manner as may be stipulated therein and shall bear such rate of interest as may be fixed by the NAMARCO. The NAMARCO shall provide for appropriate reserves for the redemption or retirement of such obligations. Obligations issued and offered for sale by the NAMARCO may be offered at such price or prices as the NAMARCO may determine. The said obligations shall and are hereby fully and unconditionally guaranteed both as to principal and interest by the Government of the Republic of the Philippines, and such guaranty shall be expressed on the face thereof.\n(b) In the event that the NAMARCO shall be unable to pay debentures, bonds, collaterals, notes or such other obligations issued by it, the Secretary of Finance shall pay the amount thereof which is hereby appropriated out of any funds in the National Treasury not otherwise appropriated and thereupon, to the extent of the amounts so paid, the Government of the Republic of the Philippines shall succeed to all of the rights of the holders of such bonds, debentures, notes, collaterals or other obligations.\n(c) The NAMARCO shall be exempt from all taxes incidental to its operation except as herein provided for. All notes, bonds and debentures and other obligations issued by the NAMARCO shall be exempt from all taxes, both as to principal and interest, except inheritance and gift taxes."}},{"id":"PH-H1179-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Penal Provisions. (a) No officer or employee of the NAMARCO nor any government official who may exercise executive or supervisory authority over the said NAMARCO, either directly or indirectly, for himself or as the representative or agent of others, shall become a guarantor, indorser, or surety for credits from the NAMARCO to others. Any such officer or employee who violates the provisions of this section shall be immediately removed by competent authority and said officer or employee shall be punished by imprisonment for not less than one year nor exceeding five years and a fine of not less than one thousand nor more than five thousand pesos.\n(b) No fee, commission, gift, or charge of any kind shall be exacted, demanded, or paid, for obtaining credit facilities from the NAMARCO, and any officer, employee, or agent of the NAMARCO, exacting, demanding, or receiving any fee for service in obtaining a credit, shall be punished by a fine of not less than one thousand nor more than three thousand pesos and imprisonment for not less than one year nor more than three years.\n(c) Any person who, for the purpose of obtaining, renewing, or increasing a credit line or the extension of the period thereof in his own or another's behalf, should give false information or cause, through his intrigue or machination, the existence and production of any false information with regard to the identity, situation, productivity, or value of the security, or with regard to a point which would effect the granting or denial of the request for credit, whether the latter has been consummated or not, and every officer or employee of the NAMARCO who, through connivance or negligence, should allow by action or omission such false information to pass unnoticed, thereby causing damage to the NAMARCO or exposing the latter to the danger of suffering such damage, shall be punished with imprisonment for not less than three months nor more than three years, and a fine of not less than the amount of the credit obtained or applied for, nor more than three times such amount.\n(d) It shall be unlawful for any officer or employee of the NAMARCO to speculate directly or indirectly in the commodity support program of the NAMARCO in the purchase of locally produced and/or manufactured goods or in transactions relating thereto, or in the purchase of imported commodities, or in the stock of membership interest or any association or corporation engaged in the handling, processing, or disposing of any such commodity or product. Any such person violating this section shall, upon conviction thereof, be fined not more than twenty thousand pesos, or imprisoned not more than ten years, or both."}},{"id":"PH-H1179-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Transitory Provisions. (a) The NAMARCO shall retain the existing regional provincial sales organization of the Price Stabilization Corporation (PRISCO): Provided, however , That as sales and distribution methods are changed or improved, any such outlets could be eliminated: Provided, further , That there shall be in each province at least one provincial sales organization or agency.\n(b) The Price Stabilization Corporation (PRISCO) is hereby dissolved in the manner hereinafter provided:\n(1) Any reference to the PRISCO in any existing law, or in any executive order, administrative order or proclamation of the President shall, with respect to any duty or function assumed by the NAMARCO created in this Act, be deemed hereafter to have reference to the National Marketing Corporation (NAMARCO);\n(2) The personnel, records, cash, such needed equipment, rights and contracts of the PRISCO involving real estate, fixed assets and stock in trade are hereby transferred to, vested in, and assumed by the NAMARCO and all the business concerning obligations and liabilities of the PRISCO on real estate, fixed assets, and stock in trade shall be liquidated, assumed and continued by the NAMARCO: Provided , That the liquidation, settlement and payment of other choses in action, obligations and liabilities of the PRISCO shall be handled by the Board of Liquidators: Provided, further , That the inventory and valuation of the real estate properties, needed equipment, fixed assets, stock in trade or choses in action, rights, obligations, liabilities and contracts of the PRISCO relative thereto shall be made by the Auditor General and during the inventory and valuation, the accountable officers of the PRISCO shall continue to be accountable therefor until actual transfer to and acceptable by the corresponding accountable officers of the NAMARCO: Provided, further , That, other assets, liabilities and obligations of the PRISCO shall be transferred to, vested in and assumed by the Board of Liquidators as hereinabove provided: Provided, finally , That the personnel of the PRISCO hereby transferred shall be reappointed in the NAMARCO in accordance with Republic Act Numbered Nine hundred ninety-seven, commonly known as the \"Reorganization Act of Nineteen hundred and fifty-four,\" and that those not reappointed within one hundred twenty days from the establishment and activation of the NAMARCO shall either be transferred to other offices or be considered separated or released from the service and that the said one hundred twenty days shall constitute as the advance separation notice required by law.\n(3) The officials and employees of the PRISCO who may be separated from the service by virtue hereof shall be entitled to the commutation of the money value of their vacation and sick leaves standing to their credit. If the officials and employees of the PRISCO so separated from the service are entitled to retire under the Osmeña Retirement Law Act (Act 2589, as amended) or under Republic Act Numbered Six hundred sixty, they shall be so retired upon the payment of the obligation of the PRISCO to the Government Service Insurance System subsisting under the said Republic Act Numbered Six hundred sixty on the date of the approval hereof. Those who may not be retired under the aforesaid laws shall be entitled to gratuity, which shall be paid in one lump sum, equivalent to one month's salary for every year of continuous, satisfactory service rendered in the PRISCO and in any branch of the government and government agencies and instrumentalities on the basis of the last salary received by them, but not exceeding twelve months in the aggregate: Provided, however , that in the case of subsequent reinstatement in the government service or in any government owned or controlled corporation of any such officer or employee who has been paid gratuity, vacation and/or sick leaves, he shall refund to the National Government the value of the unexpired portion of his gratuity and of his vacation and/or sick leaves, if any: And Provided, further , That, the amount necessary to pay the said gratuity and the money value of the sick and vacation leaves standing to the credit of the laid-off employees is hereby appropriated out of any general fund in the National Treasury not otherwise appropriated, which sum shall be used by the NAMARCO to pay such obligations."}},{"id":"PH-H1179-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Miscellaneous Provisions. (a) All Acts or Executive Orders, Administrative Orders and Proclamations or part thereof inconsistent with any of the provisions of this Act are hereby repealed or modified accordingly;\n(b) If any provisions of this Act should be held invalid, the other provisions shall not thereby be affected."}},{"id":"PH-H1179-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Effectivity. This Act shall take effect upon its approval.\nApproved: June 17, 1955."}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the National Marketing Corporation and Dissolving the Price Stabilization Corporation, Appropriating Funds Therefor, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1180"] = {"id":"PH-H1180","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1346_1955.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"进一步修正《修订行政法典》第2184条以提高市镇官员薪金最高限额的法案，并规定其他事项","en":"An Act Increasing the Maximum Limit of Salaries of Municipal Officers by Further Amending Section Twenty-One Hundred and Eighty-Four of the Revised Administrative Code, and for Other Purposes","orig":"An Act Increasing the Maximum Limit of Salaries of Municipal Officers by Further Amending Section Twenty-One Hundred and Eighty-Four of the Revised Administrative Code, and for Other Purposes","vi":"Đạo luật tăng giới hạn tối đa mức lương của cán bộ thị trấn bằng cách sửa đổi thêm Điều 2184 của Bộ Luật Hành chính Đã được Sửa đổi và các mục đích khác","th":"พระราชบัญญัติเพิ่มวงเงินสูงสุดของเงินเดือนเจ้าหน้าที่เทศบาลโดยการแก้ไขเพิ่มเติมมาตรา2184ของประมวลกฎหมายบริหารฉบับปรับปรุงและวัตถุประสงค์อื่น","id":"Undang-Undang meningkatkan batas maksimum gaji pejabat kota dengan mengubah lebih lanjut Pasal 2184 dari Kitab Undang-Undang Administrasi yang telah Direvisi dan untuk tujuan lain","ms":"Akta meningkatkan had maksimum gaji pegawai perbandaran dengan mengubah lagi Seksyen 2184 Kod Administrasi yang Telah Dikemaskini dan bagi tujuan lain"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 1346","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-17","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1346_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1180-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section twenty-one hundred and eighty-four of the Revised Administrative Code, as amended by Republic Act Numbered Five hundred and fifty-four, is further amended to read as follows:\n\"Sec. 2184. Maximum limit of salaries. — Except as otherwise specially provided in this section, the annual salaries of municipal officers shall not exceed the amounts hereinbelow fixed:\n\"In municipalities of the first class-A which have obtained during the next preceding two fiscal years an average total annual revenue of four hundred thousand pesos or more: for the mayor, five hundred four hundred pesos; for the municipal secretary, three thousand three hundred pesos; and for the municipal treasurer, four thousand five hundred pesos, of which two-thirds shall be payable out of municipal funds, in his capacity as municipal treasurer and one-third thereof out of provincial funds, in his capacity as deputy of the provincial treasurer.\n\"In other municipalities of the First Class-A: For the mayor, four thousand five hundred pesos; for the municipal secretary, two thousand seven hundred pesos; and for the municipal treasurer, three thousand nine hundred and sixty pesos, of which two-thirds shall be payable out of municipal funds, in his capacity as municipal treasurer, and one-third thereof out of provincial funds, in his capacity as deputy of the provincial treasurer.\n\"In municipalities of the First Class-B: For the mayor, four thousand three hundred pesos; for the municipal secretary, two thousand four hundred pesos; and for the municipal treasurer, three thousand seven hundred and twenty pesos, of which two-thirds shall be payable out of municipal funds, in his capacity as municipal treasurer, and one-third thereof out of provincial funds, in his capacity as deputy of the provincial treasurer.\n\"In municipalities of the first class: For the mayor, three thousand seven hundred and twenty pesos; for the municipal secretary two thousand one hundred and sixty pesos; and for the municipal treasurer, three thousand one hundred and twenty pesos, of which two-thirds shall be payable out of municipal funds, in his capacity as municipal treasurer, and one-third thereof out of provincial funds, in his capacity as deputy of the provincial treasurer.\n\"In municipalities of the second class: For the mayor, three thousand one hundred and twenty pesos; for the municipal secretary, one thousand eight hundred pesos; and for the municipal treasurer, two thousand seven hundred and sixty pesos, of which two-thirds shall be payable out of municipal funds, in his capacity as municipal treasurer, and one-third thereof out of provincial funds, in his capacity as deputy of the provincial treasurer.\n\"In municipalities of the third class: For the mayor, two thousand seven hundred and sixty pesos; for the municipal secretary one thousand five hundred and sixty pesos; and for the municipal treasurer, two thousand four hundred pesos, of which two-thirds shall be payable out of municipal funds, in his capacity as municipal treasurer, and one-third thereof out of provincial funds, in his capacity as deputy of the provincial treasurer.\n\"In municipalities of the fourth class: For the mayor, three thousand one hundred and sixty pesos; for the municipal secretary, one thousand four hundred and forty pesos; and for the municipal treasurer, one thousand nine hundred and twenty pesos, of which two-thirds shall be payable out of municipal funds, in his capacity as municipal treasurer, and one-third thereof out of provincial funds, in his capacity as deputy of the provincial treasurer.\n\"In municipalities of the fifth class: For the mayor, one thousand nine hundred and twenty pesos; for the municipal secretary, one thousand four hundred and forty pesos; and for the municipal treasurer, one thousand eight hundred pesos, of which two-thirds shall be payable out of municipal funds, in his capacity as municipal treasurer, and one-third thereof out of provincial funds, in his capacity as deputy of the provincial treasurer.\n\"With the approval of the Secretary of Finance, the annual salaries of municipal officers of a municipality which is the capital of a province or a subprovince may be fixed at rates higher than those authorized for the class to which the municipality belongs: Provided, That the salaries so fixed shall not exceed the maximum rates authorized for the corresponding officers in the next higher scale of salaries herein established unless no higher scale is provided herein, in which case, said salaries of officers of provincial and subprovincial capitals may be increased, with the approval of the Secretary of Finance by not more than three hundred and sixty pesos per annum: Provided, further, That any municipal officer whose actual salary at the time of the approval of this Act is higher than the maximum salary rate hereinabove fixed shall not suffer any decrease in pay.\"\n\"From the decisions of the provincial board with regard to salaries and per diems of municipal officers, the municipal officer or council concerned or any member of the provincial board having expressed his disconformity when the resolution objected to was passed, may appeal, and such appeal shall, within ten days after its receipt by the provincial board, be forwarded to the Secretary of Finance, whose decision shall be final.\n\" Provided, That the provincial board concerned may, in its discretion, authorize as salary of the municipal treasurer in his capacity as deputy of the provincial treasurer an amount more than the maximum rate herein fixed as payable form provincial funds, provided the corresponding maximum salary rate fixed in this Act is not exceeded.\""}},{"id":"PH-H1180-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Provincial boards and municipal councils are hereby authorized to provide in their budgets the necessary amounts as may be needed to adjust the salaries or municipal mayors, municipal secretaries, and municipal treasurers in conformity with the scale of salaries provided for in this Act. Any provision of existing laws, rules and regulations to the contrary notwithstanding, said officers shall be entitled to receive the full amount of the appropriations for their salaries which may be provided and approved in the provincial and municipal budgets in accordance with the provisions of section one hereof: Provided, That, in the case of municipal treasurer, the maximum rate of compensation authorized for his civil service eligibility is not exceeded."}},{"id":"PH-H1180-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The rates of salaries fixed in this Act notwithstanding, no increase in salaries shall be authorized until after the municipalities concerned shall have fully implemented the Minimum Wage Law."}},{"id":"PH-H1180-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Subsection (e) of section twenty-one hundred and six of the same Code and any other provisions of law, rule or regulation inconsistent with the provisions of this Act are repealed or modified."}},{"id":"PH-H1180-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The provisions of this Act shall also be applicable to the municipalities in specially-organized provinces."}},{"id":"PH-H1180-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1955."}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Maximum Limit of Salaries of Municipal Officers by Further Amending Section Twenty-One Hundred and Eighty-Four of the Revised Administrative Code, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1181"] = {"id":"PH-H1181","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1347_1955.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授予Domingo Fortuna在南伊罗戈省Candon市镇电灯、热力与动力系统特许经营权的法案","en":"An Act to Grant to Domingo Fortuna a Franchise for an Electric Light, Heat and Power System in the Municipality of Candon, Province of Ilocos Sur","orig":"An Act to Grant to Domingo Fortuna a Franchise for an Electric Light, Heat and Power System in the Municipality of Candon, Province of Ilocos Sur","vi":"Đạo luật cấp đặc quyền cho Domingo Fortuna đối với hệ thống chiếu sáng, sưởi ấm và điện lực tại Thị trấn Candon, Tỉnh Ilocos Sur","th":"พระราชบัญญัติให้สัมปทานแก่ Domingo Fortuna สำหรับระบบไฟฟ้าแสงสว่าง ความร้อน และพลังงานไฟฟ้าในเทศบาล Candon จังหวัด Ilocos Sur","id":"Undang-Undang memberikan konsesi kepada Domingo Fortuna untuk sistem penerangan, pemanas, dan tenaga listrik di Kotamadya Candon, Provinsi Ilocos Sur","ms":"Akta memberikan konsesi kepada Domingo Fortuna untuk sistem lampu, haba dan kuasa elektrik di Perbandaran Candon, Wilayah Ilocos Sur"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1347","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1347_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1181-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution there is granted to Domingo Fortuna for a period of twenty-five years from the approval of this Act, the right, privilege, and authority to construct, maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat and/or power for sale within the Municipality of Candon, Province of Ilocos Sur."}},{"id":"PH-H1181-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H1181-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that, in the event the Government should desire to maintain and operate for itself the plant and enterprise herein authorized, the grantee shall surrender his franchise and will turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H1181-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Grant to Domingo Fortuna a Franchise for an Electric Light, Heat and Power System in the Municipality of Candon, Province of Ilocos Sur","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1182"] = {"id":"PH-H1182","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1348_1955.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授予Tertuliano G. Portes在宿务省皮纳蒙加汉市镇电灯、热力与动力系统特许经营权的法案","en":"An Act Granting Tertuliano G. Portes a Franchise for an Electric Light, Heat and Power System in the Municipality of Pinamungahan, Province of Cebu","orig":"An Act Granting Tertuliano G. Portes a Franchise for an Electric Light, Heat and Power System in the Municipality of Pinamungahan, Province of Cebu","vi":"Đạo luật cấp quyền khai thác cho Tertuliano G. Portes để xây dựng, lắp đặt, vận hành và duy trì hệ thống điện tại thị xã Pinamungahan, tỉnh Cebu","th":"พระราชบัญญัติให้สัมปทานแก่ Tertuliano G. Portes เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบไฟฟ้าในเทศบาล Pinamungahan, จังหวัด Cebu","id":"Undang-Undang memberikan waralaba kepada Tertuliano G. Portes untuk membangun, memasang, mengoperasikan, dan memelihara sistem tenaga listrik di Kotamadya Pinamungahan, Provinsi Cebu","ms":"Akta memberikan francais kepada Tertuliano G. Portes untuk membina, memasang, mengendalikan dan menyelenggara sistem tenaga elektrik di Perbandaran Pinamungahan, Wilayah Cebu"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1348","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1348_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1182-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to Tertuliano G. Portes for a period of twenty-five years from the approval of this Act, the right, privilege, and authority to construct, maintain, and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat and/or power for sale within the Municipality of Pinamungahan, Province of Cebu."}},{"id":"PH-H1182-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H1182-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that, in the event the Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender his franchise and will turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H1182-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Tertuliano G. Portes a Franchise for an Electric Light, Heat and Power System in the Municipality of Pinamungahan, Province of Cebu","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1183"] = {"id":"PH-H1183","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1349_1955.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授予Cecilio Castillo在莱特省Sogod市镇电灯、热力与动力系统特许经营权的法案","en":"An Act Granting Cecilio Castillo a Franchise for an Electric Light, Heat and Power System in the Municipality of Sogod, Province of Leyte","orig":"An Act Granting Cecilio Castillo a Franchise for an Electric Light, Heat and Power System in the Municipality of Sogod, Province of Leyte","vi":"Đạo luật cấp quyền khai thác cho Cecilio Castillo để xây dựng, lắp đặt, vận hành và duy trì hệ thống điện tại thị xã Sogod, tỉnh Leyte","th":"พระราชบัญญัติให้สัมปทานแก่ Cecilio Castillo เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบไฟฟ้าในเทศบาล Sogod, จังหวัด Leyte","id":"Undang-Undang memberikan waralaba kepada Cecilio Castillo untuk membangun, memasang, mengoperasikan, dan memelihara sistem tenaga listrik di Kotamadya Sogod, Provinsi Leyte","ms":"Akta memberikan francais kepada Cecilio Castillo untuk membina, memasang, mengendalikan dan menyelenggara sistem tenaga elektrik di Perbandaran Sogod, Wilayah Leyte"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1349","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1349_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1183-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to Cecilio Castillo, for a period of twenty-five years from the approval of this Act, the right, privilege, and authority to construct, maintain, and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat, and/or power for sale within the Municipality of Sogod, Province of Leyte."}},{"id":"PH-H1183-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H1183-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that, in the event the Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender his franchise and will turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H1183-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Cecilio Castillo a Franchise for an Electric Light, Heat and Power System in the Municipality of Sogod, Province of Leyte","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1184"] = {"id":"PH-H1184","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1350_1955.html","fetchedAt":"2026-10-06","articleCount":32,"structureMode":"ARTICLE","title":{"zh":"政府运营经费拨款法","en":"An Act Appropriating Funds for the Operation of the Government of the Republic of the Philippines During the Period from July First, Nineteen Hundred and Fifty-Five to June Thirtieth, Nineteen Hundred and Fifty-Six, and for Other Purposes","orig":"An Act Appropriating Funds for the Operation of the Government of the Republic of the Philippines During the Period from July First, Nineteen Hundred and Fifty-Five to June Thirtieth, Nineteen Hundred and Fifty-Six, and for Other Purposes","vi":"Đạo luật Phân bổ Ngân sách Hoạt động của Chính phủ","th":"พระราชบัญญัติจัดสรรงบประมาณการดำเนินงานของรัฐบาล","id":"Undang-Undang Pengalokasian Anggaran Penyelenggaraan Pemerintahan","ms":"Akta Peruntukan Wang Pentadbiran Kerajaan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1350","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 32 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1350_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 33 条，缺 15）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1184-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Appropriation of funds. -The following sums, or so much thereof as may be necessary, are appropriated out of any funds in the Philippine Treasury not otherwise appropriated for the operation of the Government of the Republic of the Philippines during the period from July first, nineteen hundred and fifty-five to June thirtieth, nineteen hundred and fifty-six, except where otherwise specifically provided:\nGeneral Provisions"}},{"id":"PH-H1184-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Authority to pay salaries not in conformity with the prescribed grades or rates of compensation.— Payment to incumbent employees of salaries the rates of which are not in conformity with the schedule of grades or rates of compensation provided in section three of Commonwealth Act Numbered Four hundred and two, as amended, is hereby authorized: Provided, That new appointments, whether original or promotional, to positions not carrying the salary rates prescribed in Commonwealth Act Numbered Four hundred and two, as amended, shall be made only at rates authorized in the said Act."}},{"id":"PH-H1184-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Personnel in the classified Civil Service under Performance Budget. — The adoption of the budgetary system based on functions, activities and projects in terms of expected results in the Bureau of Civil Service, Bureau of Internal Revenue, Land Registration Commission, Bureau of Lands, Bureau of Telecommunications, Bureau of Public Libraries, Bureau of Labor, Wage Administration Service, Industrial Safety Division, Armed Forces of the Philippines, Bureau of Health and Bureau of Commerce, shall neither result in any manner in the laying off of personnel in the classified Civil Service except for cause as provided by law nor in the reduction of actual salaries of incumbent."}},{"id":"PH-H1184-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Appendix covering Plantillas of Personnel. — The appendix containing the plantillas of personnel in the different bureaus and offices whose budgets are presented pursuant to the provisions of Republic Act No. 992, is hereby made part of this Act."}},{"id":"PH-H1184-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Authority to use savings in appropriations for \"personal services,\" for \"maintenance and other operating expenses,\" and for \"furniture and equipment\" to cover deficits. -Except as otherwise provided in this Act, any savings in the regular appropriations authorized in this Act for the Executive Departments for personal services, for maintenance and other operating expenses, and for furniture and equipment of the bureaus and offices under any Department, may, with the approval of the President, be used to cover a deficit in any other item of the regular appropriations, except for personal services, under the same Department. Likewise, any savings in the appropriations for personal services, for maintenance and other operating expenses, and for furniture and equipment of any item under \"special purposes,\" may with the approval of the President, be used to cover a deficit in any other item of appropriation, except for personal services, …: Provided, That, whenever authorized positions are transferred from one program or project to another program or project under the performance budgets, the corresponding amounts appropriated for personal services are also deemed transferred, without increasing the total outlay for personal services of the office concerned. In no case, however, shall any item in the regular appropriations and appropriations for \"special purposes\" be augmented, pursuant to the authority granted in this section, by more than forty per centum of the original appropriation provided in this Act for such item."}},{"id":"PH-H1184-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Quarterly report to Congress on transfers of appropriations and accomplishments of bureaus and offices whose appropriations are based on Performance Budget. -The Auditor General and the Commissioner of the Budget shall submit separately to the Congress a quarterly report of any transfer of appropriation made to cover a deficit, the report to specify the items and the amounts involved and shall furnish copies to each member of Congress in his office: Provided, That the heads of bureaus or offices whose appropriations provided for in this Act are based on the Performance Budget shall likewise submit separately to the Congress a quarterly report of their accomplishments in the various projects as set forth in their respective performance budget."}},{"id":"PH-H1184-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Authority to use savings for other purposes. -The President of the Philippines is authorized to use any savings in the appropriations provided in this Act for the Executive Departments for the settlement of the following obligations incurred during the current fiscal year and/or previous fiscal years, the limitation in section 7-I (27) of Commonwealth Act Numbered Two hundred forty-six, as amended, notwithstanding: (1) claims under section 699 of the Revised Administrative Code and the Workmen’s Compensation Act, whichever is applicable, of officers, employees and laborers who died or were injured in line of duty; (2) commutation of the money value of the additional leave extended leave and accrued leave earned by American and deceased Filipino officers and employees, or by Filipino officers and employees separated from the service except for cause, for service rendered prior to November twenty-ninth, nineteen hundred and twenty-six; (3) purchase of furniture and equipment to replace those that may be lost through accident, fire or other calamity, or may have been damaged through the same cause, the disposal of which is deemed reasonable and necessary, if it would be more expensive to have them repaired, and purchase with the approval of the President of furniture and equipment to replace unserviceable ones condemned by the Auditor General; (4) payment of salaries of suspended employees who have subsequently been exonerated; (5) payment of the share of the National Government in the salaries of national officials in newly created cities and provinces where no appropriation has been provided therefor; (6) three per cent contribution of the Government to the Government Service Insurance System for the employee’s insurance premiums corresponding to the period from December thirty-first, nineteen hundred and forty-one to February twenty-eight, nineteen hundred and forty-five, pursuant to section four of Republic Act Numbered One hundred thirty-two, the provisions of section 7 (c) of Commonwealth Act Numbered One hundred eighty-six, as amended, to the contrary notwithstanding; (7) commutation of sick and vacation leaves of employees who may be retired under existing laws; (8) additional compensation to government nurses assigned to public health nursing at ₱50 a month in lieu of quarters, subsistence and laundry allowances as provided under section three of Republic Act Numbered Six hundred forty-nine; (9) purchase or rental of accounting machines to carry out the plan of mechanizing the accounting system in the Government; (10) obligation of the National Government under the provisions of subsection (a) of section 2553 of the Revised Administrative Code; (11) cash commutation of the accumulated vacation and sick leave of employees who voluntarily resign or are separated from the service thru no fault of their own, in accordance with the provisions of Republic Act Numbered Six hundred eleven; (12) printing of briefs in cases appealed by the Government; (13) gratuity of employees whose positions are abolished or who are retired; (14) improvement of food rations in government hospitals and leprosaria; (15) rural improvement; and (16) payment of salary differentials to officials and employees whose salary items have been reduced in the 1956 Budget to the amounts they were actually receiving at the time of the preparation of the said Budget but who before June 30, 1955 were promoted to higher rates provided for their respective salary items."}},{"id":"PH-H1184-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Suspension of expenditure of appropriations. -Except as otherwise provided in this Act and whenever in his judgment the public interest so requires, the President is authorized to suspend or otherwise stop the expenditure of any amount herein appropriated in any item or items for the Executive Departments for any purpose, except those for salaries of positions with incumbents, and thereupon the funds affected by such action shall become available for any other expenditures authorized in this Act for the Executive Departments as the President may determine, except for personal services: Provided, That, whenever authorized positions are transferred from one program or project to another program or project under the performance budgets, the corresponding amounts appropriated for personal services are also deemed transferred, without increasing the total outlay for personal services of the office concerned. In no case, however, shall any item of appropriation be augmented, pursuant to the authority granted in this section, by more than forty per centum of the original appropriation provided in this Act for such item. The Auditor General and the Commissioner of the Budget shall report separately to the Congress within a period of thirty days any suspension or transfer of funds made by the President during the previous quarter and shall furnish copies to each member of Congress in his office."}},{"id":"PH-H1184-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Provision for \"excess of actual salary\". -Appropriations provided in this Act may be used for payment of excess of actual salaries to the incumbent of a position to which said \"excess\" pertains who is actually receiving the same \"excess\" as part of the salary granted to him upon his appointment to the said position before the reduction of the basic pay thereof to the amount provided: Provided, However, That if the position be vacated and the successor to its previous incumbent shall have previously received an equal salary plus the \"excess of actual salary\" in the same or any other branch of the government service, such excess shall be allowable to him."}},{"id":"PH-H1184-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Allotment of Appropriations. -To prevent the incurrence of deficits, authorized appropriations shall be allotted in accordance with the procedure outlined hereunder:\na. No appropriation authorized for any department or agency shall be available for expenditure until the head of such department or agency shall have submitted to the Commissioner of the Budget a request for allotment of funds, showing the estimated amounts needed for each function, activity or purpose for which the funds are to be expended during the applicable allotment period and until the request shall have been approved by the Commissioner of the Budget as hereinafter provided. The form of the request for allotment shall be prescribed by the Commissioner of the Budget and shall be submitted to him at least twenty-five days prior to the beginning of the fiscal year showing the proposed quarterly allotments of the whole authorized appropriation for the department or agency.\nb. For purposes of the administration of the allotment system herein provided, each fiscal year shall be divided into four quarterly allotment periods beginning, respectively, on the first day of July, October, January and April: Provided, That in any case where the quarterly allotment period is found to be impracticable, the Commissioner of the Budget may prescribe a different period suited to the circumstances but not extending beyond the end of the fiscal year.\nc. Each request for allotment shall be reviewed by the Commissioner of the Budget and the respective amounts therein shall be allotted for expenditures, provided the estimate therein is within the terms of the appropriations as to amount and purpose, having due regard for the probable future needs of the bureau, office or agency for the remainder of the fiscal year or other term for which the appropriation was made, and provided the bureau, office or agency contemplates expenditure of the allotment during the period. Otherwise, the said Commissioner of the Budget shall modify the estimate so as to conform with the terms of the appropriation and the prospective needs of the bureau, office or agency, and shall reduce the amount to be allotted accordingly. The Commissioner of the Budget shall act promptly upon all requests for allotment and shall notify every bureau, office or agency of its allotments at least five days before the beginning of each allotment period. The total amount allotted to any bureau, office or agency for the fiscal year or other term for which the appropriation was made shall not exceed the amount appropriated for said year or term. The notification which will be sufficient authority for the Accounting Officer to enter the allotment in the books, shall include an explanation for any decrease or increase in the request of the head of the department or agency.\nd. At the end of each quarter, each department or agency must report to the Commissioner the current status of its appropriations, the cumulative allotments, obligations, expenditures, and unliquidated obligations and unobligated and unexpended balances, and the results of expended appropriations. Such department or agency may, at any time, initiate or request for a change in allotments in order to adapt its functions or activities to altered conditions.\ne. The Commissioner of the Budget shall have authority also at any time to modify or amend any allotment previously made by him. In case he shall find at any time that the probable receipts from taxes or other sources for any fund will be less than were anticipated and that as a consequence the amount available for the remainder of the term of the appropriation, or for any allotment period will be less than the amount estimated or allotted therefor, he shall, with the approval of the President, and after notice to the department or agency concerned, reduce the amount or amounts to be allotted, so as to prevent deficits.\nf. The Commissioner of the Budget shall promptly transmit records of all allotments and modifications thereof to the Auditor General, the Chairman of the Committee on Finance of the Senate, the Chairman of the Committee on Appropriations and the Chairman of the Committee on Ways and Means of the House of Representatives, and the Secretary of Finance.\ng. The Commissioner of the Budget shall maintain control records showing quarterly by funds, accounts, and other pertinent classifications, the amounts appropriated, the estimated revenues, the actual revenues or receipts, the amounts allotted and available for expenditures, the unliquidated obligations, actual balances on hand, and the unencumbered balances of the allotments for each agency of the Government.\nh. No funds shall be disbursed and no expenditures or obligation chargeable against any authorized allotments shall be incurred or authorized by any head of department or agency, without first securing the certification of the corresponding accounting officers of the Budget Commission as to the availability of funds and allotment or appropriation against which the expenditure or obligation may properly be charged, after taking into consideration all previous expenditures and outstanding obligations.\ni. Every expenditure or obligation authorized or incurred in violation of the provisions of this Act shall be void. Every payment made in violation of said provisions shall be illegal, and every officer of employee authorizing or making such payment, or taking part therein, and every person receiving such payment, or any part thereof, shall be jointly and severally liable to the Government for the full amounts so paid or received. If any officer or employee of the Government shall knowingly incur any obligation or shall authorize or make any expenditure in violation of the provisions of this Act, or take part therein, it shall be ground for his removal by the officer appointing him, and if the appointing officer be other than the President and shall fail to remove such officer or employee, the President shall exercise such power of removal after giving notice of the charges and opportunity for hearing thereon to the accused officer or employee and to the officer appointing him.\nj. Since the effective operation of the allotment system with respect to the appropriations authorized in this Act is affected by the appropriations authorized in other Acts, the provisions of this section relating to the allotment system are hereby made expressly applicable to other appropriations and funds of all kinds, including standing or continuing appropriations, and special, trust and other funds; but the provisions hereof relating to the allotment system shall not apply to appropriations for the Congress of the Philippines, Supreme Court, Court of Appeals, Courts of First Instance and Justice of the Peace Courts nor to appropriations or any other monies made available for the General Auditing Office and the Commission on Elections."}},{"id":"PH-H1184-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Creation of appropriation reserves. -The chiefs of bureaus and offices shall establish reserves of not less than five per centum of the total appropriations of their respective bureaus and offices to provide for contingencies and emergencies which would otherwise require a deficiency appropriation. All or a portion of an appropriation may be reserved when it is determined that the amounts involved may not be needed. Should conditions change during the fiscal year which would justify the use of the reserve, the necessary adjustment may be made by the Commissioner of the Budget when requested by the bureau or office affected."}},{"id":"PH-H1184-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Purchase of locally manufactured furniture, equipment, parts, accessories, supplies and materials. -All appropriations for the purchase of furniture, equipment, supplies and materials authorized in this Act shall be available only for locally manufactured furniture, equipment, parts, accessories, supplies and materials, except when none is available in the market, or when the prices of the locally manufactured article exceed those determined by the Flag Law by ten per cent."}},{"id":"PH-H1184-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Renting of automobiles, jitneys or trucks for a continuous period exceeding fifteen days prohibited. -No appropriation provided in this Act for the Executive Departments shall be used for renting automobiles, jitneys or trucks on the monthly basis nor on the daily basis for a continuous period exceeding fifteen days."}},{"id":"PH-H1184-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Authority to purchase motor vehicles. -No appropriation authorized in this Act shall be used for the purchase of automobiles, jitneys, jeeps, station wagons, motorcycles and other motor vehicles unless otherwise specifically provided in this Act.\nSection 15 . Officials entitled to government motor transportation. -The following officials are entitled to use government motor transportation chargeable against the appropriations authorized in this Act:\n(1) The President of the Philippines,\n(2) The Vice-President of the Philippines,\n(3) The President of the Senate,\n(4) The Speaker of the House of Representatives,\n(5) The President Pro-Tempore of the Senate,\n(6) The Majority Floor Leader of the Senate,\n(7) The Chairman, Committee on Finance of the Senate,\n(8) The Chairman, Committee on Accounts of the Senate,\n(9) The Chairman, Committee on Foreign Relations of the Senate,\n(10) The Chairman, Committee on Public Works of the Senate,\n(11) The Minority Floor Leader of the Senate,\n(12) The Secretary of the Senate,\n(13) The Speaker Pro-Tempore of the House of Representatives,\n(14) The Majority Floor Leader of the House of Representatives,\n(15) The Chairman, Committee on Appropriations of the House of Representatives,\n(16) The Chairman, Committee on Accounts of the House of Representatives,\n(17) The Chairman, Committee on Foreign Affairs of the House of Representatives,\n(18) The Chairman, Committee on Public Works of the House of Representatives,\n(19) The Minority Floor Leader of the House of Representatives,\n(20) The Secretary of the House of Representatives,\n(21) The Chief Justice of the Supreme Court,\n(22) The Presiding Justice of the Court of Appeals,\n(23) The Auditor General,\n(24) The Ambassadors, Ministers Plenipotentiary and Consuls in charge of consulates while in their respective stations abroad, and\n(25) The Chief of Staff and the Vice-Chief of Staff and the Commanding Officers of the other Major Services of the Armed Forces of the Philippines."}},{"id":"PH-H1184-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Officials entitled to transportation allowance. -The Department Heads, including the Administrator of Economic Coordination, the Commissioner of the Budget, the Chairman of the Commission on Elections, and the Social Welfare Administrator are hereby granted a commutable transportation allowance of two hundred fifty pesos each per month; the Undersecretaries of Departments and officials with the same rank, the Public Service Commissioner, the Legislative Secretary, the Legislative Liaison Officer, the Presiding Judge of the Court of Industrial Relations, and the Presiding Judge of the Court of Tax Appeals, two hundred pesos each per month, and the following Directors or chiefs of bureaus and offices, and the Sergeant At Arms of the House of Representatives, one hundred pesos each per month, chargeable against the appropriations authorized in this Act for their respective offices:\n(1) The Director of Printing,\n(2) The Commissioner of Civil Service,\n(3) The Commissioner of Customs,\n(4) The Collector of Internal Revenue,\n(5) The Treasurer of the Philippines,\n(6) The Purchasing Agent, Bureau of Supply,\n(7) The Insurance Commissioner,\n(8) The Commissioner, Land Registration Commission,\n(9) The Director, National Bureau of Investigation,\n(10) The Commissioner of Immigration,\n(11) The Director of Prisons,\n(12) The Chairman, Code Commission,\n(13) The Director of Plant Industry,\n(14) The Director of Animal Industry,\n(15) The Director of Forestry,\n(16) The Director of Lands,\n(17) The Director of Mines,\n(18) The Director of Fisheries,\n(19) The Director of Soil Conservation,\n(20) The Director of Agricultural Extension,\n(21) The Manager, Fiber Inspection Service,\n(22) The Director of Public Works,\n(23) The Director of Posts,\n(24) The Director of Telecommunications,\n(25) The Chief, Motor Vehicles Office,\n(26) The Commissioner of Public Highways,\n(27) The Director of Public Schools,\n(28) The Director of Public Libraries,\n(29) The Director, Institute of National Language,\n(30) The Director of National Museum,\n(31) The Director of Private Schools,\n(32) The Director of Labor,\n(33) The Commissioner, Workmen’s Compensation Commission,\n(34) The Chief Wage Administration Service,\n(35) The Captain (Director), Bureau of Coast and Geodetic Survey,\n(36) The Chairman, Philippine Veterans Board,\n(37) The Chairman, Board on Pensions for Veterans,\n(38) The Director of Quarantine,\n(39) The Director of Hospitals,\n(40) The Director of Health,\n(41) The Director of Commerce,\n(42) The Administrator, Sugar Quota Administration,\n(43) The Director, Patent Office,\n(44) The Commissioner, Securities and Exchange Commission,\n(45) The Administrator, Civil Aeronautics Administration,\n(46) The Director, Weather Bureau,\n(47) The Director of the Census and Statistics,\n(48) The Administrator, Cooperatives Administration Office,\n(49) The Director, Institute of Science and Technology,\n(50) The Director, Philippine General Hospital,\n(51) The Counselors in the Department of Foreign Affairs, and\n(52) The Chief, Irrigation Service Unit."}},{"id":"PH-H1184-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Bureaus and offices entitled to use, operate and maintain government motor vehicles and launches. -No bureau or office shall use, operate or maintain from the appropriations authorized in this Act government service cars, jeeps, station wagons, vans, service trucks, pick-up trucks, launches, speedboats, motorcycles, etc., except the following:\n(1) The House of Representatives, for general service purposes;\n(2) The Senate, for general service purposes;\n(3) Malacañang, for general service purposes;\n(4) The National Intelligence Coordinating Agency, in the coordination of the national intelligence activities and in carrying out its functions in the interest of national security;\n(5) The Radio Station DZFM, for covering special events for delayed broadcasts, servicing of sponsored programs, contacting artists, fetching \"sign on\" personnel and conducting home those \"signing off;\"\n(6) The Social Welfare Administration, for ministering relief, during military actions against dissidents, to evacuees, the injured and incapacitated and to the victims of typhoons, earthquakes, fires, floods, tidal waves and volcanic eruptions; and for conducting the inmates of Welfareville to and from the Courts, hospitals and other offices procuring materials and food supplies for their subsistence, and delivering food to the various units within the Welfareville compound, including collection and disposal of garbage;\n(7) The Budget Commission, for the gathering from the various government offices and instrumentalities of such data and information as are essentially material or pertinent to the exercise of authority over budget operations and control, for the performance of duties connected with the preparation of the National Budget, and for wage and position classification survey;\n(8) The Bureau of Printing, for the delivery and/or shipment of printed matters, books and/or forms to various offices;\n(9) The Department of Foreign Affairs, for carrying out protocol duties in connection with the arrival or visit in the Philippines of high dignitaries and officials or accredited representatives of foreign governments, and for the delivery of diplomatic pouches to and from points of embarkation or shipment;\n(10) The Bureau of Customs, for use of examiners of the Appraisers Division in the inspection of bonded warehouses, including embroidery factories, for hauling parcels from the Bureau of Posts to the Customs Building for examination, and for carrying out the so-called \"immediate payment system\" under which the Division will dispatch in a motor vehicle import entries for examination to its supervisors stationed at the piers for distribution to the examiners detailed under them and have the examined entries and the examiner’s samples brought to the Customs Building, and for carrying out detective and police duties of the Port Patrol Division in Manila and of the patrol service in the Port of Cebu;\n(11) The Bureau of Internal Revenue, for the strict enforcement of the internal revenue laws and regulations and detection of violations thereof;\n(12) The Bureau of the Treasury, for transportation of cash from the Central Bank of the Philippines to the Bureau of the Treasury, and vice versa;\n(13) The National Bureau of Investigation, for detection and investigation of crimes and criminals and other law violations;\n(14) The Court of Tax Appeals, for transportation of its personnel whenever the Court holds its hearing outside of the City of Manila pursuant to Section 6 of Republic Act No. 1135;\n(15) The Bureau of Prisons, for conducting prisoners to and from the Bureau of Prisons, inspection of prison institutions and stations, procuring food supplies and materials, and delivering products and/or manufactures of the Prison Industries in Muntinlupa and in the penal colonies;\n(16) The Division of Agricultural Economics, Office of the Secretary of Agriculture and Natural Resources, for gathering agricultural statistics for researches and analyses in agriculture;\n(17) The Division of Agricultural Information, Office of the Secretary of Agriculture and Natural Resources, for distribution of agricultural information materials for guidance of farmers in improving their farming methods;\n(18) The Agricultural Tenancy Commission, for conducting education rallies, researches on tenancy practices observed in the different regions of the country, and for inspection of farm mechanization;\n(19) The Bureau of Plant Industry, for the control of abaca mosaic and other plant pests and diseases, including demonstration and extension work;\n(20) The Bureau of Animal Industry, for the distribution of animal products and transportation of animals and feeds, including insemination of work;\n(21) The Bureau of Forestry, for the distribution of seedlings and transportation of supplies and materials and cinchona barks to ports of shipment;\n(22) The Bureau of Lands, for the survey and subdivision of public agricultural lands and land management;\n(23) The Bureau of Mines, for the transportation of mineral samples to and from the office for the geological, mineralogical and mineral land survey parties operating in the different parts of the Philippines;\n(24) The Bureau of Fisheries, for the collection of marine specimens, inspection of experimental fish farms and distribution of seedlings;\n(25) The Bureau of Soil Conservation, for carrying out soil survey and conservation work in the different regions of the country;\n(26) The Bureau of Agricultural Extension, for carrying out its extension work and diffusing among the people, particularly those in rural areas, useful and practical information on agriculture, soil conservation, livestock, fisheries, forest conservation, public lands and natural resources laws, home economics and rural life by means of field demonstrations, lectures, conferences, publications and other means of disseminating information;\n(27) The Fiber Inspection Service, for carrying out its work of inspection and supervision of fiber grading-baling establishments, fiber improvement and demonstration work;\n(28) The Bureau of Public Works, for undertaking the construction of public works projects, inspection and supervision thereof, and for the procurement of construction supplies and materials;\n(29) The Bureau of Posts, for the transportation of strictly mail matters;\n(30) The Bureau of Telecommunications, for the construction, repair, transfer and maintenance of telegraph, telephone and radio stations and circuits and the delivery of telegrams and radiograms;\n(31) The Motor Vehicles Office, for the enforcement of the provisions of the Motor Vehicle Law;\n(32) The Wage Administration Service, for use by regional wage inspection supervisors in supervising the enforcement of the Minimum Wage Law, in the inspection of agricultural, industrial and commercial establishments, especially in out-of-the-way locations, and in making special investigations and economic surveys necessary for the administration and enforcement of the law;\n(33) The vocational schools, for instructional purposes requiring the use, demonstration and/or operation of motor or other powered vehicles;\n(34) The Bureau of Private Schools, for the inspection of private schools that are out-of-the-way places, and for undertaking rush investigation of complaints from various sources;\n(35) The Bureau of Coast and Geodetic Survey, for carrying out field reconnaissance, triangulations, precise leveling and magnetic and gravity measurements and for ship servicing;\n(36) The Armed Forces of the Philippines, when on military operations or on active duty in the restoration and maintenance of peace and order;\n(37) The Department of Health, for the use of the Division of Tuberculosis in BCG Vaccination and Traveling X-ray Examination Units, the Division of Health Education and Information in exhibiting health films and the Public Health Research Laboratories in connection with health research, including the distribution of vaccines, sera and other biological preparations;\n(38) Government hospitals, for ambulance service and procuring food supplies and materials for the subsistence of patients and personnel entitled thereto;\n(39) The Bureau of Health, for health, sanitation and prevention and control of epidemics;\n(40) The Bureau of Quarantine, whenever used by quarantine officers exclusively for quarantine work;\n(41) The Civil Aeronautics Administration, for the operation and maintenance of its landing fields, including supervision and reconstruction or repair of signaling equipment located thereat;\n(42) The Weather Bureau, for the maintenance, operation and inspection of its meteorological stations, including the Manila International Airport Forecasting Center and the Diliman Geophysical and Astronomical Station, and delivery of supplies thereto;\n(43) The Office of Economic Coordination, for use in inspecting projects being undertaken by government corporations, including private industrial establishments applying for tax exemption under Republic Act Numbered Thirty-five, and in gathering and transmitting data and information necessary for the efficient supervision and coordination of the activities of the said corporations;\n(44) The Institute of Science and Technology, for visit and inspection of factories, for the collection of forest, plant, animal and marine by-products and agricultural wastes for use in research and laboratory investigations, including survey of sources of raw materials in different regions;\n(45) The General Auditing Office, for the inspection of the delivery of equipment and supplies and materials to the various bureaus and offices of the Government, as well as to sites of public works construction, and for surprise examinations of disbursing officers;\n(46) The Commission on Volcanology, for inspecting and observing volcanoes and warning people in danger areas; and\n(47) The Philippine Council for United States Aid (PHILCUSA), for use in inspecting projects being undertaken by the Government jointly with the Foreign Operations Administration (FOA) and in gathering and transmitting data and information necessary for the efficient supervision and coordination of the activities of said projects."}},{"id":"PH-H1184-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Proper use of government motor vehicles. -The use of government motor vehicles by bureaus and offices for the purposes enumerated in section seventeen hereof shall be authorized only through the issuance for each trip of a serially numbered ticket, duly signed by the chief or the administrative officer of the bureau or office concerned. These motor vehicles shall be used strictly for official business, bear government plates only and after office hours kept in the garage provided therefor by the bureau of office to which they belong, except when in use for strictly official business outside office hours."}},{"id":"PH-H1184-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Use of more than one motor vehicle prohibited. -With the exception of the President, no government official or employee authorized to use any vehicle operated and maintained from the funds appropriated in this Act shall be allowed to use more than one such motor vehicle: Provided, However, That the Vice-President, the President of the Senate, and the Speaker of the House of Representatives may be allowed to use two motor vehicles each: And Provided, finally, That no official who has been furnished motor transportation by any government corporation shall be allowed to use motor vehicle transportation operated and maintained from funds appropriated in this Act.\nThe Auditor General is hereby empowered to issue rules and regulations for the proper implementation and enforcement of the provisions of this section and sections 16, 17 and 18."}},{"id":"PH-H1184-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Disposition of motor vehicles not used by a bureau or office. — All motor vehicles owned by or assigned to the different departments, bureaus, offices and branches of the National Government not needed by the officials and for the purposes enumerated in section fifteen and seventeen of this Act shall be disposed of to the highest bidder at public auction sales announced in newspapers of general circulation at least ten days before the sale: Provided, That the former user thereof shall be given preference if he offers and pays a price equal to that of the highest bid by others."}},{"id":"PH-H1184-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Prohibition against the use of appropriations for the payment of salaries and wages of officers or employees engaged in a strike against the Government. -Subject to existing civil service rules and regulations and the proper administrative proceedings, no part of the funds of, or available for expenditure by, any agency included in this Act shall be used to pay the salary or wages of any officer or employee who engages in a strike against the Government of the Republic of the Philippines or who is a member of an organization of government employees that in the opinion of the Secretary of Justice asserts the right to strike against the Government of the Republic of the Philippines, or who in the opinion of said Secretary of Justice advocates, or is a member of an organization that advocates, the overthrow of the Government of the Republic of the Philippines by force or violence; Provided, That for the purposes hereof an affidavit shall be considered sufficient evidence that the person making the affidavit has not, contrary to the provisions of this section, engaged in a strike against the Government of the Republic of the Philippines, is not a member of any organization of government employees that asserts the right to strike against the Government of the Republic of the Philippines, or that such person does not advocate, and is not a member of an organization that advocates, the overthrow of the Government of the Republic of the Philippines by force or violence."}},{"id":"PH-H1184-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Per diems outside of the Philippines. -No per diems in excess of fifty pesos shall be paid to any official or employee traveling outside of the Philippines."}},{"id":"PH-H1184-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"No transfer of salary savings to the Government Service Insurance System. — The provisions of Republic Act No. 660 to the contrary notwithstanding, no savings from personal services under the general fund and the special, revolving, trust, depository and other funds shall be transferred to the Government Service Insurance System."}},{"id":"PH-H1184-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Reinsurance of government buildings to be equitably distributed among private insurance companies in the Philippines. -In all cases where appropriations are provided in this Act for payment of premiums covering the insurance of government buildings with the Property Insurance Fund, reinsurance shall be equitably distributed among private insurance companies doing business in the Philippines on uniform terms, conditions and rates of premiums."}},{"id":"PH-H1184-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Prohibition against the transfer of appropriations of the Department of National Defense. -The provisions of section eight of this Act to the contrary notwithstanding, no amount appropriated for the Department of National Defense shall be transferred to any other Executive Department."}},{"id":"PH-H1184-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Limitation of special details of officials and employees. -Any provision of existing law to the contrary notwithstanding, no portion of any appropriation provided for in this Act shall be made available for the payment of salaries of officials or employees who are not actually performing the duties and functions pertaining to their positions and assigned to the place of employment as specified in this Act: Provided, That this shall not apply to special assignments for a period not exceeding one hundred eighty days which shall not be renewed or extended. Any official who shall allow the payment of salaries to officials or employees who are not in their designated place of employment and performing their assigned tasks shall be required to refund to the government such sums as may have been paid to such officials or employees."}},{"id":"PH-H1184-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Authority to harmonize the appropriation structure with new terminology of classification of accounts. -The Commissioner of the Budget is hereby authorized to harmonize the appropriation structure with the new terminology of classification of accounts that may be prescribed by law or regulations: Provided, That such reclassification shall not increase or decrease the aggregate sum appropriated in this Act for the various objects affected under each Department, bureau or office."}},{"id":"PH-H1184-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"The Committee on Finance of the Senate and the Committee on Appropriations of the House of Representatives to look into all matters relating to public expenditures. -The Committee on Finance of the Senate and the Committee on Appropriations of the House of Representatives are hereby authorized to look at any time into all matters relating to funds for the expenditures of the National Government and for the payment of public indebtedness; auditing of accounts and expenditures of the National Government; claims against the Government; and in general all matters relating to public expenditures."}},{"id":"PH-H1184-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"Expenditure and disbursement of special funds. -No expenditure shall be incurred, nor any disbursement made, out of the appropriations authorized in this Act from special, revolving and trust funds and from receipts automatically appropriated which will exceed at any one time either the fund itself or the cash in the National Treasury pertaining to such fund, except when, in the opinion of the President, such expenditure or disbursement is required by the exigency of the service, and sufficient income or receipts are expected to accrue to such funds to cover said expenditure or disbursement, in which case the necessary amount may be advanced from the general fund."}},{"id":"PH-H1184-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"Appropriations chargeable against the Philippine Charity Sweepstakes Fund. -The appropriations provided in this Act for carrying out the activities heretofore financed from the receipts of the Philippine Charity Sweepstakes Fund shall continue to be charged against the said Fund, and the Board of Directors of the Philippine Charity Sweepstakes shall allot the amounts thereof in the distribution of the Philippine Charity Sweepstakes Fund."}},{"id":"PH-H1184-A31","no":31,"noLabel":{"en":"Section 31."},"text":{"en":"Immediate payment of accounts. -In order to insure the immediate collection of income due any bureau or office for services rendered or sale of any commodity or article produced or manufactured by the same, no such service shall be rendered or sale made except on the cash basis. Any official or employee who allows such service to be rendered or sale to be made on account shall be held personally liable therefor and such act shall be considered sufficient ground for his removal from office; Provided, That the provision of this section shall apply only to transactions of the government with private parties."}},{"id":"PH-H1184-A32","no":32,"noLabel":{"en":"Section 32."},"text":{"en":"Incumbents of positions whose designations or titles were modified not to be laid off. -Incumbents of positions whose designations or titles were modified or otherwise changed in this Act shall not be laid off, nor the salaries authorized in this Act for such positions increased by reason of such change in designation or title the provision of existing law to the contrary notwithstanding."}},{"id":"PH-H1184-A33","no":33,"noLabel":{"en":"Section 33."},"text":{"en":"Effective date. -This Act shall take effect on July first, nineteen hundred and fifty-five, except where otherwise stated.\nApproved: June 18, 1955."}}],"pack":"ph-p16"};
  FT["PH-H1185"] = {"id":"PH-H1185","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1351_1955.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授予Monkayo Electric Company在达沃省蒙卡约市镇电灯、热力与动力系统特许经营权的法案","en":"An Act Granting the Monkayo Electric Company a Franchise for an Electric Light, Heat and Power System in the Municipality of Monkayo, Province of Davao","orig":"An Act Granting the Monkayo Electric Company a Franchise for an Electric Light, Heat and Power System in the Municipality of Monkayo, Province of Davao","vi":"Đạo luật cấp quyền khai thác cho Monkayo Electric Company để xây dựng, lắp đặt, vận hành và duy trì hệ thống điện tại thị xã Monkayo, tỉnh Davao","th":"พระราชบัญญัติให้สัมปทานแก่ Monkayo Electric Company เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบไฟฟ้าในเทศบาล Monkayo, จังหวัด Davao","id":"Undang-Undang memberikan waralaba kepada Monkayo Electric Company untuk membangun, memasang, mengoperasikan, dan memelihara sistem tenaga listrik di Kotamadya Monkayo, Provinsi Davao","ms":"Akta memberikan francais kepada Monkayo Electric Company untuk membina, memasang, mengendalikan dan menyelenggara sistem tenaga elektrik di Perbandaran Monkayo, Wilayah Davao"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1351","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1351_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1185-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to the Monkayo Electric Company, for a period of twenty-five years from the approval of this Act, the right, privilege, and authority to construct, maintain, and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat, and/or power for sale within the Municipality of Monkayo, Province of Davao."}},{"id":"PH-H1185-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H1185-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that in the event the Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender its franchise and will turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H1185-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Monkayo Electric Company a Franchise for an Electric Light, Heat and Power System in the Municipality of Monkayo, Province of Davao","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1186"] = {"id":"PH-H1186","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1352_1955.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授予Hernani J. Jimenez博士在西内格罗斯省La Carlota市镇电灯、热力与动力系统特许经营权的法案","en":"An Act Granting Dr. Hernani J. Jimenez a Franchise for an Electric Light, Heat and Power System in the Municipality of La Carlota, Province of Negros Occidental","orig":"An Act Granting Dr. Hernani J. Jimenez a Franchise for an Electric Light, Heat and Power System in the Municipality of La Carlota, Province of Negros Occidental","vi":"Đạo luật cấp quyền khai thác cho Dr. Hernani J. Jimenez để xây dựng, lắp đặt, vận hành và duy trì hệ thống điện tại thị xã La Carlota, tỉnh Negros Occidental","th":"พระราชบัญญัติให้สัมปทานแก่ Dr. Hernani J. Jimenez เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบไฟฟ้าในเทศบาล La Carlota, จังหวัด Negros Occidental","id":"Undang-Undang memberikan waralaba kepada Dr. Hernani J. Jimenez untuk membangun, memasang, mengoperasikan, dan memelihara sistem tenaga listrik di Kotamadya La Carlota, Provinsi Negros Occidental","ms":"Akta memberikan francais kepada Dr. Hernani J. Jimenez untuk membina, memasang, mengendalikan dan menyelenggara sistem tenaga elektrik di Perbandaran La Carlota, Wilayah Negros Occidental"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1352","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1352_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1186-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to Dr. Hernani J. Jimenez, for a period of twenty-five years from the approval of this Act, the right, privilege, and authority to construct, maintain, and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat, and/or power for sale within the Municipality of La Carlota, Province of Negros Occidental."}},{"id":"PH-H1186-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H1186-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that, in the event the Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender his franchise and will turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H1186-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Dr. Hernani J. Jimenez a Franchise for an Electric Light, Heat and Power System in the Municipality of La Carlota, Province of Negros Occidental","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
