  FT["PH-H1194"] = {"id":"PH-H1194","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1360_1955.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授予Talisay Electric Plant在西内格罗斯省Talisay市镇安装、运营与维护电灯、热力与动力系统特许经营权的法案","en":"An Act Granting to the Talisay Electric Plant a Franchise to Install, Operate, and Maintain an Electric Light, Heat, and Power System in the Municipality of Talisay, Province of Occidental Negros","orig":"An Act Granting to the Talisay Electric Plant a Franchise to Install, Operate, and Maintain an Electric Light, Heat, and Power System in the Municipality of Talisay, Province of Occidental Negros","vi":"Đạo luật cấp quyền khai thác cho Talisay Electric Plant để xây dựng, lắp đặt, vận hành và duy trì hệ thống điện tại thị xã Talisay, tỉnh Occidental Negros","th":"พระราชบัญญัติให้สัมปทานแก่ Talisay Electric Plant เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบไฟฟ้าในเทศบาล Talisay, จังหวัด Occidental Negros","id":"Undang-Undang memberikan waralaba kepada Talisay Electric Plant untuk membangun, memasang, mengoperasikan, dan memelihara sistem tenaga listrik di Kotamadya Talisay, Provinsi Occidental Negros","ms":"Akta memberikan francais kepada Talisay Electric Plant untuk membina, memasang, mengendalikan dan menyelenggara sistem tenaga elektrik di Perbandaran Talisay, Wilayah Occidental Negros"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1360","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1360_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1194-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to the Talisay Electric Plant, a sole proprietorship of Anselmo S. Diaz, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat and/or power for sale within the municipality of Talisay, Province of Occidental Negros."}},{"id":"PH-H1194-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H1194-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that, in the event the Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender his franchise and will turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H1194-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting to the Talisay Electric Plant a Franchise to Install, Operate, and Maintain an Electric Light, Heat, and Power System in the Municipality of Talisay, Province of Occidental Negros","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1195"] = {"id":"PH-H1195","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1361_1955.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"授权菲律宾总统出售碧瑶的国家政府别墅及其坐落地块与家具设备的法案","en":"An Act Authorizing the President of the Philippines to Sell the National Government Cottages in Baguio and the Lots in Which They are Situated and the Furniture and Equipment","orig":"An Act Authorizing the President of the Philippines to Sell the National Government Cottages in Baguio and the Lots in Which They are Situated and the Furniture and Equipment","vi":"Đạo luật số 1361: Luật cho phép Tổng thống Philippines bán các nhà nghỉ của Chính phủ Quốc gia tại Baguio cùng đất, đồ đạc và thiết bị","th":"พระราชบัญญัติฉบับที่1361อนุญาตให้ประธานาธิบดีฟิลิปปินส์ขายบ้านพักของรัฐบาลแห่งชาติในBaguioพร้อมที่ดิน เฟอร์นิเจอร์ และอุปกรณ์","id":"Undang-Undang Nomor 1361: yang mengizinkan Presiden Filipina menjual pondok Pemerintah Nasional di Baguio beserta tanah, perabot, dan perlengkapannya","ms":"Akta Nombor 1361: membenarkan Presiden Filipina menjual kotej Kerajaan Negara di Baguio bersama tanah, perabot dan kelengkapannya"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1361","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1361_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1195-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The President of the Philippines is hereby authorized to sell the national government cottages in Baguio and the lots in which they are situated and the furniture and equipment, save those reserved for the President, Vice-President, President of the Senate, Speaker of the House of Representatives, members of the Supreme Court and the Court of Appeals, and the Auditor General."}},{"id":"PH-H1195-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"An Appraisal Committee is hereby created composed of the District Engineer of Benguet, the City Assessor and the City Auditor of Baguio, to appraise each cottage and lot including furniture and equipment to be sold, and no cottage and lot including furniture and equipment may be sold unless it has first been properly appraised by the Committee. Before the appraisal of the lots, the district engineer shall segregate each lot by metes and bounds and shall exclude the portions that may be needed as school sites, playgrounds, roads, government offices and depots, and those reserved for the officials mentioned in section one hereof. The segregation plan shall be submitted to the President of the Philippines for approval."}},{"id":"PH-H1195-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The cottages and lots including furniture and equipment shall be sold at public auction to the highest bidder under such rules and regulations as the President may prescribe: Provided, That no cottage and lot including furniture and equipment may be sold for less than the appraised actual value of each cottage and lot including furniture and equipment as found by the Committee on Appraisal: Provided, further, That no person or family shall buy more than one cottage and the lot including furniture and equipment in which it is built: Provided, furthermore, That no person who already owns residential property in Baguio shall be allowed to participate in the public auction to sell these cottages and lots including furniture and equipment: Provided, furthermore, That every cottage and the lot including furniture and equipment in which it is built in Jungle Town shall be sold, at a price to be fixed by the Committee on Appraisal payable in ten yearly installments, to the present lessee thereof who has continuously leased them for not less than three years prior to the date of the approval of this Act, unless such lessee refuses to exercise the right herein granted within a period of six months from the date he is notified in writing that such cottage and lot including furniture and equipment are ready for sale to him as well as of the price thereof, in which case the same shall be sold in like manner as the cottages and lots including furniture and equipment not located in Jungle Town: And Provided, finally, That if a lot and/or cottage is excluded from the sale because the lot is needed as provided in section two hereof, the occupant shall be assigned another lot in Jungle Town which shall be sold to him as herein provided."}},{"id":"PH-H1195-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Except as provided in section three hereof, no government official or employee or member of his family shall be allowed to purchase any of the cottages and lots including furniture and equipment, and any sale to such person shall be void: Provided, That if a government official or employee is the occupant and lessee of a cottage continuously for at least five years prior to the approval of this Act, and does not own any residential lot in the City of Baguio, he shall be allowed to purchase the same and be given preference in the sale of the cottage and lot so occupied and leased by him."}},{"id":"PH-H1195-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"No property purchased under this Act shall be sold, transferred, or conveyed to other parties within a period of ten years after the consummation of the sale."}},{"id":"PH-H1195-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the President of the Philippines to Sell the National Government Cottages in Baguio and the Lots in Which They are Situated and the Furniture and Equipment","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1196"] = {"id":"PH-H1196","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1362_1955.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"进一步修订第65号共和国法（通称《菲律宾退伍军人权利法案》）的法案","en":"An Act to Further Amend Republic Act Numbered Sixty-Five, Commonly Known as the Philippine Veterans Bill of Rights","orig":"An Act to Further Amend Republic Act Numbered Sixty-Five, Commonly Known as the Philippine Veterans Bill of Rights","vi":"Đạo luật sửa đổi thêm Đạo luật Cộng hòa số 65","th":"พระราชบัญญัติแก้ไขเพิ่มเติมอีกพระราชบัญญัติแห่งสาธารณรัฐที่ 65","id":"Undang-Undang mengubah lagi Undang-Undang Republik No. 65","ms":"Akta meminda lagi Akta Republik No. 65"},"level":"law","status":"active","topics":["defence"],"docNumber":"Republic Act No. 1362","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1362_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1196-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section two of Republic Act Numbered Sixty-five entitled \"An Act providing for a bill of rights for officers and enlisted men of the Philippine Army and of recognized or deserving guerrilla organizations, and veterans of the Philippine Revolutions, creating therefor a Philippine Veterans Board in the Department of National Defense, and for other purposes,\" as amended by Republic Act Numbered Five hundred seventy-seven, is further amended to read as follows:\nSec. 2. Officers and enlisted men in good standing of the Philippine Army and of any recognized or deserving guerilla organizations who took active participation in the resistance movement and/or in the liberation drive against the enemy who desire to study, or one child of a veteran in whose favor he renounces such right, or the widow or child of a deceased veteran in whose favor the same right is applied for the surviving widow or legal guardian, shall, upon certification of the Chairman of the Philippine Veterans Board be admitted to any school college, university or institute authorized by the government, free from all school fees, including tuition, matriculation, athletic, library, laboratory, medical, ROTC, diploma, and graduation fees: Provided , That if the widow remarries, she losses the benefits granted her under this section: Provided, however , That if the veteran contracted two or more marriages and there are children in any or all of such marriages, or if the veteran and his wife died before the enactment of this law, the Philippine Veterans Board shall decide as to who of the children shall enjoy the benefits granted herein: Provided, further , That the length within which a veteran, or child of a deceased veteran, may enjoy this benefit shall be determined by the length of the veteran's war time service between the period of December eight, nineteen hundred and forty-one to December second, nineteen hundred and forty-five plus one school year but in no case less than two school years: Provided, further , That a school year shall mean four quarters or two semesters and one summer: Provided, further , That if after utilizing this period the veteran has not yet finished the course he is taking, the Board may in its discretion allow him to finish his course depending on his scholastic standing: Provided, further , That the veteran is considered not to be using the number of school years he is entitled to if he is enrolled only in the elementary grades or in the high school: Provided, further , That the educational benefit may be utilized for review courses such as the pre-bar, pre-board and the CPA reviews: Provided, further , That the board may in its discretion and for plausible reasons authorize the veterans to change the course which he has originally applied or which he is actually taking: Provided, further , That no private school, college, or institute can be compelled to accept any number which exceeds twenty-five per centum of its entire enrollment.\""}},{"id":"PH-H1196-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section three of the same Act, as amended by Republic Act Numbered Five hundred seventy-seven, is further amended to read as follows:\nSec. 3. The benefits of the next preceding section shall be available only to those who signify their desire to study to the Chairman of the Philippine Veterans Board not later than July thirty-one, nineteen hundred and fifty-six.\""}},{"id":"PH-H1196-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section nine of Republic Act Numbered Sixty-five is hereby amended to read as follows:\nSec. 9. The persons mentioned in sections one and two hereof who are permanently incapacitated from work owing to sickness, disease, or injuries sustained in line of duty, shall be given a life pension of fifty pesos a month, and ten pesos a month for each of his unmarried minor children below eighteen years of age, unless they are actually receiving a similar pension from other government funds, and shall receive, in addition, the necessary hospitalization and medical care.\""}},{"id":"PH-H1196-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955"}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Further Amend Republic Act Numbered Sixty-Five, Commonly Known as the Philippine Veterans Bill of Rights","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1197"] = {"id":"PH-H1197","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1363_1955.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"在政府、政府控制或半政府公司任命中优先录用退伍军人并为其他目的法案","en":"An Act to Give Preference to Veterans in Appointments in the Government, Government-Controlled or Semi-Government Corporations and for Other Purposes","orig":"An Act to Give Preference to Veterans in Appointments in the Government, Government-Controlled or Semi-Government Corporations and for Other Purposes","vi":"Đạo luật ưu tiên cựu chiến binh trong việc bổ nhiệm vào cơ quan chính phủ và các công ty do chính phủ kiểm soát hoặc bán chính phủ","th":"พระราชบัญญัติให้สิทธิพิเศษแก่ทหารผ่านศึกในการแต่งตั้งในหน่วยงานรัฐบาลและบริษัทที่รัฐบาลควบคุมหรือกึ่งรัฐบาล","id":"Undang-Undang mengutamakan veteran dalam pengangkatan pada instansi pemerintah serta perusahaan yang dikendalikan pemerintah atau semi-pemerintah","ms":"Akta mengutamakan veteran dalam pelantikan di agensi kerajaan serta syarikat dikawal kerajaan atau separa kerajaan"},"level":"law","status":"active","topics":["defence"],"docNumber":"Republic Act No. 1363","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1363_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1197-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The policy of the Government is to give preference, other considerations being approximately equal, to persons who are veterans under section four of this Act."}},{"id":"PH-H1197-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Accordingly, appointing officers shall give preference to veterans when extending appointments to positions in the government, in semi-governmental corporations, and government-controlled corporations. Appointing officers who knowingly violate the provisions of this Act shall be punished by a fine of one month's pay for the first violation, and dismissal from the service for the second violation."}},{"id":"PH-H1197-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The provisions of this Act shall not refer to positions which are confidential in nature, or policy-determining, or of highly technical nature."}},{"id":"PH-H1197-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The term \"veteran\" as employed in this Act shall refer to: (1) veterans of the Philippine Revolution as certified to by the Board of Pensions for Revolutionary Veterans; (2) veterans of World War II as certified to by the Philippine Veterans Board; and (3) honorably discharged soldiers and officers of the Armed Forces of the Philippines who have served therein for at least five years."}},{"id":"PH-H1197-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"In order to enable a veteran to obtain preference under the provisions of this Act, it must be shown that he has approximately the same qualifications as other applicants. It is not intended that a veteran shall have priority over civil service eligibles unless he himself is of the same or higher civil service eligibility."}},{"id":"PH-H1197-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The President of the Philippines shall, within thirty days of the effectivity of this Act, promulgate such regulations as may be necessary to carry out the intent and purpose of this Act."}},{"id":"PH-H1197-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section eleven of Republic Act Numbered Sixty-five is amended to read as follows:\n\"Sec. 11. The provisions of Commonwealth Act Numbered Four hundred forty-one to the contrary notwithstanding, the NARRA shall set aside and reserve any of the agricultural lands under its administration for the exclusive settlement of the persons mentioned in sections one and two hereof, as well as of the persons entitled to the benefits of the next preceding section, who desire to own their own farms and who apply therefor within twenty-five years from the approval of this Act, and may for the same purpose and upon the request of the Board, arrange for the acquisition, in the manner outlined in the aforesaid Act, of any other agricultural land which, in the sound judgment of the Board, is best fitted for the purpose herein set forth. The persons herein mentioned shall be entitled to the same benefits, privileges, facilities and help granted by said Act to other settlers\"."}},{"id":"PH-H1197-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955"}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Give Preference to Veterans in Appointments in the Government, Government-Controlled or Semi-Government Corporations and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1198"] = {"id":"PH-H1198","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1364_1955.html","fetchedAt":"2026-10-06","articleCount":34,"structureMode":"ARTICLE","title":{"zh":"卫生工程执业规制法","en":"An Act to Regulate the Practice of Sanitary Engineering in the Philippines","orig":"An Act to Regulate the Practice of Sanitary Engineering in the Philippines","vi":"Đạo luật Quy định Hành nghề Kỹ thuật Vệ sinh","th":"พระราชบัญญัติกำกับการประกอบวิชาชีพวิศวกรรมสุขาภิบาล","id":"Undang-Undang Pengaturan Praktik Teknik Sanitasi","ms":"Akta Pengawalseliaan Amalan Kejuruteraan Sanitasi"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1364","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 34 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1364_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 35 条，缺 10）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1198-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title of Act. -This Act shall be known as the \"Sanitary Engineering Law.\""}},{"id":"PH-H1198-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Definition of terms. -The practice of sanitary engineering within the meaning and intent of this Act shall embrace the following activities:\n(a) Sanitary surveys, reports, design, direction, management, consultation, and investigation of:\n(1) Water purification plants, water collection and distribution systems, reservoirs, drainage and sewer systems, sewage treatment plants, malaria control structures, sewage disposal tanks, and other structures for public health and welfare.\n(2) Projects relating to stream pollution, insect and vermin control or eradication, rural and camp sanitation, and milk and food sanitation.\n(3) Systems for the prevention of atmospheric pollution or the control of indoor air, especially the air or working spaces in industrial establishments (industrial hygiene engineering).\n(b) Professional research and laboratory work supporting the activities listed in subsection (a).\n(c) The term \"sanitary engineer\" as used in this Act shall mean a person duly registered with the Board of Examiners for Sanitary Engineers in the manner as hereinafter provided.\nBoard of Examiners for Sanitary Engineers"}},{"id":"PH-H1198-A3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Composition of Board. -Within thirty days from the effectivity of this Act there shall be created a Board of Examiners for Sanitary Engineers hereinafter referred to as the Board, to be composed of a chairman and two members who shall be appointed by the President of the Philippines upon the recommendation of the Commissioner of Civil Service from among such persons of recognized standing in their profession as may be certified as having practised at least five years, and academically and morally fully qualified by their respective bona fide sanitary engineering associations. The members of the Board shall hold office for a term of three years after appointment or until their successors shall have been appointed and shall have duly qualified. The first members of the Board appointed under this Act shall hold office for the following terms: one member for one year; one member for two years; and one member for three years. Each member of the Board shall qualify by taking the proper oath of office before entering upon the performance of his duties. Any member of the Board may be removed by the President for neglect of duty, incompetence, malpractice, unprofessional, unethical, immoral, or dishonorable conduct, after having been given opportunity to defend himself in a proper administrative investigation: Provided, That during the process of investigation, the President shall have the power to suspend such member under investigation and shall appoint a temporary member in his place. Vacancies in the Board shall be filled for the unexpired term."}},{"id":"PH-H1198-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Powers and duties of the Board. -The Board of Examiners for Sanitary Engineers is vested with authority, conformable with the provisions of this Act, to administer oaths, issue, suspend and revoke certificates of registration for the practice of sanitary engineering, issue certificates of recognition to sanitary engineers already practicing prior to the effectivity of this Act for advanced studies, research and/or highly specialized training in any branch of sanitary engineering, subject to the approval of the President, to investigate such violations of this Act and the regulations thereunder as may come to the knowledge of the Board and for this purpose, issue subpoena duces tecum to secure appearance of witnesses in connection with the charges presented to the Board, to inspect, at least once a year, educational institutions offering courses in sanitary engineering, to discharge such other powers and duties as may affect ethical and technological standards of the sanitary engineering profession in the Philippines. For the purpose of this Act, the Secretary of Health, and/or his duly authorized representatives in the provinces and chartered cities shall be ex officio agents of the Board, and as such it shall be their duty to help in the enforcement of the provisions of this Act.\nIf any person shall refuse to obey any subpoena so issued or shall refuse to testify or produce any book, document, etc., the Board may present its petition to the Court of First Instance, setting forth the facts and thereupon such court shall, in a proper case, issue its subpoena to such person, requiring his appearance before such court, and there to testify or produce such books, papers, documents, etc., as may be deemed necessary and pertinent by the Board. Any person failing or refusing to obey the subpoena or order of the said court, may be proceeded against in the same manner as for refusal to obey any other subpoena or order of the court."}},{"id":"PH-H1198-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Qualifications of Board members. -Each member of the Board shall, at the time of his appointment:\n(a) Be a citizen and resident of the Philippines;\n(b) Be at least thirty years of age and of good moral character;\n(c) Be a graduate of sanitary engineering or a registered civil engineer who has taken major subjects in sanitary engineering from a recognized and legally constituted school, institute, college or university and/or a registered Civil Engineer who has passed the Civil Service examination for Senior Sanitary Engineer;\n(d) Be a registered sanitary engineer duly qualified to practice sanitary engineering in the Philippines and have practised sanitary engineering, with a certificate as such, for a period of not less than five years prior to his appointment;\n(e) Not be a member of the faculty of any school, institution, college, or university where sanitary engineering course is taught nor have a pecuniary interest in such institution;\n(f) No former members of the faculty of any school, institution, college or university, where sanitary engineering is taught can become a member of the Board, unless he had stopped teaching for at least three consecutive years prior to his appointment."}},{"id":"PH-H1198-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Registration and examination fees. -The Board of Examiners shall charge for each application for examination, the sum of thirty-five pesos and for each certificate of registration, ten pesos."}},{"id":"PH-H1198-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Compensation of Board Members. -The members of the Board shall each receive as compensation, the sum of five pesos for each applicant examined. A sanitary engineer in the service of the Government of the Philippines, appointed as member of the Board shall receive the compensation as herein provided in addition to his salary in the Government. All authorized expenses of the Board shall be paid by the Bureau of Civil Service. The Board, including the compensation provided for hereinafter, shall be paid by the collecting and disbursing office of the Bureau of Civil Service, out of such appropriation, as may be made for the purpose."}},{"id":"PH-H1198-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Executive Officer of the Board. -The Commissioner of Civil Service shall be the executive officer of the Board, and shall conduct the examinations given by the Board and shall designate any subordinate officer of the Bureau of Civil Service to act as secretary of the Board. All records and minutes of the Board, including all examination papers, shall be kept by the Bureau of Civil Service."}},{"id":"PH-H1198-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Annual report. -The Board shall submit an annual report to the President after the close of each fiscal year, giving a detailed account of its proceedings during the year and making such recommendations as may be deemed proper.\nSection 10. Roster of Sanitary Engineers.— A r oster showing names and place of business and permanent home addresses of all professional sanitary engineers, shall be prepared by the Commissioner of Civil Service during the month of July of every year, commencing one year after the date this Act becomes effective. Copies of this roster shall be mailed to each person so registered and placed on file with the President; and copies thereof, shall be furnished to all Department Heads, to the mayors of all chartered cities, to the Director of Public Works, to the Collector of Customs, to such other bureaus, or government agencies and provincial and municipal authorities as may be deemed necessary, and to the public upon request.\nExamination for Registration"}},{"id":"PH-H1198-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Examination requirement. -All applicants for registration for the practice of sanitary engineering, shall be required to pass a technical examination as hereinafter provided."}},{"id":"PH-H1198-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Holding of examination. -Examination of candidates desiring to practice sanitary engineering in the Philippines shall be given in the City of Manila, beginning the last Monday of January and August of each year, provided that such days do not fall on official holidays, otherwise the examination shall be held on the days next following."}},{"id":"PH-H1198-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Subjects of examination. -Applicants for certificates of registration as sanitary engineers shall be examined in the following subjects: Mathematics, including algebra, plane and spherical trigonometry, analytics, descriptive and solid geometry, differential and integral calculus, rational and applied mechanics; hydraulics; topographic and hydrographic surveying; design and construction of wooden, masonry, reinforced concrete, and steel structures as flumes, water towers and drainage canals; hydrology; water and sewage analysis; microbiology and bacteriology; design and construction of sewers, storm drains, water purification plants, sewage treatment plants and plumbing: Provided, However , That duly registered civil engineers shall be exempted from taking examinations in the following subjects: (1) Mathematics, including algebra, plane and spherical trigonometry, differential and integral calculus, rational and applied mechanics; (2) hydraulics; (3) topographic and hydrographic surveying; and (4) design and construction of wooden, masonry, reinforced concrete and steel structures as flumes, water towers and drainage canals."}},{"id":"PH-H1198-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Report of ratings. -The Board of Examiners for Sanitary Engineering shall, within one hundred and twenty days after the date of completion of the examination, report the rating obtained by each candidate to the Commissioner of Civil Service, who shall submit such ratings to the President."}},{"id":"PH-H1198-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Reexamination. -An applicant who for the third time fails to pass the examination for the same grade shall not be allowed to take another until at least one year has elapsed after his last examination."}},{"id":"PH-H1198-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Issuance of certificates. -The President shall, upon the recommendation of the Board, issue a certificate of registration upon payment of the registration fee as provided in this Act to any applicant, who, in the opinion of the Board and after approval by the President, has satisfactorily met all the requirements specified in this Act.\nAll certificates of registration shall show the full name of the registrant, shall have a serial number, and shall be signed by all the members of the Board, the President and the Commissioner of Civil Service and shall be attested by the official seal of the same Board.\nThe issuance of a certificate of registration by the Board to a registrant shall be evidence that the person named therein is entitled to all the rights and privileges of a registered sanitary engineer, while said certificate remains unrevoked and unsuspended, unless the same is revoked or suspended."}},{"id":"PH-H1198-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Qualifications for examination. -Any person applying for admission to the sanitary engineering examination as herein Provided, shall, prior to the date of the examination, establish to the satisfaction of the Board that he has the following qualifications:\n(a) Be at least twenty-one years of age;\n(b) Be a citizen of the Philippines;\n(c) Be of good reputation and moral character; and,\n(d) Be a graduate of a four-year course in sanitary engineering or BSCE having taken major subjects in sanitary engineering from a school, institute, college or university recognized by the Government or the State wherein it is established."}},{"id":"PH-H1198-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Oath of Sanitary Engineers. -All successful candidates shall be required to take a professional oath before the Board of Examiners for Sanitary Engineers or other Government officials authorized to administer oaths, prior to entering upon the practice of the sanitary engineering profession."}},{"id":"PH-H1198-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Seal and use of seal. -All registered sanitary engineers shall obtain a seal of such design as the Board shall authorize and direct: Provided, However , That the serial number of the certificate issued by the Board shall be included in the design of the seal. Plans and specifications prepared by, or under the direct supervision of a registered sanitary engineer shall be stamped with the seal during the life of the registrant’s certificate, and it shall be unlawful for any one to stamp or seal any document with said seal after the certificate of the registrant named therein has expired or has been revoked, unless said certificate shall have been renewed or reissued."}},{"id":"PH-H1198-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Exemption from registration. -Registration shall not be required of the following persons:\n(a) Officers or enlisted men of the United States and Philippine Armed Forces, and civilian employees of the Government of the United States stationed in the Philippines while rendering sanitary engineering services for the United States and/or Philippines.\n(b) Foreign sanitary engineers or experts called in by the Philippine Government for consultation for specific sanitary engineering services as defined under this Act: Provided, That this practice shall be limited to such work: And Provided, further, That they do not engage in private practice at their own account as sanitary engineers."}},{"id":"PH-H1198-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Refusal to issue certificate. -The Board of Examiners for Sanitary Engineers shall not issue a certificate to any person convicted by a court of competent jurisdiction of any criminal offense involving moral turpitude, or to any person guilty of immoral or dishonorable conduct, or to any person of unsound mind. In the event of a refusal to issue a certificate to any person, the Board shall give to the applicant a written statement setting forth its reason for such action, which statement shall be incorporated in the records of the Board."}},{"id":"PH-H1198-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Re-issue and replacement of certificates. -The Subject to the approval of the President, the Board shall have the power after due notice and hearing, to suspend or revoke the certificate of registration for any cause mentioned in the preceding section."}},{"id":"PH-H1198-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Suspension and revocation of certificates. -Board may, after the expiration of one year from the date a certificate of registration is revoked and for reasons it may deem sufficient, entertain an application for a new certificate of registration from the registrant concerned. Such application shall be accomplished in the same form prescribed for examination, but the Board may, in its discretion, exempt the applicant from taking the requisite examination."}},{"id":"PH-H1198-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Transitory provisions. -Within one year, or as soon as this Act takes effect, any person desiring to practice the profession of sanitary engineering shall be required only to obtain a certificate of registration in the manner and under the conditions herein provided:\n(1) All graduates of sanitary engineering or civil engineers who have taken major subjects in sanitary engineering from a recognized and legally constituted school, institute, college or university, with at least two years experience as sanitary engineers; all civil engineers in the employ of the Philippine Government or in private practice in the Philippines who have at least five years experience in sanitary engineering services and civil engineers with no less than ten years continuous practice as master plumbers, prior to the approval of this Act; and,\n(2) All civil engineers who have passed the Assistant Sanitary Engineer or Senior Sanitary Engineer Civil Service examinations and have been practicing sanitary engineering for at least two years prior to the approval of this Act.\nEnforcement of Act and Penal Provisions"}},{"id":"PH-H1198-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Enforcement of the Act by officers of the law. -It shall be the duty of all duly constituted law officers of the national, provincial, city and municipal governments or any political subdivision thereof, to enforce the provisions of this Act and to prosecute any person violating the same."}},{"id":"PH-H1198-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Registration required. -Unless exempted from registration, no person shall practice or offer to practice sanitary engineering in the Philippines without having obtained the proper certificate of registration from the Board of Examiners for Sanitary Engineers."}},{"id":"PH-H1198-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Penal provisions. -Any person who shall practice or offer to practice sanitary engineering in the Philippines without being registered in accordance with the provisions of this Act, or any person presenting or attempting to use as his own the certificate of registration of a registered sanitary engineer, or any person who shall give any false or forged evidence of any kind to the Board, or any person who shall impersonate any registrant sanitary engineer of different name, or any person who shall attempt to use a revoked or suspended certificate of registration, or any person who shall use in connection with his name, or otherwise assume, use, or advertise any title or description tending to convey the impression that he is a sanitary engineer, without holding a valid certificate of registration, or any person who shall violate any of the provisions of this Act, shall be guilty of a misdemeanor and shall, upon conviction, be sentenced to a fine of not less than five hundred pesos nor more than two thousand pesos, or to suffer imprisonment for a period of not less than six months nor more than one year, or both, in the discretion of the court.\nMiscellaneous Provisions"}},{"id":"PH-H1198-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Field of action authorized for Sanitary Engineering; prohibitions. -It shall be unlawful for any person, unless exempted from registration under section twenty of this Act:\n(a) To be in responsible charge of the preparation of plans, designs, investigations, valuations, technical reports, specifications or estimates, or to be in performance of other sanitary engineering service, either for himself or for others, unless he holds a valid certificate of registration as sanitary engineer.\n(b) To be in responsible charge of the construction, erection, installation or alteration, or of the performance of sanitary engineering service in connection with the manufacture, sale, supply or distribution of any sanitary engineering works, projects or plant (as cited in article one, section two of this Act), either for himself or for others, unless he holds a valid certificate of registration as sanitary engineer."}},{"id":"PH-H1198-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Preparation of plans and supervision of construction by registered sanitary engineers required. -It shall be unlawful for any person or firm to order or otherwise cause the construction, erection, installation or alteration of any sanitary engineering equipment, machinery or process for any sanitary engineering work, project or plant, the cost of which exceeds five thousand pesos, unless the designs, plans, layouts, and/or specifications have been prepared under the responsible charge of, signed and sealed by a registered sanitary engineer, and unless the construction, erection, installation, and/or alteration thereof are executed under the responsible charge and direct supervision of a registered sanitary engineer."}},{"id":"PH-H1198-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Firms and corporations engaged in sanitary engineering practice. -A firm, partnership, corporation or association may engage in the practice of sanitary engineering in the Philippines: Provided, That such practice is carried out under the supervision of a sanitary engineer or sanitary engineers holding valid certificates issued by the Board.\nNo firm, partnership, corporation or association, using the name of a person or persons as in the name of a firm, shall advertise as sanitary engineers unless said person or persons are registered sanitary engineers."}},{"id":"PH-H1198-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Collection of professional fees. -It shall be unlawful for any unregistered person to collect a fee for services rendered except as an employee collecting a fee as representative of a registered sanitary engineer."}},{"id":"PH-H1198-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Reciprocity requirements. -No person who is not a citizen of the Philippines at the time he applies to take the examination shall be allowed to take it unless he can prove in the manner provided by the Rules of Court that, by specific provision of law, the country of which he is a citizen, subject, or national either admits citizens of the Philippines to the practice of the same profession without restriction or allows them to practice it after an examination on terms of strict and absolute equality with citizens, subjects, or nationals of the country concerned, including the unconditional recognition of degrees issued by institutions of learning duly recognized for the purpose by the Government of the Philippines: Provided, That if he is not a citizen of the Philippines after December eight, nineteen hundred and forty-one, his active practice in that profession, either in the Philippines or in the state or country where he was practicing his profession, shall not have been interrupted for a period of two years or more prior to July four, nineteen hundred and forty-six, and that the country or state from which he comes allows the citizens of the Philippines by specific provisions of law, to practice the same profession without restrictions or on terms of strict and absolute equality with citizens, subjects or nationals of the country or state concerned."}},{"id":"PH-H1198-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Act not affecting other provisions and/or trades. -This Act shall not be construed to affect or prevent the practice of any other legally recognized profession, and/or trade nor shall it be construed to diminish the fields of practice already embraced by civil engineers duly registered under the Civil Engineering Law, Republic Act Numbered Five hundred and forty-four, or of those by duly licensed master plumbers under existing law."}},{"id":"PH-H1198-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Construction of Act. -If any part or section of this Act shall be declared unconstitutional, such declaration shall not invalidate the other provisions hereof."}},{"id":"PH-H1198-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Effectivity. -This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p16"};
  FT["PH-H1199"] = {"id":"PH-H1199","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1365_1955.html","fetchedAt":"2026-10-06","articleCount":24,"structureMode":"ARTICLE","title":{"zh":"要求所有椰干买家在其每笔国内椰干收购地使用水分测定仪并为其他目的法案","en":"An Act Requiring All Copra Buyers to Use Moisture Meters in All Their Domestic Purchases of Copra in the Place Where Each Such Purchase is Made, and for Other Purposes","orig":"An Act Requiring All Copra Buyers to Use Moisture Meters in All Their Domestic Purchases of Copra in the Place Where Each Such Purchase is Made, and for Other Purposes","vi":"Luật yêu cầu tất cả người mua cùi dừa khô sử dụng máy đo độ ẩm trong mọi giao dịch mua nội địa tại nơi mua","th":"พระราชบัญญัติกำหนดให้ผู้ซื้อเนื้อมะพร้าวแห้งทุกรายใช้เครื่องวัดความชื้นในการซื้อภายในประเทศทุกครั้ง ณ สถานที่ซื้อ","id":"Undang-Undang mewajibkan semua pembeli kopra menggunakan alat ukur kadar air dalam setiap pembelian domestik di tempat transaksi","ms":"Akta mewajibkan semua pembeli kopra menggunakan meter kelembapan bagi setiap pembelian domestik di tempat pembelian"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1365","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 24 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1365_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1199-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"For every first domestic purchase of a particular lot of copra and in every place where each such purchase is made the buyers are hereby required, immediately after one year from the approval of this Act, to use moisture meters, duly approved by the Institute of Science and Technology as hereinafter provided, for determining the percentage of moisture content in copra."}},{"id":"PH-H1199-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Violation of the provisions of the preceding section shall subject the buyer, whether a natural or juridical person, upon conviction, to imprisonment for not less than one month nor more than six months and a fine not less than one thousand nor more than five thousand pesos, with subsidiary imprisonment in case of insolvency: Provided, However , That when such buyer acts through an agent, the latter shall upon conviction also be subject to imprisonment for not less than thirty days and a fine of not less than one hundred pesos nor more than five hundred pesos with subsidiary imprisonment in case of insolvency: And Provided, further, That when the violator is an alien, he shall be subject to the additional penalty of deportation."}},{"id":"PH-H1199-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Every moisture meter which shall be used in accordance with this Act shall first be examined and tested by the Institute of Science and Technology. After a finding by the Institute that the meter is accurate and fit for the purpose of determining the moisture content of copra, it shall approve the same for use. Upon approval thereof, the Institute shall cause a lead seal to be attached to the meter and issue a certificate to the owner upon payment by him to the Institute of a fee of twenty-pesos, such fees to be collected to constitute a special fund to be available exclusively for the use of the Institute to discharge properly the functions assigned to it by this Act. The certificate shall bear the signature of the Director of the Institute and the date of its issuance, and shall state the brand of the meter, the serial number thereof and its calibration, and shall further state that the meter has been found fit for determining the moisture content of copra: Provided, However , That only moisture meters of local manufacture shall be approved for use by the Institute."}},{"id":"PH-H1199-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Should any copra buyer referred to in section one use a moisture meter which has no lead seal and/or for which no certificate has been issued in accordance with the preceding section, or for which a re-certification has not been obtained or has been refused in accordance with section six hereof, he shall upon conviction be subject to imprisonment for not less than one month nor more than six months and a fine of not less than one thousand pesos nor more than five thousand pesos, with subsidiary imprisonment in case of insolvency: Provided, However , That when such buyer acts through an agent, the latter shall upon conviction also be subject to imprisonment for not more than one month and a fine of not less than one hundred pesos nor more than five hundred pesos, with subsidiary imprisonment in case of insolvency: And Provided, further, That when the violator is an alien, he shall be subject to the additional penalty of deportation."}},{"id":"PH-H1199-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The certificate issued in accordance with section three shall be posted in a conspicuous place near the meter, in the site where the meter is to be used."}},{"id":"PH-H1199-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Once every one hundred and eighty days to be counted from the issuance of the certificate mentioned in section three, the calibration of each approved meter must be re-certified by the Director of the Institute of Science and Technology. For each re-certification, the Institute shall collect from the owner of the meter a fee of ten pesos, such fees to be collected to form a part of the special fund created in section three. However, re-certification shall be refused if, in the opinion of the Director, the meter has ceased to be fit for determining the moisture content of copra."}},{"id":"PH-H1199-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"At any time after the issuance of the certificate as referred to in sections three and six, the Philippine Coconut Administration may cause the moisture meter to be re-examined by the Institute of Science and Technology for determination if its calibration is still correct; but no fee shall be charged by the Institute for such re-examination."}},{"id":"PH-H1199-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Any person who tampers with a moisture meter duly authorized to be used as provided for in the preceding sections so as to favor the seller or buyer, or who uses or consents to the use of a moisture meter knowing that it has been tampered to favor him or the person he represents, shall upon conviction be subject to imprisonment for not less than one month nor more than six months and a fine of not less than one thousand pesos nor more than five thousand pesos, with subsidiary imprisonment in case of insolvency: Provided, That when the violator is an alien, he shall be subject to the additional penalty of deportation."}},{"id":"PH-H1199-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Every copra seller or his representative who deals with the buyers required by this Act to use moisture meters shall be allowed by the buyer or his representative to witness the reading of the moisture content of the copra sold."}},{"id":"PH-H1199-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The samples to be taken from the copra under transaction and which are to be fed to and tested by the moisture meter shall be picked in the following manner: samples constituting at least ten per cent of the entire stock of copra to be sold shall be drawn therefrom at random in such a manner as to make the samples more or less representative of such whole stock of copra, in the presence of the seller or his representative and the buyer or his representative; and such samples shall then be mixed together thoroughly and from the mixture the copra to be fed to and tested by the moisture meter shall be drawn indiscriminately in such a manner as to make the same more or less representative of such samples, likewise in the presence of the seller or his agent and the buyer or his agent.\nAny person who commits fraud in the picking of the samples from the copra to be sold to be fed to and tested by the moisture meter to the prejudice either of the seller or buyer shall upon conviction be subject to imprisonment for not less than one month nor more than six months and a fine of not less than one thousand pesos nor more than five thousand pesos, with subsidiary imprisonment in case of insolvency: Provided, That when the violator is an alien, he shall be subject to the additional penalty of deportation."}},{"id":"PH-H1199-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The same penalty provided for in the preceding section shall be imposed upon any buyer and/or his agent who misread or give an incorrect reading of the moisture meter to the prejudice of the seller."}},{"id":"PH-H1199-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"A Committee to formulate a scale establishing a graduated rate of deduction according to the percentage of the moisture content of copra which may be purchased by the domestic copra buyers mentioned in section one of this Act is hereby created."}},{"id":"PH-H1199-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The Committee shall be composed of the Board Chairman of the Philippine Coconut Administration, as Chairman, and a representative of the national organization of Philippine coconut planters, and a representative of the national organization of Philippine copra exporters, as members: Provided, However , That the scale of deduction to be adopted by the Committee shall correspond to the relation between the percentage of moisture content and the consequent loss of weight and shrinkage of copra as determined by tests and experiments conducted or to be conducted by the Institute of Science and Technology and the Philippine Coconut Administration: And Provided, further, That no deduction shall be prescribed for copra with a moisture content of less than five per cent shall be awarded a premium equal to the difference between five per cent and said moisture content."}},{"id":"PH-H1199-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The Committee shall be convened within twenty days from the approval of this Act and the scale shall be formulated within thirty days after the Committee is convened. Any scale voted upon affirmatively by a majority of the members of the Committee shall be deemed approved."}},{"id":"PH-H1199-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"The Chairman of the Committee shall then cause the approved scale referred to in the preceding section to be published in three consecutive issues of the Official Gazette and in five newspapers of general circulation once a week for three consecutive weeks. The expenses for such publication shall be borne by the Philippine Coconut Administration."}},{"id":"PH-H1199-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"The scale shall form a part of this Act and shall take effect immediately after the lapse of one year from the approval of this Act."}},{"id":"PH-H1199-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"After the scale referred to in the next preceding section takes effect, no deduction in the weight of copra based on moisture content greater than that established by such scale shall be allowed. In case of violation of this provision, the penalty and fine provided for in section two of this Act shall apply."}},{"id":"PH-H1199-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"After the effectivity of the scale, every first domestic purchase of a particular lot of copra in the Philippines shall be evidenced by a certificate in triplicate, the original of which shall be issued by the buyer to the seller. The certificate shall state in detail the moisture meter reading, the number of bags of copra, the gross weight thereof, the deductible tare weight of the bags, the net weight, the deductible percentage based on the scale, the weight deductible from the net weight, the remaining difference, the price quoted on five per cent, and the amount payable.\nFailure to issue the certificate provided for in this section shall subject the buyer and/or his agent upon conviction to imprisonment for not less than one month nor more than six months and a fine not less than one thousand nor more than five thousand pesos, with subsidiary imprisonment in case of insolvency."}},{"id":"PH-H1199-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"The operation of moisture meters required by this Act to be used, and the issuance of the certificate referred to in the preceding section, shall be under the supervision of the Philippine Coconut Administration pursuant to rules and regulations it shall promulgate to ensure that the purposes and objectives of this Act in requiring the use of moisture meters are accomplished. To raise the necessary funds for such supervisory work, there shall be levied a fee of five centavos for every one hundred kilos of copra for every first domestic purchase of said product, to be paid by the buyer and collected by the Philippine Coconut Administration pursuant to rules and regulations it shall promulgate, the proceeds of such levy to be available exclusively for its use: Provided, However, That such levy shall be imposed only once for a particular lot of copra."}},{"id":"PH-H1199-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"After the effective date of this Act, all prices of copra shall be quoted on the basis of resecada with five per cent moisture."}},{"id":"PH-H1199-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"For a violation of any provision in this Act for which no specific penalty has been prescribed, the penalty provided for in section two shall apply."}},{"id":"PH-H1199-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"When the violation of any of the provisions of this Act is committed by a juridical person, the manager or the person acting as such shall be responsible for such violation."}},{"id":"PH-H1199-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"All violations of this Act shall be prosecuted in the same manner and under the same rules of ordinary criminal actions."}},{"id":"PH-H1199-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Requiring All Copra Buyers to Use Moisture Meters in All Their Domestic Purchases of Copra in the Place Where Each Such Purchase is Made, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1200"] = {"id":"PH-H1200","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1366_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Cortes市","en":"An Act Converting the Sitio of Son-oc, in the Municipality of Cortes, Province of Bohol, to a Barrio to be Known as Barrio Fatima","orig":"An Act Converting the Sitio of Son-oc, in the Municipality of Cortes, Province of Bohol, to a Barrio to be Known as Barrio Fatima","vi":"Luật chuyển Sitio Son-oc thuộc đô thị Cortes, tỉnh Bohol, thành Barangay Fatima","th":"พระราชบัญญัติยกระดับ Sitio Son-oc ในเทศบาล Cortes จังหวัด Bohol เป็นหมู่บ้านที่เรียกว่า Barangay Fatima","id":"Undang-Undang mengubah Sitio Son-oc di Kotamadya Cortes, Provinsi Bohol, menjadi Barangay Fatima","ms":"Akta menukar Sitio Son-oc di Perbandaran Cortes, Wilayah Bohol, menjadi Barangay Fatima"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1366","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1366_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1200-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Son-oc, in the Municipality of Cortes, Province of Bohol, is hereby converted to a barrio to be known as barrio Fatima."}},{"id":"PH-H1200-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p16"};
  FT["PH-H1201"] = {"id":"PH-H1201","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1367_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Three Hundred Thousand Pesos for the Construction of a Leprosy Research Laboratory and Training Center Building and for the Expenses of its Equipment and Maintenance","orig":"An Act Appropriating the Sum of Three Hundred Thousand Pesos for the Construction of a Leprosy Research Laboratory and Training Center Building and for the Expenses of its Equipment and Maintenance","vi":"Đạo luật Cộng hòa số 1367 cấp 300.000 peso xây phòng thí nghiệm nghiên cứu bệnh phong và trung tâm đào tạo","th":"พระราชบัญญัติสาธารณรัฐฉบับที่1367จัดสรรเงิน300,000เปโซเพื่อสร้างห้องปฏิบัติการวิจัยโรคเรื้อนและอาคารศูนย์ฝึกอบรม","id":"Undang-Undang Republik Nomor 1367 tentang alokasi 300.000 peso untuk pembangunan laboratorium penelitian kusta dan pusat pelatihan","ms":"Akta Republik Nombor 1367 mengenai peruntukan 300,000 peso untuk pembinaan makmal penyelidikan kusta dan pusat latihan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1367","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1367_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1201-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of three hundred thousand pesos for the construction of an adequate leprosy research laboratory and training center building and for the expenses of its equipment and maintenance."}},{"id":"PH-H1201-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p16"};
  FT["PH-H1202"] = {"id":"PH-H1202","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1368_1955.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"修订第 51 号联邦法（即《达沃市宪章》）若干条的法案","en":"An Act to Amend Certain Sections of Commonwealth Act Numbered Fifty-One, as Amended, Otherwise Known as the Charter of the City of Davao","orig":"An Act to Amend Certain Sections of Commonwealth Act Numbered Fifty-One, as Amended, Otherwise Known as the Charter of the City of Davao","vi":"Đạo luật sửa đổi một số điều của Đạo luật Thịnh vượng chung số 51 (Hiến chương Thành phố Davao) như đã được sửa đổi","th":"พระราชบัญญัติแก้ไขเพิ่มเติมบางมาตราแห่งพระราชบัญญัติเครือรัฐที่ 51 (กฎบัตรเมือง Davao) ซึ่งแก้ไขเพิ่มเติมแล้ว","id":"Undang-Undang mengubah beberapa pasal Undang-Undang Persemakmuran No. 51 (Piagam Kota Davao) sebagaimana diubah","ms":"Akta meminda beberapa seksyen Akta Komanwel No. 51 (Piagam Bandar Davao) sebagaimana dipinda"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1368","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1368_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1202-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section seven of Commonwealth Act Numbered Fifty-one, as amended, is further amended to read as follows:\n\"Sec. 7. Election and compensation. -The Mayor shall be the chief executive of the city.\n\"The Mayor shall be elected by the qualified voters of the city during every regular election for provincial and municipal officials in accordance with the provisions of the Revised Election Code: Provided, That the first election for Mayor shall be held simultaneously with the regular elections for provincial and municipal officials to be held following the approval of this Act. Pending the said next regular elections, the incumbent Mayor of the city at the time of the approval of this Act shall continue to hold office and in case said office be vacant at the time this Act takes effect, the President shall appoint a person to act as Mayor until his successor shall have been elected and have qualified.\n\"No person shall be elected Mayor unless he has been a citizen of the Philippines for at least five years, is at least twenty-five years of age at the time of his election, a resident of the city for not less than one year immediately prior to his election and a qualified voter therein.\n\"The Mayor shall receive a salary of eight thousand four hundred pesos a year. With the approval of the proper Head of Department, he may receive, in addition to his salary, a non-commutable allowance of two thousand pesos per annum. He shall also be entitled, at the discretion of the City Council, to quarters allowance."}},{"id":"PH-H1202-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section eight of the same Act is amended to read as follows:\n\"Sec. 8. The Vice-Mayor. -There shall be a vice-mayor who shall perform the duties of the Mayor, in the event of the sickness, absence or other temporary incapacity of the Mayor, or in the event of a definitive vacancy in the position of Mayor, until said office shall be filled in accordance with law. If, for any reason, the vice-mayor is temporarily incapacitated for the performance of the duties of the office of the Mayor, or said office of the vice-mayor is vacant, the duties of the Mayor shall be performed by the city engineer. The acting mayor shall have the same powers and duties as the Mayor.\n\"The vice-mayor shall be the presiding officer of the City Council and shall perform such other duties as may be assigned to him by the Mayor or prescribed by law or ordinance. He shall be elected in the same manner as the Mayor and shall at the time of his election possess the same qualifications as the Mayor. He shall receive a salary of five thousand four hundred pesos a year."}},{"id":"PH-H1202-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section ten of the same Act is amended to read as follows:\n\"Sec. 10. City Secretary. — There shall be a city secretary who shall be appointed by the Mayor; and who shall receive a salary of four thousand two hundred pesos per annum. He shall be considered as head of a city department and as such he shall have the following duties:\n\"(a) He shall act as secretary of the Board of Tax Appeals, and such other boards or committees as may hereafter be created by law or ordinance, and shall keep a journal of their proceedings.\n\"(b) He shall have charge of all records and documents of the city for which provision is not otherwise made.\n\"(c) He shall keep the corporate seal and affix the same with his signature to all official acts of the Mayor and to all other official documents and papers of the government of the city as may be required by custom, in the discretion of the Mayor.\n\"(d) He shall be the local civil registrar and shall keep a civil register for the city and record therein all births, marriages, and deaths with their respective dates.\n\"(e) He shall perform such other duties as the Mayor may direct or as may be required of him by law or ordinance.\n\"(f) He shall attest all orders, proclamations, ordinances and resolutions signed by the Mayor.\n\"(g) He shall, on demand, furnish certified copies of all records and documents in his charge which are not of a confidential character and shall collect twenty centavos for each one hundred words including the certificate, and all receipts shall be paid into the city treasury. He shall likewise perform with respect to his office, the duties similar to those imposed on heads of departments of the city government by section thirty-three hereof."}},{"id":"PH-H1202-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The provisions of section twelve of the same Act are repealed, and, in lieu thereof, the following new provisions are inserted:\n\"Sec. 12. Constitution and organization of the City Council. -The City Council shall be the legislative body of the city, and shall be composed of the vice-mayor, as the presiding officer, and ten councilors, who shall be elected at large by the voters of the city, in conformity with the provisions of the Revised Election Code, and shall hold office for four years unless sooner removed. The ten candidates receiving the greatest number of votes shall be declared elected.\n\"In case of sickness, absence, suspension or other temporary disability of any member of the council, or if for any reason it becomes necessary to maintain a quorum, the President of the Philippines may appoint a temporary substitute who shall possess all the rights and perform all the duties of a member of the Council until the return to duty of the regular incumbent.\n\"If any member of the City Council should be a candidate for office in any election, he shall be incompetent to act with the City Council in the discharge of the duties herein conferred upon it, and in such case the other members of the Council shall discharge said duties without his assistance, or they may choose some disinterested elector of the city to act on the Council in such matters in his stead.\n\"The members of the council shall each receive an annual compensation of three thousand six hundred pesos."}},{"id":"PH-H1202-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"There are hereby inserted between sections twelve and thirteen of the same Act four sections, to be known as sections 12-A, 12-B, 12-C, and 12-D, which shall read as follows:\n\"Sec. 12-A. Qualification, election, suspension and removal of members of the Council. -The members of the City Council shall be qualified electors of the city, shall be residents thereof for at least one year, and be not less than twenty-three years of age. The members-elect shall upon qualifying assume office on the date fixed in the Revised Election Code and hold office until their successors are elected and have qualified.\n\"The members of the City Council may be suspended or removed from office under the same circumstances, in the same manner, and with the same effect, as elective provincial officers, and the provisions of law governing the suspension or removal of elective provincial officers are hereby made applicable to the suspension or removal of said members of the Council.\n\"Sec. 12-B. The Presiding Officer of the City Council. -The vice-mayor shall be the presiding officer of the Council. In his absence, the Council shall elect one of its members as temporary presiding officer. He shall sign all ordinances, and all resolutions and motions directing the payment of money or creating liability, enacted or adopted by the Council.\n\"Sec. 12-C."}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Certain Sections of Commonwealth Act Numbered Fifty-One, as Amended, Otherwise Known as the Charter of the City of Davao","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1203"] = {"id":"PH-H1203","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1369_1955.html","fetchedAt":"2026-10-06","articleCount":9,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Thirty Million Pesos, Out of the Proceeds of the Sale of Bonds to be Issued Under Republic Act Numbered One Thousand or from Any Loan, for the Purpose of Financing the Manufacture of Coconut Products and By-Products and the Component Parts of Coconut Trees, and Otherwise for the Industrialization of the Coconut Trees and Coconut Products and By-Products","orig":"An Act Appropriating the Sum of Thirty Million Pesos, Out of the Proceeds of the Sale of Bonds to be Issued Under Republic Act Numbered One Thousand or from Any Loan, for the Purpose of Financing the Manufacture of Coconut Products and By-Products and the Component Parts of Coconut Trees, and Otherwise for the Industrialization of the Coconut Trees and Coconut Products and By-Products","vi":"Đạo luật Cộng hòa số 1369 cấp 30 triệu peso để tài trợ sản xuất các sản phẩm và phụ phẩm dừa và công nghiệp hóa cây dừa","th":"พระราชบัญญัติสาธารณรัฐฉบับที่1369จัดสรรเงิน30ล้านเปโซเพื่อสนับสนุนการผลิตผลิตภัณฑ์และผลพลอยได้จากมะพร้าวและการพัฒนาอุตสาหกรรมมะพร้าว","id":"Undang-Undang Republik Nomor 1369 tentang alokasi 30 juta peso untuk membiayai produksi produk dan hasil sampingan kelapa serta industrialisasi kelapa","ms":"Akta Republik Nombor 1369 mengenai peruntukan 30 juta peso untuk membiayai pengeluaran produk dan hasil sampingan kelapa serta perindustrian kelapa"},"level":"law","status":"active","topics":["environment","culture"],"docNumber":"Republic Act No. 1369","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 9 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1369_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1203-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby appropriated, out of the proceeds of the sale of bonds to be issued under Republic Act Numbered One thousand or from any loan, the sum of thirty million which shall be invested: (a) in the construction, establishment and operation of necessary centrals or mills for the manufacture, on commercial scale, or industrialization of coconut products and by-products and the component parts of coconut trees, hereinafter called coconut centrals; or (b) in loans to persons who are citizens of the Philippines or to associations or corporations organized under the laws of the Philippines, the capital of which is owned by the citizens of the Philippines, for the purpose of financing the establishment of such centrals or mills; or (c) in shares, hereafter called contributions, or in subscriptions by the Government to the capital of such associations or corporations engaged or which will engage in such enterprise or coconut industrialization."}},{"id":"PH-H1203-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The administration and investment of the sum appropriated under section one shall be vested in the Philippine Coconut Administration. In pursuant hereof, the Philippine Coconut Administration is authorized and empowered:\n(a) To construct, establish and operate coconut centrals and to purchase the necessary machineries and equipment for such centrals;\n(b) To make loans not exceeding the amount of fifty thousand pesos to any Filipino citizen or corporation the majority of whose stock is owned by Filipinos, properly secured in accordance with existing banking laws; in the event that the loan exceeds fifty thousand pesos, the approval of the Economic Coordinator or his successor shall be required;\n(c) To enter into partnership with Filipino producers and/or Filipino citizens engaged in the industry, or associations the majority of whose stock is owned by Filipinos, or subscribe to the capital stock of a corporation the majority of whose stock is owned by Filipinos for the purpose of financing the manufacture, on commercial scale, of coconut products and by-products and the component parts of coconut trees, including the construction, establishment and operation of the necessary coconut centrals or mills in connection therewith: Provided, However , That if the contribution shall exceed fifty thousand pesos, the approval of the Economic Coordinator or his successor shall be required;\n(d) To make the necessary disbursement from the sum appropriated in section one on coconut of the loans, contributions, subscriptions and/or investments pursuant to subsections (a), (b), and (c), of this section;\n(e) To make contracts and otherwise to execute such acts and exercise such powers as may be necessary to carry out the purposes of this Act.\nThe Philippine Coconut Administration shall make studies and investigations of the enterprises or projects for which the loans, contributions and subscriptions to the capital of the enterprise/or investments mentioned in the preceding paragraphs are needed, and to determine the advisability of financing such enterprises or projects as provided in this Act."}},{"id":"PH-H1203-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Such shares contributed by the Philippine Coconut Administration to the capital of a partnership or shares of stock of a corporation subscribed by it shall be sold at any time at its actual market value or at least its par value to private individuals who are citizens of the Philippines who may desire to buy such shares: Provided, However , That in the sale of the said shares contributed by the Philippine Coconut Administration to the capital of a partnership or of the said shares of stock subscribed by it, the members of the partnership or the stockholders of the corporation, as the case may be, shall be given at least six months’ option within which to purchase the said shares in proportion to their respective holdings, but in the absence of such buyers, preference shall be given to residents of the locality or province where the partnership or corporation is located, as the case may be."}},{"id":"PH-H1203-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All loans authorized under this Act shall be made upon the security of a mortgage of, or deed of trust on, the assets of the enterprise to be established and operated with the proceeds of such loans: Provided, That the amount of each loan shall not exceed seventy per cent of the appraised value of real assets given as security: Provided, further, That the appraised value of said real assets shall be determined by the PHILCOA. All said loans shall be self-liquidating within a period of not to exceed ten years, and shall bear interest at the rate of six per centum per annum: Provided, However , That all such loans shall be on such terms and conditions relating to the expenditure of the moneys loaned as the Philippine Coconut Administration shall determine and may be made payable in whole or in part out of the income of the enterprise for the establishment and operation of which the loans were made: Provided, further, That said loans shall not be made or approved unless the Philippine Coconut Administration finds and certifies that in its judgment the security therefor is reasonably adequate and such loans will be repaid within the time agreed."}},{"id":"PH-H1203-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Philippine Coconut Administration is authorized and empowered to bid for and purchase at any foreclosure or other sale, or otherwise to acquire the enterprise, including all its property, pledged or mortgaged to secure any loan made pursuant to this Act; to pay the purchase price and any costs and expenses incurred in connection therewith from the sum appropriated in section one of this Act; to accept title to any enterprise, including all its property, so purchased or acquired in the name of the Government of the Philippines; to operate or lease such enterprise for such period as may be deemed necessary or advisable to protect the investment therein, but not to exceed five years after the acquisition thereof; and to sell such enterprise and all its property, so acquired, upon such terms and for such consideration as the Philippine Coconut Administration shall determine to be reasonable.\nNo borrower of funds under this Act shall, without the approval of the Philippine Coconut Administration, sell or dispose of its enterprise, property, or rights, acquired under the provisions of this Act, until any loan obtained from the said Philippine Coconut Administration, including all interest and charges, shall have been repaid."}},{"id":"PH-H1203-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"For the purpose of making the studies and investigations herein provided for, the Philippine Coconut Administration may request and utilize, with the approval of the proper Heads of Departments, free of charge, such services of national officers and employees and of officers and employees of any Government-owned or controlled corporation as are available, and such services so utilized shall be considered to have been rendered to the departments, bureaus or offices in which they are employed."}},{"id":"PH-H1203-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The Philippine Coconut Administration is empowered to issue the necessary rules and regulations to carry out the provisions of this Act. It shall present to the Congress at the close of each fiscal year a full report of its activities under this Act."}},{"id":"PH-H1203-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The penalty of imprisonment for one year to five years shall be imposed upon any person or persons found guilty of violating the provisions of this Act."}},{"id":"PH-H1203-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p16"};
  FT["PH-H1204"] = {"id":"PH-H1204","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1370_1955.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"设立促进音乐事业的公营公司并拨款十万比索作为其初始费用并为其他目的法案","en":"An Act Creating a Public Corporation for the Promotion of Music, and Appropriating the Sum of One Hundred Thousand Pesos for its Initial Expenses and for Other Purposes","orig":"An Act Creating a Public Corporation for the Promotion of Music, and Appropriating the Sum of One Hundred Thousand Pesos for its Initial Expenses and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1370","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1370_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1204-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby created a public corporation for the promotion of music, which shall be known as the Music Promotion Foundation, hereinafter referred to as the Foundation. Its principal office shall be in the City of Manila."}},{"id":"PH-H1204-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Foundation shall have perpetual succession, with power to sue and be sued; to hold such real and personal property as shall be necessary for corporate purposes; to receive real and personal property by gift, devise, or bequest; to solicit contributions without securing a permit from the Social Welfare Administrator; to adopt a seal and alter the same at pleasure; to promulgate and adopt by-laws, rules and regulations not inconsistent with the laws of the Philippines, and, generally, to do all such acts and things as may be necessary to carry into effect the provisions of this Act, and to promote the aims and purposes of the Foundation."}},{"id":"PH-H1204-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Foundation shall initiate, promote and stimulate the creation and rendition of good music by means of grants, loans and other forms of assistance to qualified persons and institutions applying therefor; shall encourage, protect and aid the organization of clubs and societies throughout the Philippines for the promotion of music; shall create scholarships in music for specially gifted citizens; shall build and operate a suitable theatre, to be known as the National Theatre of the Philippines; and shall from time to time conduct contests in musical composition and rendition, granting prizes to winning contestants in cash or in the form of scholarships. Whenever necessary, the Foundation may organize benefit concerts anywhere in the Philippines to raise funds for the payment of said prizes and maintenance of such scholarships, and, in general, for the attainment of the objectives of this Act."}},{"id":"PH-H1204-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All corporate powers of the Foundation shall be vested in, and exercised by, a Board of Trustees composed of nine outstanding artists of the Philippines to be appointed by the President with the consent of the Commission on Appointments, one from among the directors of leading conservatories of music, one conductor, one outstanding singer, one pianist, one violinist, one choreographer, one opera producer, one composer and one music patron. The Chairman of the Board shall be elected by the members from among themselves."}},{"id":"PH-H1204-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The first appointees to the Board shall serve as designated by the President in their respective appointments, three for a term of two years, three for a term of three years, and three for a term of four years from the date they qualify and assume office; but their successors shall be appointed for a term of six years, except that any person chosen to fill a vacancy in the Board shall serve only for the unexpired term of the member whom he succeeds. Each member shall, for each day of meeting actually attended by him, receive from the general fund of the Foundation a per diem of not more than twenty-five pesos: Provided, That no per diem shall be paid to any member for more than one meeting within a week."}},{"id":"PH-H1204-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The Board of Trustees shall have the power to make and amend the by-laws, rules and regulations of the Foundation, and, by a two-thirds vote of the whole Board at a meeting called for the purpose, may authorize the execution of mortgages and liens upon the property of the Foundation. The Board of Trustees may, by resolution passed by a majority of the whole Board, designate five or more of their number to constitute an executive committee, of which a majority shall constitute a quorum. To the extent provided in said resolution or in the by-laws of the Foundation, the executive committee shall have and exercise the powers of the Board of Trustees in the management of the business affairs of the Foundation. The Board of Trustees, by the affirmative vote of the majority of its entire membership, may appoint other standing committees, which shall have and may exercise such powers as shall be conferred upon them by the by-laws."}},{"id":"PH-H1204-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Any donation, contribution, subsidy or aid which from time to time may be made to the Foundation by the Government or any of its subdivisions, branches, offices, agencies, or instrumentalities, or by any person or entity, shall be administered by the Board of Trustees in pursuance of this Act."}},{"id":"PH-H1204-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"All donations, contributions, subsidies or aids which from time to time may be made to the Foundation shall be considered allowable deductions on the income of the donors or givers for income tax purposes; and other transactions undertaken by the Foundation in pursuance of its objectives shall be free from any and all taxes."}},{"id":"PH-H1204-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"All officers and employees of the Foundation shall be subject to the Civil Service Law and Rules, except those whose positions may, upon recommendation of the Board of Trustees, be declared by the President of the Philippines as policy determining, primarily confidential or highly technical in nature."}},{"id":"PH-H1204-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The Auditor General or his representatives shall check and audit all the accounts, funds and properties of the Foundation in the same manner and as frequently as the accounts, funds and properties of the Government are checked and audited under existing laws."}},{"id":"PH-H1204-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Out of any funds in the National Treasury not otherwise appropriated, the sum of one hundred thousand pesos is hereby appropriated as aid to the Foundation for its initial expenses."}},{"id":"PH-H1204-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating a Public Corporation for the Promotion of Music, and Appropriating the Sum of One Hundred Thousand Pesos for its Initial Expenses and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1205"] = {"id":"PH-H1205","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1371_1955.html","fetchedAt":"2026-10-06","articleCount":21,"structureMode":"ARTICLE","title":{"zh":"界定、分类、确定并规范菲律宾港口除关税、国内税与吨税以外一切收费与费用的法案","en":"An Act to Define, Classify, Fix and Regulate the Amount of All Charges and Fees in Philippine Ports, Other Than Customs Duties, Internal Revenue Taxes and Tonnage Dues","orig":"An Act to Define, Classify, Fix and Regulate the Amount of All Charges and Fees in Philippine Ports, Other Than Customs Duties, Internal Revenue Taxes and Tonnage Dues","vi":"Đạo luật xác định, phân loại, ấn định và điều chỉnh các khoản thu phí tại cảng Philippines, trừ thuế hải quan, thuế nội địa và phí trọng tải","th":"พระราชบัญญัติกำหนดนิยามจำแนกกำหนดและควบคุมค่าธรรมเนียมทั้งหมดในท่าเรือฟิลิปปินส์ยกเว้นอากรศุลกากรภาษีรายได้ภายในประเทศและค่าระวางตามระวางบรรทุก","id":"Undang-Undang yang menetapkan definisi, klasifikasi, besaran, dan pengaturan seluruh pungutan di pelabuhan Filipina selain bea cukai, pajak dalam negeri, dan bea tonase","ms":"Akta yang mentakrifkan, mengelaskan, menetapkan dan mengawal semua caj dan fi di pelabuhan Filipina selain duti kastam, cukai hasil dalam negeri dan fi tan muatan"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 1371","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 21 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1371_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1205-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Definitions. As used in this Act:\n(a) Harbor fee is the amount which the owner, agent, operator or master of a vessel has to pay for each entrance into or departure from a port of entry in the Philippines.\n(b) Wharfage charge is the amount assessed against the cargo of a vessel engaged in the foreign trade, based on the quantity, weight or measure received and/or discharged by such vessel. The owner, consignee, or agent of either, of the merchandise is the person liable for such charge.\n(c) Berthing charge is the amount assessed against a vessel for mooring or berthing at a pier, wharf, bulkheadwharf, river or channel marginal wharf at any port in the Philippines; or for mooring or making fast to a vessel so berthed; or for coming or mooring within any slip, channel, basin, river or canal under the jurisdiction of any port of the Philippines. The owner, agent, operator or master of the vessel is liable for this charge.\n(d) Storage charge is the amount assessed on merchandise for storage in customs premises, cargo sheds and warehouses of the government. The owner, consignee, or agent of either, of the merchandise is liable for this charge.\n(e) Arrastre charge is the amount which the owner, consignee, or agent of either, of merchandise or baggage has to pay for the handling, receiving and custody of the imported or exported merchandise or the baggage of the passengers.\nHarbor Fees"}},{"id":"PH-H1205-A2","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"PART I"},"text":{"en":"The following schedule of fees for each entrance into or departure from a port of entry in the Philippines is hereby established:\n(a) For each entrance from a foreign port P50.00 (b) For each departure to a foreign port\n50.00 (c) For each coastwise entrance or departure:\n(1) In case of vessel from 6 to 15 tons net\n1.00\n(2) In case of vessel more than 15 but not more than 75 tons net\n2.00\n(3) In case of vessel more than 75 but not more than 150 tons net\n4.00\n(4) In case of vessel more than 150 but not more than 200 tons net\n6.00\n(5) In case of vessel more than 200 but not more than 250 tons net\n10.00\n(6) In case of vessel more than 250 but not more than 300 tons net\n12.00\n(7) In case of vessel more than 300 but not more than 400 tons net\n16.00\n(8) In case of vessel more than 400 tons net\n20.00 Provided , That the following are exempt from the payment of such fees:\n(a) Vessels entering the port for the sole purpose of receiving bunker fuel and/or ship supplies or changing pilots, and remaining less than twenty-four hours in the port;\n(b) Vessels passing through the port and remaining less than twelve hours and not receiving or discharging cargo;\n(c) Vessels owned by the Philippine Government or any foreign government not engaged in carrying cargo, or passengers for hire; and\n(d) Private, non-commercial pleasure craft.\nWharfage Charges"}},{"id":"PH-H1205-A3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"PART II"},"text":{"en":"There shall be levied, collected and paid on all articles imported or brought into the Philippines, and on products of the Philippines, except coal, lumber, creosoted and other pressure treated materials as well as other minor forest products, cement, guano, natural rock asphalt, the minerals and ores of base metals (e.g., copper, lead, zinc, iron, chromite, manganese, magnesite and steel), and sugar molasses, exported from the Philippines, a charge of two pesos per gross metric ton as a fee for wharfage: Provided , That in the case of logs, or flitches twelve inches square or equivalent cross-sectional area, or over, a charge of sixty centavos per cubic meter shall be collected: Provided, further , That such wharfage fee shall not be levied on articles imported or brought into the Philippines which are unloaded on private wharves.\nBerthing Charges"}},{"id":"PH-H1205-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"PART III"},"text":{"en":"Vessels in Foreign Trade. (a.) Every vessel engaged in foreign trade which berths at a pier, wharf, bulkhead-wharf, river or channel marginal wharf at any national port in the Philippines provided with cargo sheds, or which makes fast to any vessel lying at such wharf or pier, for the purpose of discharging and/or loading cargo shall pay a berthing fee of four centavos per registered gross ton of the vessel for the first twenty-four hours or part thereof, and for each succeeding twenty-four hours or part thereof exceeding three hours: Provided , That the maximum charge shall not exceed four hundred pesos per day;\n(b) Every vessel engaged in foreign trade which berths at a pier, wharf, bulkhead-wharf, river or channel marginal wharf at any national port in the Philippines without cargo sheds, or which makes fast to any vessel lying at such wharf or pier, for the purpose of discharging and/or loading cargo shall pay a berthing fee of three centavos per registered gross ton of the vessel for the first twenty-four hours or part thereof, and for each succeeding twenty-four hours or part thereof exceeding three hours: Provided , That the maximum charge shall not exceed three hundred pesos per day.\n(c) Whenever any vessel referred to in the preceding subsections (a) and (b) is stopped by the customs authorities from discharging cargo to avoid congestion on the piers or for other justifiable causes, such vessel shall be exempt from the payment of berthing fees during the period of such suspension, unless in the meantime it loaded cargo at shipside or from the piers. In such case the wharfinger shall indicate in his report the time when the vessel stopped discharging cargo and the time it resumed said activity, and whether or not the vessel loaded cargo during the suspension of the loading operations."}},{"id":"PH-H1205-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"PART III"},"text":{"en":"Non-Cargo Vessels. Every vessel engaged in foreign trade which berths at a pier, wharf, bulkhead-wharf, river or channel marginal wharf at any national port in the Philippines, or which makes fast to any vessel lying at such wharf or pier, for the sole purpose of landing and/or taking passengers, or for taking fresh water or fuel for bunkers shall pay a berthing fee of two centavos per registered gross ton of the vessel: Provided , That such vessel does not remain at such berth more than eight hours; but if such vessel remains at such berth more than eight hours, the same berthing fee shall be paid as is provided in section four, subsection (a), hereof for cargo vessels whether the wharf or pier is with or without cargo shed: Provided, further , That the maximum charge shall not exceed two hundred pesos per day."}},{"id":"PH-H1205-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"PART III"},"text":{"en":"Vessels in the Philippine Coastwise Trade. (a.) Every vessel propelled by steam or internal combustion engine and engaged in the Philippine coastwise trade, excepting boats of five tons gross or less or pleasure or non-commercial craft, which berths at a pier, wharf, bulkhead wharf, river or channel marginal wharf at any national port in the Philippines provided with cargo sheds or which makes fast to any vessel at such wharf, or pier, for the purpose of loading or discharging cargo or for any other purpose except when in distress shall pay a berthing fee of one centavo per registered gross ton of the vessel for the first twenty-four hours or part thereof, and one-half centavo per registered gross ton for each succeeding twenty-four hours or part thereof: Provided , That the maximum charge shall not exceed one hundred pesos for the first day and fifty pesos for each succeeding day or part thereof, nor shall the minimum charge be less than ten pesos for the first day and five pesos for each succeeding day or part thereof: Provided, further , That steam or motor vessels subject to berthing fees as herein prescribed, of less than one hundred gross tons, shall be subject to a minimum charge of not less than two pesos for the first day and one peso for each succeeding day or part thereof.\n(b) Each vessel propelled by steam or internal combustion engine and engaged in coastwise trade which berths at a pier, wharf, bulkhead-wharf, river or channel marginal wharf without a cargo shed at any national port, or which makes fast to any vessel lying at such wharf or pier for any purpose, except those specifically exempted in the preceding subsection, shall pay a berthing fee on one-half centavo per registered gross ton of the vessel for the first twenty-four hours or part thereof, and one-fourth centavo per registered gross ton of the vessel for each succeeding twenty-four hours or part thereof: Provided , That the maximum charge shall not exceed twenty-five pesos for the first day and twelve pesos for each succeeding day or part thereof, nor shall the maximum charge be less than two pesos for the first day and one peso for each succeeding day or part thereof: Provided, further , That steam or motor vessels subject to berthing fee as herein prescribed, of less than one hundred gross tons, shall be subject to a minimum charge of not less than one peso for the first day and fifty centavos for each succeeding day or part thereof.\n(c) Every vessel propelled by steam or internal combustion engine and engaged in the bay and river trade or operating in the daily ferry service, which berths at a pier, wharf, bulkhead-wharf, channel or river marginal wharf or without cargo sheds at any national port, or which makes fast to any vessel lying at such wharf or pier more than once every twenty-four hours, except those specifically exempted in subsection (a) hereof, shall be subject to the payment of a berthing fee equivalent to fifty per centum of the rates prescribed by the preceding subsections (a) and (b), as the case may be; the rates for the first twenty-four hours or part thereof, applicable on the first day of each month and rates for each succeeding day or part thereof, applicable to each succeeding day of the month up to and including the last day: Provided , That when such vessels leave their berth and do not take berth again within twenty-four hours from the time they leave their berth, they shall be subject to the rates prescribed for the first twenty-four hours when they return and berth again at the wharf or pier or make fast to any vessel lying at such wharf or pier.\nStorage Charges"}},{"id":"PH-H1205-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"PART IV"},"text":{"en":"At Manila. (a.) Consignments of merchandise, or parts thereof, which remain in any of the government piers or other customs premises shall be entitled to a free storage period of six working days after the cargo of the vessel from which such merchandise was landed has been officially declared as discharged. After the said free storage period, the storage rate per ton, per day shall be as follows:\nPer ton Merchandise not designated for Examination For the first nine days P0.25 Thereafter, to the date of completion of the processing of the entry by the Marine Division, as stamped on the delivery permit\n0.50 From the date of completion of the processing of the entry by the Marine Division to the date of delivery\n1.00 Provided , That if an importer or broker demands delivery within the free storage period of six working days by filing his delivery permit and having sufficient means of transportation to withdraw his merchandise from the piers, is prevented from withdrawing the merchandise because of the congestion of the cargo and/or traffic in the piers, the six-day free storage period herein provided shall be extended for the duration of such congestion upon certification by the wharfinger to the Collector of Customs of the existence of such congestion. The Surveyor of the Port, acting in behalf of the Collector of Customs, may, from time to time, extend the six-day free storage period, upon the petition of the importers or brokers, if in his opinion the condition of the piers does not permit movement of merchandise due to congestion or other causes beyond the control of the importers or brokers during that period: Provided, further , That the storage charges on consignments of merchandise for which no entries are filed within ten days after the cargo of the importing vessels has been officially declared as discharged shall be assessed as provided in section ten (i) hereof: Provided, further , That in no case shall storage charged be assessed at less than one peso on any single package of less than 3.334 tons or at less than two pesos on any consignment consisting of two or more packages of less than 6.667 tons for any day or fraction thereof: Provided, finally , That storage charges shall not be collected on merchandise designated for examination, except as provided in subsection (b) hereof.\nThe Surveyor of the Port, immediately upon receipt of advice of the wharfinger as to the time of the completion of discharge of cargo from a vessel lying alongside the pier or bulkhead, shall cause to be posted a notice at the piers and in the customhouse announcing that fact and giving the date upon which storage charged on cargo from such vessel will begin.\n(b) Goods, packages, or parts of consignments designated for examination which are removed from the piers or customs premises within the six-day free storage period as provided in subsection (a) or within forty-eight hours after examination, exclusive of Sundays and legal holidays, shall not pay storage charges. Thereafter, the same shall be subject to storage charge at the rate of one peso per ton per day: Provided , That no storage shall be charged on the articles above referred to if the aggregate weight of those pertaining to one consignment is less than one kilo.\n(c) Goods, packages, or parts of consignments already released for delivery to the importers, which are subsequently held for reexamination by authorized customs officers shall not pay storage during the period of suspension of their delivery, but if they are not removed from the customs premises within forty-eight hours after their release by the withholding officers, storage shall be paid thereon thereafter at the rate of one peso per ton per day.\n(d) Packages and articles, whether manifested or not, or shipstores weighing more than one kilo remaining in the parcel office or the Appraiser's Division for more than five working days after their receipt therein, shall pay the following rates:\n(1) Packages or articles weighing from one kilo to ten kilos, P0.05 each, per day; and\n(2) Packages or articles weighing more than ten kilos, P0.10 each, per day:\nProvided , That every package or article not taken within the free storage period of five working days provided in this subsection shall be subject to storage charge of at least fifty centavos in the case of those weighing from one kilo to ten kilos and one peso in the case of those weighing more than ten kilos.\n(e) Parcels and packages received by mail through the Post Office, which remain in the Parcel Office of the Appraisers' Division for more than fifteen working days after their receipt therein, shall pay the following rates:\n(1) Parcels or packages weighing ten kilos or less, P0.02 per day; and\n(2) Parcels or packages weighing more than ten kilos P0.05 per day:\nProvided , That each parcel or package shall, if not taken within the fifteen-day free storage period provided in this subsection, be subject to storage charge of not less than forty centavos in the case of those weighing ten kilos or less, and one peso in the case of those weighing more than ten kilos.\n(f) Consignments of merchandise, or parts thereof, which are transferred to general bonded warehouses and remain therein beyond the free storage period of six working days provided in subsection (a) shall pay storage charges at the rate fixed in the contract entered into between the Bureau of Customs and the operator of the general bonded warehouse. Where no such contract exists, the storage charge shall be at the rate of fifty centavos per ton per day."}},{"id":"PH-H1205-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"PART IV"},"text":{"en":"At Cebu, Iloilo, Zamboanga, Davao, Jolo, Tabaco, Legaspi, Jose Panganiban, Aparri, Tacloban, San Fernando, and Cagayan de Oro. (a.) Consignments of merchandise, or parts thereof, not designated for examination, which remain on customs premises, government warehouses, or on the piers for more than four working days after the discharge of the last package of the consignment upon the customs wharf or piers, shall pay at the rate of ten centavos per ton per day: Provided , That in no case shall storage charges be assessed at less than thirty-five centavos on any single package of less than 3.334 tons or at less than seventy centavos on any consignment consisting of two or more packages of less than 6.667 tons on any day or fraction thereof.\n(b) Goods, packages, or parts of consignments designated for examination which remain in the appraiser's stores or on the piers for more than forty-eight hours after examination, shall be subject to storage charge at the rate of twenty centavos per ton per day: Provided , That in case said articles are taken from the appraiser's stores or the piers within the said forty-eight hours, excluding Sundays and holidays, after the examination, the same shall be exempt from storage charges: Provided, further , That no storage charge shall be assessed on any of the articles herein referred to prior to the expiration of the free storage period of four working days provided in this subsection, although forty-eight hours have already elapsed after the examination of said articles.\n(c) Packages and articles, whether manifested or not, or shipstores remaining in customs premises for more than five working days after their receipt therein, shall pay storage charge at the rate of ten centavos per piece or parcel per day: Provided , That there shall be no charge on packages or articles weighing less than one kilo.\n(d) Parcels and packages received by mail through the Post Office, which remain in the Appraisers' Division for more than fifteen days after their receipt therein, shall pay storage charge at the rate of five centavos per day: Provided , That such parcels and packages, except those weighing less than one kilo, if not taken within the fifteen-day period from the date they are received in the Appraisers' Division, shall be subject to storage charge of not less than one peso. No storage shall be charged on parcels or packages weighing less than one kilo.\n(e) Goods, packages, or parts or consignments designated for examination which remain in the appraisers' stores more than forty-eight hours after the liquidation of the entry has been posted at the Liquidation Office, shall pay at the rate of twenty centavos per ton per day: Provided , That all goods, packages or parts of consignments so remaining shall be subject to storage charges of not less than one peso: Provided, further , That no storage shall be charged on such goods, packages or parts of consignments, until the expiration of forty-eight hours after the liquidation of the entry has been posted at the Liquidation Office."}},{"id":"PH-H1205-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"PART IV"},"text":{"en":"At all Ports of Entry. Packages known as baggage or arriving as such, which remain in customs custody after their receipt on customs premises at any port of entry in the Philippines, including the customs office at Aparri, Tacloban and Jose Panganiban, shall be free from storage charges during the first forty-eight hours after their receipt therein. Thereafter, there shall be paid the following rates per day, including Sundays and holidays:\nNot exceeding 60 cubic decimeters in bulk P0.05 each; Minimum charge P0.35 More than 60 to 120 cubic decimeters in bulk P0.10 each; Minimum charge\n0.70 More than 120 cubic decimeters in bulk P0.15 each; Minimum charge\n1.05 Provided , That all steamer chairs and wooden frames covered with can, cloth, or canvas, of the folding variety, shall pay at the rate of two centavos each per day, the minimum to be not less than fifteen centavos: Provided, further , That if such baggage, steamer chairs, and wooden frames are held in bond for a period of more than thirty days, storage charges shall accrue thereon from the time of their delivery into customs custody."}},{"id":"PH-H1205-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"PART IV"},"text":{"en":"General Provisions. (a.) Merchandise, supplies or materials imported by any branch of the Philippine Government, except those imported by Philippine government entities which are intended for commercial or profit making purposes, shall be exempt from storage charges: Provided , That whenever such consignments shall have been imported by other than the Philippine Government or branches thereof, or for sale thereto, storage shall be charged thereon as hereinabove provided.\n(b) Transit consignments manifested as such for any Philippine port of entry shall be exempt from storage charges at the first port of arrival if forwarded to the port of destination within six days, including Sundays and holidays, after the cargo of the importing vessel has been officially declared to be discharged. Thereafter storage charges shall accrue thereon at the rate of fifty centavos per ton per day.\n(c) Foreign transit cargo landed at any port of entry in the Philippines destined for foreign ports shall be exempt from storage charges if forwarded to its destination within ten days, including Sundays and holidays, after the cargo of the importing vessel has been officially declared as discharged. Thereafter storage charges shall accrue thereon at the rate of fifty centavos per ton per day.\n(d) Overlanded or misimported cargo not destined for the Philippines shall be exempt from storage charges if re-exported within six days, including Sundays and holidays, after the carrying vessel has been officially declared as discharged. Thereafter, storage charges shall accrue thereon at the rate of fifty centavos per ton per day.\n(e) Unmanifested cargo intended for the Philippines or of unknown destination, if claimed by steamship agents for local consumption shall, if released by the Collector of Customs, be treated as regular imported cargo, subject to the rates of storage charges fixed as hereinbefore provided. If claimed by said ship agents for re-exportation, the same shall be governed either by subsections (c) or (d) hereof, as the case may be.\n(f) All other unclaimed merchandise, including overlanded cargo, the destination of which is unknown, if not claimed within thirty days after arrival of the importing vessel, shall pay storage charges from the date the cargo of the carrying vessel is officially declared as discharged to the time authority is issued permitting entry to be filed therefor. From the date it is permitted to be entered, unclaimed merchandise shall be treated as though originally landed on that date and shall be granted five working days' grace (except when sold at public auction) before storage charge again accrues, with a reduction of not exceeding ten per cent on account of their being packages designated for examination.\n(g) Packages designated for examination shall not include those the delivery of which is suspended pending compliance with customs regulations, and which are not otherwise exempt from the payment of storage charges. Storage charges shall not, however, accrue on such packages during the suspension of delivery until after the expiration of three days immediately following the date of notice of release to importer. Packages which remain in customs premises, pursuant to Philippine Health Service regulations or to regulations promulgated by other government bureaus or offices, shall be exempt from the payment of storage charges during the time such regulations are being complied with.\n(h) Storage charge at the daily rate of one peso per ton shall accrue on all goods remaining in the auction room if not removed on the day following the date of the completion of sale.\n(i) Any consignment of merchandise, with the exception of those mentioned in subsections (a), (b), (c), (d), (e), (f), and (g) hereof, for which no entry has been filed within ten days after the cargo of the steamer from which such merchandise was landed has been officially declared as discharged, or if the entry therefor has been filed but the consignment remains at the piers, bulkheads, warehouses, or other customs premises, for a period of more than twenty days after the cargo of the vessel has been officially declared as discharged, shall be subject to storage charge at the rate of one peso per ton per day thereafter: Provided, however , That in ports of entry other than Manila, the rate of storage to be charged shall not exceed twenty-five centavos per ton per day.\n(j) Merchandise brought to a pier or bulkhead for export and not loaded on a vessel within seventy-two hours shall thereafter pay storage charges up to the hour of loading at the rate of twenty-five centavos per ton per day, or part thereof. Any merchandise sent to the piers or bulkheads for shipment and not loaded on the exporting vessel for which it was intended must be removed from the pier or bulkhead within seventy-two hours after the departure of said vessel, and if not so removed shall be subject to a storage charge of fifty centavos per ton per day, or part thereof, thereafter.\n(k) Coastwise cargo discharged at a national port, whether a port of entry or not, which remains on the government pier, wharf or other customs premises for more than two working days after discharge of all consignments from the carrying vessel shall pay a storage charge of one peso per ton per day or part thereof. Coastwise cargo brought to a pier or wharf for shipment to another port and not loaded on the vessel for which it was intended shall, if not removed from the pier or wharf within twenty-four hours after the departure of the said vessel, pay a storage charge of one peso per ton per day or fraction thereof.\n(l) The storage charges hereinbefore prescribed accruing on cargo which has not been withdrawn or removed from the customs premises in due time, may, for good reasons, be reduced or remitted by the Collector of Customs, subject to the approval of the Commissioner of Customs and of the Auditor General: Provided , That in case of reduction, the amount corresponding to such reduction shall not be in excess of fifty per cent nor less than ten per cent of the storage liability of the importer or consignee.\n(m) For purposes of the assessment of the storage charges hereinbefore provided, the term \"ton\" shall be taken to mean a ton of one thousand kilos or the American measurement ton of 1.1326124 cubic meters (40 cubic feet), whichever is greater.\nArrastre Charges"}},{"id":"PH-H1205-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"PART V"},"text":{"en":"Port of Manila.\n(a.) Imported Cargo. The following shall be the schedule of charges for receiving merchandise from ship's tackle or ex-lighters, distributing and stacking same on said piers and wharves, and rehandling same from said piers or wharves, unto consignee's or agent's transportation or unto transportation furnished by bonded warehouses:\n(1) General cargo, except as specifically mentioned hereunder, per ton of 40 cubic feet or 1,000 kilos at the rate of P4.90\n(2) Provided , That on any single consignment weighing 250 kilos or less, or measuring 10 cubic feet or less the charge shall be\n2.85\n(3) Provided , That on any single consignment weighing 500 kilos or less, or measuring 20 cubic feet or less, but more than 250 kilos or 10 cubic feet the charge shall be\n3.00\n(4) Provided , That on any single consignment weighing 750 kilos or less, or measuring 30 cubic feet or less, but more than 500 kilos or 20 cubic feet the charge shall be\n3.75\n(5) Provided , That on any single consignment weighing 1,000 kilos or less, or measuring 40 cubic feet or less, but more than 750 kilos or 30 cubic feet the charge shall be\n4.50\n(6) And Provided , That any consignment consisting of a single package weighing less than 10 kilos shall not be subject to any charge:\nProvided however, That the following shall be subject to the special charges hereunder listed:\n(1) Coffee and cocoa beans in sacks, per ton of 1,000 kg.\n4.50\n(2) Eggs in baskets, per ton of 40 cubic feet\n2.70\n(3) Flour in sacks, per ton of 1,000 kilos\n3.50\n(4) Wood furniture, and wood and metal empty containers, per ton of 40 cubic feet\n3.50\n(5) Bamboo and wicker furniture, per ton of 40 cubic feet\n3.00\n(6) Newsprint paper in rolls, not less than 34\" in length, 24\" in circumference, per ton of 1,000 kilos\n4.00\n(7) Hay in bales, per ton of 40 cubic ft.\n2.50\n(8) Hempt not in bales, per ton of 1,000 kilos\n4.50\n(9) Horses, cattle and carabaos, ordinary, uncrated, per head\n1.20\n(10) Horses, cattle and carabaos, etc., for breeding and/or exhibition purposes, uncrated, per head\n4.50\n(11) Horses, cattle, carabaos, etc., for breeding and/or exhibition purposes, crated, per ton of 40 cubic feet\n3.00\n(12) Pigs, sheep, goats etc., ordinary, un- crated, per head .60\n(13) Pigs, sheep, goats, etc., for breeding and/or exhibition purposes, crated, per ton of 40 cubic feet\n2.50\n(14) Pigs, sheep, goats, etc., for breeding and/or exhibition purposes, uncrated, per head\n2.50\n(15) Infusorial earth and asbestos cement per ton of 40 cu. ft. or 1,000 kilos P2.40\n(16) Iron and steel bars and bundles, pipes and pipe fittings singly or in bundles, without marks or with illegible marks or various consignments or marks landed mixed up, to be received in the open and sorted out by invoice assort- ment and specification for proper de- livery, per ton of 1,000 kilos or 40 cu. ft.\n5.60\n(17) General cargo packed in cartons of 40 cu. ft.\n7.20 (b) Lighter Deliveries. All merchandise stored in the piers or wharves and delivered into lighters, cascos, etc., shall pay in addition to the above charges per ton of 40 cu. ft. or 1,000 kilos\n1.00 (c) Export Cargo. For handling of merchandise for export from consignor's transportation upon the piers or wharves to the slings of the exporting vessel:\n(1) General cargo, except as specially men- tioned hereunder, per ton of 40 cu. ft., or 1,000 kilos\n3.30\n(2) Provided , That there shall be a minimum charge of\n2.00 Provided, however , That the following shall be subject to the special charges hereunder listed:\n(1) Coffee and flour in sacks, per ton of 1,000 kilos\n2.00\n(2) Wood furniture and wood and metal empty containers, per ton of 40 cu. ft.\n(3) Bamboo and wicker furniture, per ton of 40 cu. ft.\n1.60\n(4) Hemp, not in bales, per ton of 1,000 kilos\n2.50\n(5) Horses, cattle and carabaos, per head\n2.00\n(6) Horses, cattle and carabaos, etc., for breeding and/or exhibition purposes, uncrated, per head\n5.00\n(7) Horses, cattle, carabaos, etc., for breeding and/or exhibition purposes, crated, per ton of 40 cu. ft.\n3.00\n(8) Pigs, sheep, goats, etc., per head\n0.60\n(9) Pigs, sheep, goats, etc., for breeding and/or exhibition purposes, uncrated, per head\n3.00\n(10) Pigs, sheep, goats, etc., for breeding and/or exhibition purposes, crated, per ton of 40 cu. ft.\n3.00 (d)\n(1) When transit cargo for inter-island ports is landed on one pier or wharf and is loaded onto the forwarding ves- sel berthed at the time at the same pier or wharf, the contractor shall place the same onto the forwarding trans- portation or onto the slings of the forwarding vessel at the rate of, per ton of 40 cu. ft. or 1,000 kilos\n4.00 Provided , That there shall be a minimum charge of\n4.00\n(2) When transit cargo for inter-island ports is landed on one pier or wharf and is transferred to another pier or wharf for loading onto the forwarding vessel berthed at the time at the latter pier or wharf, the contractor shall place the same onto the transfer transportation furnished by the agent and/ or importers, receive the same from such transfer transportation and place the same into the slings of the for- warding vessel at such other pier or wharf at the rate of, per ton of 40 cu. ft. or 1,000 kilos\n5.00\n(3) The charge of handling transit cargo for foreign ports including service of \"Arrastre\", recouping or reconditioning of cargo, transfer from pier to pier, and transfer to and from bonded warehouse, shall be at the rate of, per ton of 40 cu. ft. or 1,000 kilos\n12.50 (e) Heavy Cargo. On any single package of import, export, transit cargo, weighing more than two tons, handled on a pier or wharf, the harge shall be, per ton or any fraction thereof\n13.50 Provided , That this charge shall not apply to automobiles, motor trucks and transit cargo for coastwise ports.\n(f) Shipside Charges. There shall be collected on all import cargo falling under Customs Administrative Order Numbered One hundred thirty-seven (old series), as amended by Customs Administrative Order Numbered One hundred thirteen, and other subsequent Customs Administrative Orders relative to shipside delivery, the following charge\n0.60 (g) Pier Lighting Services. For lights furnished on piers or wharfs for the purpose of working cargo, when loading or unloading vessel or vessels at night:\nFor pier lighting service, per hour\n4.00 For cluster lights furnished, per cluster\n0.80 (h) Water Service. For fresh water furnished to vessel, berthed at pier or wharf per ton\n0.40\n(i) Other Services.\n(1) For use of landing skids, per skid\n30.60\n(2) For issuance of short-landed certificates, per certificate\n0.50\n(3) For making fast and letting go lines, per berthing\n40.00"}},{"id":"PH-H1205-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"PART V"},"text":{"en":"Port of Cebu.\n(a.) Import Cargo (including transit import cargo.) For receiving imported merchandise from ship's tackle or ex-lighters, distributing and stacking same on said piers and wharves, and rehandling same from said piers or wharves onto consignee's or agent's transportation or onto transportation furnished by bonded warehouses:\n(1) General Cargo. (per ton of 40 cu. ft. or 1,000 kilos):\n(a) Wharf delivery P3.00\n(b) Pier delivery (only 10 per cent of the total quantity to be charged)\n4.80 Provided , That,\n(c) Any single consignment weighing\n(1) From 10 to 250 kilos\n2.50\n(2) From 251 to 375 kilos\n3.25\n(3) From 376 to 500 kilos\n4.00\n(4) From 501 to 625 kilos\n4.75\n(5) From 626 to 750 kilos\n5.50\n(6) From 751 to 875 kilos\n6.25\n(7) From 876 to less than 1,000 kilos\n7.00\n(d) Heavy machinery and other heavy lifts, per ton of 40 cu. ft. or 1,000 kilos\n10.000\n(e) Cargoes discharged at the wharf and taken into the piers or customs warehouses, per ton of 40 cu. ft. or 1,000 kilos\n12.00\n(2) Specific cargoes. (Per bag, bundle, keg, sack, bale, piece, package):\n(a) Chinaware in bundles; paint in kegs of 1 gallon; matches in tins; wharf or pier delivery per bundle, keg, tin or unit P0.08\n(b) Flour in bags of 50 lbs., per bag\n0.08\n(c) Flour in bags of 100 lbs., per bag\n0.15\n(d) Sardines, salmon, milk and others in cases or packages of groceries, hardware, and machinery parts of the same approximate size and weight, wharf or pier delivery per case, package or unit\n0.12\n(e) Potatoes and onions in crates or cases, wharf or pier delivery, per crate or case or unit\n0.15\n(f) Rice and other sacks of the same approximate size and weight, not to exceed 60 kilos, wharf or pier delivery per sack or unit\n0.15\n(g) Rice and other sacks of the same approximate size and weight, weighing 80 kilos up, per sack or unit\n0.28\n(h) Barbed wire in bundles not exceeding 45 lbs; and auto tires in loose; per bundle or unit, wharf or pier delivery P0.15\n(i) Cement in barrels, wharf or pier delivery, per barrel\n0.20\n(j) Cement in paper bags, wharf or pier delivery, per bag\n0.12\n(k) Linseed oil in 5-gal. drums and other drums of the same approximate size and weight, wharf or pier delivery, per drum\n0.14\n(l) Bricks in loose, wharf or pier elivery per piece\n0.30\n(m) Oil and other contents of 50 to 55-gal. drums, wharf or pier delivery, per ton of 1,000 kilos\n3.00\n(n) Caustic soda and asphalt in drums of no less than 230 kilos, pier or wharf delivery, per ton of 1,000 kilos\n3.50\n(o) Gunnies and textiles in bales from 150 kilos up, wharf or pier delivery, per ton of 1,000 kilos\n3.50\n(p) Cocoa beans, corn flour, and cornstarch in bags wharf or pier delivery, per ton of 1,000 kilos\n3.00\n(q) Galvanized iron in crates or in loose; galvanized wire in coils, wharf or pier delivery, per ton of 1,000 kilos\n3.00 Salt in sacks of not more than 33 kilos, per sack\n0.10 Milk in cases \"Nestle\" brand, per case\n0.09 Beer in cans, per carton\n0.08 Beer in bottles, per carton\n0.10 (b) Valuable cargo. The charges for each package of gold, silver, precious stones, precious metals, jewelry, treasury notes of any kind, bank notes, securities, bullion or specie or any other cargo whose value has been declared at P500 or more shall be:\nFor the first P500\n3.00 For every P500 or fraction thereof thereafter\n3.00 (c) Other Services. For the issuance of short-landed certificates, per certificate\n0.50"}},{"id":"PH-H1205-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"PART V"},"text":{"en":"Port of Zamboanga.\n(a.) Imports, including import transit cargoes.\n(1) General cargoes:\n(a) Wharf delivery, per ton of 1,000 kilos\n1.00\n(b) Single consignment weighing:\nFrom 10 to 250 kilos\n1.00 From 251 to 500 kilos\n2.50 From 501 to 750 kilos\n4.00\n(c) Heavy machinery and other heavy lifts, per ton\n10.00\n(2) Specific cargoes.\n1.00\n(a) Flour, sugar and rice, bags or sacks of 50 lbs. or less, per bag\n0.05\n(b) Flour, sugar, and rice, bags or sacks of 100 lbs. or less, per bag\n0.01\n(c) Milk, sardines, cases of groceries, hardware and machinery parts of the same approximate size and weight, per case\n0.05\n(d) Cement, in barrels, per barrel\n0.20\n(e) Cement, in bags, per bag\n0.10\n(f) Oils and other contents in drums of 50 to 55 gals., per ton of 1,000 kilos\n1.00\n(g) All others in drums less than 250 kilos, per ton of 1,000 kilos\n1.50\n(h) Galvanized iron sheets, pipes, etc., per ton\n1.00\n(i) Gunnies and textiles in bales per ton of 1,000 kilos\n1.50 Provided , That, (1) Specific cargoes rates shall only be applied for wharf delivery.\n(2) Additional two hundred per cent to the specific cargoes rates shown above shall be charged only when cargo is taken to or from customs warehouse or owner's bodega, and\n(3) Additional fifty per cent to the above rates shall be charged in case service is done during overtime period.\n(b.) Merchandise for export. For handling of merchandise for export from consigner's transportation upon the piers or wharves to the slings of the exporting vessel:\n(1) General cargo, except as specifically mentioned hereunder per ton of 40 cu. ft., or 1,000 kilos\n0.20\n(2) Provided , That there shall be a minimum charge of\n0.20\n(3) Provided , That the service shall consist only of the labor in hooking the net or sling containing the cargo from the carrying truck to the ship's tackle."}},{"id":"PH-H1205-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"PART V"},"text":{"en":"Port of Davao. (a.) Import Cargo (including transit import cargo.) (1) For receiving imported merchandise, including transit import cargo, from ship's tackle or ex-lighters to the pier or wharf, and rehandling same from said pier or wharf onto consignee's or agent's transportation during the regular office hours, per ton of 40 cu. ft. or 1,000 kilos P2: Provided , That when the service is rendered after office hours or during Sundays or legal holidays, the rate shall be, per ton of 40 cu. ft. or 1,000 kilos P3: Provided, further , That there shall be collected a minimum charge of P1 on merchandise consisting of a single consignment and weighing less than one ton.\n(2) For rehandling imported merchandise, including transit import cargo, from the pier or wharf to the customs warehouse onto consignee's or agent's transportation, during regular office hours, per ton of 40 cu. ft. or 1,000 kilos P1: Provided , That when the service is rendered after office hours or during Sundays or legal holidays, the rate shall be, per ton of 40 cu. ft. or 1,000 kilos P2: Provided, further , That there shall be collected a minimum charge of P0.50 on merchandise consisting of a single consignment and weighing less than one ton.\n(3) Rate of charges for all merchandise stored in the pier or wharf and delivered onto lighters or cascos, per ton of 40 cu. ft. or 1,000 kilos P1: Provided , That when the service is rendered after office hours or during Sundays or legal holidays, the rate shall be, per ton of 40 cu. ft. or 1,000 kilos P1.50: Provided, further , That there shall be collected a minimum charge of P0.50 on merchandise consisting of a single consignment and weighing less than one ton.\n(4) For the issuance of short-landed certificates, per certificate P0.50\n(5) For making fast lines at Sasa Wharf, per berthing\n25.00\n(6) For letting go lines at Sasa Wharf, per unberthing\n25.00\n(7) For use of tugs in berthing or to assist in pulling away from wharf, when such assistance is requested by the master or vessel's agents, provided time shall start at the hour the tug requested to be on standby, per hour\n25.00"}},{"id":"PH-H1205-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"PART V"},"text":{"en":"Port of Iloilo.\n(a.) Import Cargo. For receiving imported merchandise from the ship's tackle or ex-lighters, distributing and stacking same on said piers and wharves, and rehandling same from said pier or wharf onto consignee's or agent's transportation or onto transportation furnished by bonded warehouse:\nDischarged\nFrom the vessel or pier direct to the wharf From the vessel thru the lighter to wharf or pier\n(1) General cargo, except as specifically mentioned hereunder, per ton of 40 cu. ft. or 1,000 kilos at the rate of P3.00 P2.00\n(2) Provided , That on any single consignment weighing 250 kilos or less, or measuring 10 cu. ft. or less, the charge shall be\n1.40\n0.95\n(3) Provided , That on any single consignment weighing 375 kilos or less, or measuring 16 cu. ft. or less, but more than 250 kilos or 10 cu. ft., the charge shall be\n1.75\n1.15\n(4) Provided , That on any single consignment weighing 500 kilos or less, or measuring 20 cu. ft. or less, but more than 375 kilos or 15 cu. ft., the charge shall be\n2.20\n1.55\n(5) Provided , That on any single consignment weighing 1,000 kilos or less or measuring 40 cu. ft. or less, but more than 500 kilos or 20 cu. ft., the charge shall be\n2.50\n1.85\n(6) And provided , That any consignment consisting of a single package weighing less than 10 kilos shall not be subject to any charge: Provided , That the following shall be subject to the special charges hereunder listed:\n(1) Automobiles and motor trucks boxed or unboxed, crated or uncrated, per ton of 1,000 kilos\n3.00\n2.00\n(2) Coffee and cocoa beans in sacks, per ton of 1,000 kilos P3.00 P2.00\n(3) Eggs, in baskets, per ton of 40 cubic feet\n2.00\n1.35\n(4) Flour in sacks, per ton of 1,000 kilos\n2.25\n1.50\n(5) Wood furniture, and wood and metal empty containers, per ton of 40 cubic feet\n1.80\n1.20\n(6) Bamboo and wicker furniture, per ton of 40 cu. ft.\n1.00\n0.65\n(7) Newsprint paper in rolls, not less than 34\" in length and 24\" in circumference, per ton of 1,000 kilos\n2.20\n1.50\n(8) Hay in bales, per ton of 40 cubic feet\n1.00\n0.65\n(9) Hemp not in bales, per ton of 1,000 kilos\n3.00\n2.00\n(10) Horses, cattle and carabaos, etc., for breeding and/or exhibition purposes, uncrated, per head\n2.80\n1.90\n(11) Horses, cattle, and carabaos, ordinary, uncrated, per head\n0.60\n0.40\n(12) Horses, cattle, carabaos, etc., for breeding and/or exhibition purposes, crated, per ton of 40 cu. ft.\n2.80\n1.90\n(13) Pigs, sheep, goats, etc., ordinary, uncrated, per head\n0.30\n0.20\n(14) Pigs, sheep, goats, etc., for breeding and/or exhibition purposes, uncrated, per head\n1.80\n1.20\n(15) Infusorial earth and asbestos cement, per ton of 40 cu. ft. or 1,000 kilos\n1.40\n0.95\n(16) Iron and steel bars and bundles, pipes and pipe fittings, singly or in bundles, without marks or of various consignments or marks landed mixed up, to be received in the open and sorted out by invoice assortment and specification for proper delivery, per ton of 1,000 kilos or 40 cubic feet P3.50 P2.35\n(17) General cargo packed in cartons of 40 cubic feet\n3.50\n2.35 (b) Merchandise for export. For handling of merchandise from consignor's transportation upon the pier or wharf to the slings of the exporting vessel:\n(1) General cargo, except as specifically mentioned hereunder per ton of 40 cu. ft. or 1,000 kilos P2.00\n(2) Provided , That there shall be a minimum charge of\n1.00 Provided , That the following shall be subject to the special charges hereunder listed:\na. Automobiles and motor trucks, boxed or unboxed, crated or uncrated, per ton of 40 cu. ft. or 1,000 kilos\n1.00\nb. Coffee in sacks, per ton of 1,000 kilos\n1.00\nc. Flour in sacks, per ton of 1,000 kilos\n1.00\nd. Wood furniture, and wood and metal empty containers, per ton of 40 cu. ft.\n1.00\ne. Bamboo and wicker furniture, per ton of 40 cubic feet\n1.00\nf. Hemp, not in bales, per ton of ,000 kilos\n1.80\ng. Horses, cattle and carabaos, per head\n1.00\nh. Horses, cattle, and carabaos, etc., for breeding and/or exhibition purposes, uncrated, per head\n2.80\ni. Horses, cattle, carabaos, etc., for breeding and/or exhibition purposes, crated, per ton of 40 cubic feet\n1.80\nj. Pigs, sheep, goats, etc., per head\n0.40\nk. Pigs, sheep, goats, etc., for breeding and/or exhibition purposes, uncrated, per head\n1.80\nl. Pigs, sheep, goats, etc., for breeding and/or exhibition purposes, crated, per ton of 40 cu. ft.\n1.80 (c.) Transit Cargo (Import). Transit cargo shall include all merchandise handled over the piers and wharves which is manifested for ports other than Iloilo. The charge of handling transit cargo shall be as that for imported cargo, except as shown below:\n(1) When transit cargo for inter-island ports is loaded onto the forwarding transportation parked and/or onto the forwarding vessel berthed at the time at the same pier or wharf, the rate for placing the same onto the forwarding transportation or onto the slings of the forwarding vessel shall be at per ton of 40 cubic feet or 1,000 kilos P2.50 P1.75\n(2) Provided , That there shall be a minimum charge of\n2.00\n1.35\n(3) When transit cargo for inter-island ports is landed on one pier or wharf and is transferred to another pier or wharf for loading onto the forwarding vessel berthed at the time at the latter pier or wharf, the rate for placing the same onto the transfer transportation furnished by the agent and/or importer, receiving the same from uch transfer for transportation and placing the same into the slings of the forwarding vessel at such other pier or wharf shall be, at per ton of 40 cubic feet or 1,000 kilos\n3.00\n2.00\n(4) Provided, further , That any transit cargo for inter-island ports which remain on pier or wharf for more than ten days after the cargo of the importing vessel from which it was landed has been officially declared or discharged, shall be transferred to the bonded warehouse and treated as any other cargo so transferred\n3.00\n2.00\n(5) The charge of handling transit cargo for foreign ports including service for \"arrastre\", reoccupying or reconditioning of cargo, transfer from pier to pier, and transfer to and from bonded warehouse, shall be at the rate of, per ton of 40 cu. ft. or 1,000 kilos\n8.50\n5.70\n(6) Provided , That the charge for handling of foreign transit cargo less than 40 cu. ft. or 1,000 kilos shall be the same as that for imported cargo.\n(d) Heavy cargo. On any single package or import, export, or transit cargo, weighing more than two tons, handled on a pier or wharf, the charge shall be, per ton or any fraction thereof P8.50 P5.70 Provided , That this charge shall not apply to automobiles, motor trucks and transit cargo for coastwise ports.\n(e) Handling of Baggages. No charge shall be made for the handling of baggages of incoming or outgoing passengers except as follows:\n(1) For baggages regularly manifested as cargo the charge shall be the same as for general imported cargo.\n(2) For animals accompanying passengers, the charge shall be the same as for animals regularly imported or exported.\n(3) For automobiles of incoming or outgoing passengers, the charge shall be the same as for automobiles regularly imported or exported. For any special service on the pier and wharf or in the immediate vicinity thereof in connection with the handling of merchandise, and for the use of electric trucks, tractors and other arrastre equipment:\nSpecial service, per ton of 40 cu. ft. of 1,000 kilos P2.50 This service charge shall not apply to merchandise on which arrastre charge has been paid or secured.\n(f) Hire of Autotrucks. For the use of autotrucks for transferring cargo from one pier to another and/or warehouse, or vice-versa, the charge shall be per ton of 40 cu. ft. or 1,000 kilos\n1.50 (g) Checking Charges. There shall be collected on all cargo falling under Customs Administrative Order Numbered One hundred thirty-seven (old series), as amended, relative to shipside delivery (except coal, lumber, and firebricks in quantities, crude oil, kerosene and gasoline in cases, or in lots of over ten thousand cases or its equivalents and entire cargo of vessels when of one commodity and consigned to one consignee only, when written application for non-checking of such excepted merchandise has been made by the consignee to and approved by the Bureau of Customs) a checking charge as follows:\nPer ton of 40 cu. ft. or 1,000 kilos P0.40 This charge shall be known as a \"checking charge\" and shall be made against import cargo only: Provided , That nothing herein contained shall be so construed as to authorize the collection of arrastre charges other than checking charges on shipside deliveries duly authorized by the Collector of Customs in accordance with Customs Administrative Order Numbered Eighty-four.\n(h) Pier Lighting Service. For lights furnished on pier or wharf for the purpose of working cargo, when loading or unloading vessel or vessels at night:\nFor pier lighting services, per hour P2.25 For cluster lights furnished, per cluster\n0.50\n(i) Water Service. For fresh water furnished to vessel berthed at pier or wharf, per ton\n0.30 (j) Valuable Cargo. The charges for such packages of gold, silver, precious stones, precious metals, jewelries of any kind, bank notes, securities, bullion or specie, or any other cargo whose value is declared at P500 or more shall be:\nFor the first P500 P2.50 For every P500 or fraction thereof thereafter\n2.50 (k) Other Services\n(1) For the use of landing skids, per skid\n15.00\n(2) For the issuance of short-landed certificates, per certificate\n0.40\n(3) For making fast and letting go lines, per berthing\n30.00"}},{"id":"PH-H1205-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"PART V"},"text":{"en":"In all other Ports. The office or agency of the government charged with the supervision, administration and management of all ports in the Philippines, upon the approval of the Department Head, shall fix the rates for the handling, receiving and custody of imported or exported merchandise or the baggages of passengers in all other ports of entry, taking into account the facilities, machinery and equipment available in such port of entry."}},{"id":"PH-H1205-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"PART V"},"text":{"en":"The provisions of sections eleven, twelve, thirteen, fourteen, fifteen, and sixteen to the contrary notwithstanding, the office or agency of the government charged with the supervision, administration and management of all ports in the Philippines, upon prior approval of the Department Head, may increase or decrease the rates fixed therein in any port of the Philippines, by not more than fifty per cent when such increase or decrease is necessary to protect the interest of the government: Provided, however , That nothing herein contained shall be understood to amend, alter or revoke any contract existing at the time this Act becomes effective.\nFinal Provisions"}},{"id":"PH-H1205-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"PART VI"},"text":{"en":"Nothing herein contained shall preclude the agency or office of the government charged with the supervision, administration and management of all ports in the Philippines, upon the approval of the Department Head, from imposing other charges and fees which it may find to be reasonable."}},{"id":"PH-H1205-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"PART VI"},"text":{"en":"The agency or office of the government charged with the supervision, administration and management of all ports in the Philippines, upon approval of the Department Head, shall promulgate all rules and regulations for the collection of all the fees and charges herein provided."}},{"id":"PH-H1205-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"PART VI"},"text":{"en":"Section fourteen of the Philippine Tariff Act of nineteen hundred and nine, as amended; section twelve hundred and fifty-seven and subsections (b) and (c), and paragraphs 1 to 8 of subsection (d) of section fourteen hundred and fourteen of the Revised Administrative Code; Executive Order Numbered Two hundred and fifty-five, dated February twenty-one, nineteen hundred and forty, as amended by Executive Orders Numbered Two hundred seventy, dated April twenty-five, nineteen hundred and forty, and Three hundred sixty-six, dated August thirty, nineteen hundred and forty-one; and Customs Administrative Order Numbered One hundred and ninety, dated December twenty, nineteen hundred and fifty-four, of the Commissioner of Customs, are hereby repealed."}},{"id":"PH-H1205-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"PART VI"},"text":{"en":"This Act shall take effect on July first, nineteen hundred and fifty-five.\nApproved: June 18, 1955"}}],"pack":"ph-p16","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Define, Classify, Fix and Regulate the Amount of All Charges and Fees in Philippine Ports, Other Than Customs Duties, Internal Revenue Taxes and Tonnage Dues","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
